try:
    import redis.asyncio as redis_aio
except ImportError:
    redis_aio = None

_redis_client_inst = None
_redis_failed_until = 0    # Cooldown vor erneutem Verbindungsversuch

async def get_redis():
    """Liefert verbundenen Redis-Client oder None.
       - Cached die Instanz bei Erfolg
       - Bei Fehler: 60s Cooldown bevor wir erneut versuchen
       - Nie Exceptions nach außen — Caller darf einfach None erwarten."""
    global _redis_client_inst, _redis_failed_until
    if _redis_client_inst is not None:
        return _redis_client_inst
    if redis_aio is None:
        return None
    if datetime.now(timezone.utc).timestamp() < _redis_failed_until:
        return None
    try:
        client = redis_aio.from_url(
            REDIS_URL, decode_responses=True,
            socket_timeout=2, socket_connect_timeout=2)
        await client.ping()
        _redis_client_inst = client
        log.info(f"Redis verbunden: {REDIS_URL}")
        return client
    except Exception as e:
        log.warning(f"Redis nicht erreichbar ({REDIS_URL}): {e}")
        _redis_failed_until = datetime.now(timezone.utc).timestamp() + 60
        return None

async def redis_get_json(key: str):
    r = await get_redis()
    if r is None: return None
    try:
        v = await r.get(key)
        return json.loads(v) if v else None
    except Exception as e:
        log.debug(f"redis_get_json({key}) failed: {e}")
        return None

async def redis_set_json(key: str, value, ttl: int = None):
    r = await get_redis()
    if r is None: return
    try:
        await r.set(key, json.dumps(value, ensure_ascii=False), ex=ttl)
    except Exception as e:
        log.debug(f"redis_set_json({key}) failed: {e}")

# ---------- Ollama-Client ----------
# FIX (Header "Was offen bleibt"): vorher erzeugte JEDER llm_chat()/
# llm_list_models()-Aufruf eine neue aiohttp.ClientSession — TCP-Handshake
# + TLS-Setup-Overhead bei jedem AI-Call statt einmaliger gepoolter Verbindung.
# Lazy-initialisierte, modul-globale Session analog zum get_redis()-Pattern
# oben. Wird beim Bot-Shutdown explizit geschlossen (siehe shutdown-Pfad).
_AI_SESSION: Optional["aiohttp.ClientSession"] = None
_AI_SESSION_LOCK: Optional[asyncio.Lock] = None

async def _get_ai_session() -> "aiohttp.ClientSession":
    global _AI_SESSION, _AI_SESSION_LOCK
    if _AI_SESSION_LOCK is None:
        _AI_SESSION_LOCK = asyncio.Lock()
    async with _AI_SESSION_LOCK:
        if _AI_SESSION is None or _AI_SESSION.closed:
            _AI_SESSION = aiohttp.ClientSession(
                connector=aiohttp.TCPConnector(limit=10, limit_per_host=4,
                                               keepalive_timeout=60))
        return _AI_SESSION

async def _close_ai_session():
    """Beim Bot-Shutdown aufrufen, damit die gepoolte Session nicht als
    'Unclosed client session'-Warnung im Log landet."""
    global _AI_SESSION
    if _AI_SESSION is not None and not _AI_SESSION.closed:
        try:
            await _AI_SESSION.close()
        except Exception:
            pass
        _AI_SESSION = None


async def llm_chat(messages: List[dict],
                   model: Optional[str] = None,
                   timeout: Optional[float] = None) -> Tuple[Optional[str], Optional[str]]:
    """Zentraler Text-Chat (V37, ollama-frei). Kette: Brain-Runtime (lokales
       llama.cpp, wenn AI_PROVIDER=brain) → nc.freeai (keyless Cloud).
       Vertrag unverändert: (text, error_kind). Vision-Anfragen (images) gehen
       direkt an freeai — die Brain-Runtime ist text-only."""
    timeout = AI_TIMEOUT if timeout is None else timeout
    # v4.0-W64: Claude zuerst, sobald ein Anthropic-Key gesetzt ist. Auth-Fehler
    # NICHT still verschlucken (der Betreiber soll den falschen Key merken);
    # transiente Fehler (rate/unreachable) fallen auf die keyless Kette zurück.
    _akey = _anthropic_key()
    if _akey and not any(m.get("images") for m in messages):
        _txt, _err = await asyncio.to_thread(
            _nc_claude.chat_sync, messages, _akey, _anthropic_model(model),
            timeout if (timeout and timeout > 0) else 60)
        if _txt:
            return (_txt, None)
        if _err == "auth":
            return (None, "auth")
        log.debug("Claude ohne Antwort (%s) — Fallback-Kette", _err)
    if (os.getenv("AI_PROVIDER", "").strip().lower() == "brain"
            and not any(m.get("images") for m in messages)):
        try:
            from brain import get_brain
            _res = await asyncio.to_thread(
                get_brain().llm.chat, messages,
                timeout if (timeout and timeout > 0) else 3600)
            if _res.get("ok"):
                return (_res["text"], None)
            log.debug("Brain-LLM ohne Antwort (%s) — freeai-Fallback",
                      _res.get("error"))
        except Exception as _e:
            log.debug("Brain-LLM-Pfad nicht verfügbar (%s) — freeai-Fallback", _e)
    return await _nc_freeai.chat(messages, model=model, timeout=timeout)


_LLM_MODELS_CACHE = {"ts": 0.0, "models": []}




async def llm_list_models() -> Optional[List[str]]:
    """Modell-Liste: Brain-Backend (llama.cpp) zuerst, sonst freeai-Basen."""
    try:
        from brain import get_brain
        m = await asyncio.to_thread(get_brain().llm.models)
        if m:
            return m
    except Exception:
        pass
    try:
        return await asyncio.to_thread(_nc_freeai.list_models_sync) or None
    except Exception:
        return None


def llm_chat_sync(messages, model=None, timeout=None):
    """Blockierender Chat für Flask-Routen/Threads. Brain → freeai."""
    timeout = AI_TIMEOUT if timeout is None else timeout
    # v4.0-W64: Claude zuerst (Dashboard/ENV-Key), sonst Brain → keyless.
    _akey = _anthropic_key()
    if _akey:
        _txt, _err = _nc_claude.chat_sync(messages, _akey, _anthropic_model(model),
                                          timeout if (timeout and timeout > 0) else 60)
        if _txt:
            return (_txt, None)
        if _err == "auth":
            return (None, "auth")
    if os.getenv("AI_PROVIDER", "").strip().lower() == "brain":
        try:
            from brain import get_brain
            _res = get_brain().llm.chat(
                messages, timeout if (timeout and timeout > 0) else 3600)
            if _res.get("ok"):
                # v4.0-W93: Brain-LLM (llama.cpp) liefert keine Tokens → schätzen.
                try:
                    _nc_usage.record("brain", "llama.cpp",
                                     _nc_usage.estimate_tokens(messages),
                                     _nc_usage.estimate_tokens(_res.get("text", "")))
                except Exception:
                    pass
                return (_res["text"], None)
        except Exception:
            pass
    return _nc_freeai.chat_sync(messages, model=model, timeout=timeout)




def _check_ai_alive_sync(timeout: float = 1.5) -> bool:
    """Health: Brain-Backend (llama.cpp) ODER freeai erreichbar?"""
    try:
        from brain import get_brain
        if get_brain().llm.alive():
            return True
    except Exception:
        pass
    try:
        return _nc_freeai.alive_sync(timeout=max(2.0, timeout))
    except Exception:
        return False


def _check_ai_models_sync(timeout: float = 1.5):
    """Modell-Liste (sync) für System-Panels: Brain zuerst, sonst freeai."""
    try:
        from brain import get_brain
        m = get_brain().llm.models()
        if m:
            return m
    except Exception:
        pass
    try:
        return _nc_freeai.list_models_sync(timeout=max(3.0, timeout)) or []
    except Exception:
        return []







# ---------- Live-Streaming des Ollama-Chats (SSE) ----------------------------
# WARUM: Der blockierende ollama_chat_sync hat ein Socket-Timeout → bei langsamem
# CPU-Modell (Laden/Denken) bricht die Anfrage ab. Streaming hält die Verbindung,
# solange Tokens fließen; das Frontend zeigt Laden→Denken→Antwort live an.


async def ai_chat(messages, model=None, timeout=None):
    """Einheitlicher Chat für die Reaction Engine. Default-Provider 'pollinations' (KOSTENLOS,
       KEIN API-Key, nc.freeai mit Basen-Rotation)."""
    if not _ai_backend_logged["done"]:
        _ai_backend_logged["done"] = True
        log.info("Reaction-AI Backend: provider=%s, model=%s (keyless via nc.freeai%s)",
                 REACTION_AI_PROVIDER, REACTION_AI_MODEL,
                 " + Brain-Runtime" if REACTION_AI_PROVIDER in ("brain","llamacpp") else "")
    # V37-B92: Zeitbudget IMMER begrenzen — die Reaction-Engine läuft in der
    # live-react-Loop; ein hängendes Backend darf sie nie blockieren.
    timeout = timeout if (timeout and timeout > 0) else REACTION_AI_TIMEOUT
    # v4.0-W65: Claude zuerst, sobald ein Anthropic-Key gesetzt ist (auch die
    # Reaction-Engine läuft dann über Claude). Auth-Fehler → keine stille
    # Rückkehr auf keyless; transiente Fehler fallen auf die Kette zurück.
    _akey = _anthropic_key()
    if _akey and not any(m.get("images") for m in messages):
        # v4.1-W13: den ECHTEN Grund einsammeln. Vorher stand im Log 26 Mal
        # "fehlgeschlagen (bad_request)" und kein einziges Mal, WAS am Request
        # schlecht war — obwohl die API es jedes Mal mitschickt. Der Rueckruf
        # laeuft im Thread von chat_sync; er darf deshalb nur schreiben, nicht
        # blockieren.
        _cdetail = {}
        def _claude_grund(kind, detail, modell):
            _cdetail["kind"], _cdetail["detail"], _cdetail["model"] = kind, detail, modell
        _ctxt, _cerr = await asyncio.to_thread(
            _nc_claude.chat_sync, messages, _akey, _anthropic_model(model), timeout,
            on_error=_claude_grund)
        if _ctxt:
            return (_ctxt, None)
        if _cerr == "auth":
            return (None, "auth")
        _react_warn("claudefb", "Reaction-AI Claude fehlgeschlagen (%s) → Kette. "
                    "Modell=%s, Antwort der API: %s"
                    % (_cerr, _cdetail.get("model") or "?",
                       _cdetail.get("detail") or "kein Text mitgeliefert"))
    # V37-B92: provider=brain → llama.cpp-Runtime (Ollama ist auf den 8 Kernen
    # messbar langsamer). Fail-open-Kette: brain → ollama.
    if REACTION_AI_PROVIDER in ("brain", "llamacpp"):
        try:
            from brain import get_brain
            _res = await asyncio.wait_for(
                asyncio.to_thread(get_brain().llm.chat, messages, timeout),
                timeout=timeout + 10)
            if _res.get("ok"):
                return (_res["text"], None)
            _react_warn("brainfb", "Reaction-AI brain fehlgeschlagen (%s) → freeai."
                        % _res.get("error"))
        except Exception as _e:
            _react_warn("brainfb", "Reaction-AI brain-Pfad: %s → freeai." % _e)
    # V37: einziger Cloud-Pfad = nc.freeai (keyless, Basen-Rotation, 429-Backoff)
    return await _nc_freeai.chat(messages, model=model or REACTION_AI_MODEL,
                                 timeout=timeout)


AI_STREAM_TIMEOUT = _env_int("AI_STREAM_TIMEOUT", 900)   # nur greifend bei TOTALER Stille




async def ai_rate_limit_check(user_id: int) -> bool:
    """True = Anfrage darf weiter, False = Limit erreicht.
       Ohne Redis: kein Limit (degraded)."""
    r = await get_redis()
    if r is None: return True
    key = f"ai_rl:{user_id}"
    try:
        n = await r.incr(key)
        if n == 1:
            await r.expire(key, 60)
        return n <= AI_RATE_LIMIT_PER_MIN
    except Exception as e:
        log.debug(f"ai_rate_limit_check: {e}")
        return True

async def ai_history_load(chat_id: int, user_id: int) -> List[dict]:
    r = await get_redis()
    if r is None: return []
    key = f"ai_hist:{chat_id}:{user_id}"
    try:
        items = await r.lrange(key, 0, -1)
        return [json.loads(x) for x in items]
    except Exception as e:
        log.debug(f"ai_history_load: {e}")
        return []

async def ai_history_append(chat_id: int, user_id: int, role: str, content: str):
    r = await get_redis()
    if r is None: return
    key = f"ai_hist:{chat_id}:{user_id}"
    try:
        await r.rpush(key, json.dumps({"role": role, "content": content}))
        # nur die letzten N Turns (1 Turn = user + assistant) behalten
        await r.ltrim(key, -AI_HISTORY_TURNS * 2, -1)
        await r.expire(key, AI_HISTORY_TTL)
    except Exception as e:
        log.debug(f"ai_history_append: {e}")

async def ai_history_clear(chat_id: int, user_id: int):
    r = await get_redis()
    if r is None: return
    try:
        await r.delete(f"ai_hist:{chat_id}:{user_id}")
    except Exception: pass

