def start_recording_attempt(tracking_id, username, recorder):
    """F19: legt einen neuen Attempt-Eintrag an. Returns die ID für späteres Update."""
    try:
        with db_conn() as conn:
            cur = conn.execute(
                "INSERT INTO recording_attempts "
                "(tracking_id, username, recorder, started_at, outcome) "
                "VALUES (?,?,?,?,?)",
                (tracking_id, username, recorder,
                 datetime.now(timezone.utc).isoformat(), "running"))
            conn.commit()
            return cur.lastrowid
    except Exception as e:
        log.warning(f"start_recording_attempt failed: {e}")
        return None

def finish_recording_attempt(attempt_id, *, returncode=None, file_path=None,
                             file_size=None, outcome="ok", stderr_tail=None,
                             error=None, duration_secs=None):
    if attempt_id is None: return
    try:
        with db_conn() as conn:
            conn.execute(
                "UPDATE recording_attempts SET "
                "ended_at=?, duration_secs=?, returncode=?, file_path=?, "
                "file_size=?, outcome=?, stderr_tail=?, error=? WHERE id=?",
                (datetime.now(timezone.utc).isoformat(),
                 duration_secs, returncode, file_path, file_size,
                 outcome, (stderr_tail or "")[:2000] if stderr_tail else None,
                 error, attempt_id))
            conn.commit()
    except Exception as e:
        log.warning(f"finish_recording_attempt failed: {e}")

