def get_last_recording_attempt(tid):
    """F22: liefert (outcome, recorder) der letzten Aufnahme für ein Tracking,
       oder None,None wenn noch keine. Wird genutzt um zu entscheiden ob
       der nächste Versuch auf 'native_api' gepinned werden soll."""
    try:
        with db_conn() as conn:
            row = conn.execute(
                "SELECT outcome, recorder FROM recording_attempts "
                "WHERE tracking_id=? ORDER BY id DESC LIMIT 1",
                (tid,)).fetchone()
            if row:
                return row["outcome"], row["recorder"]
    except Exception as e:
        log.debug(f"get_last_recording_attempt: {e}")
    return None, None

def decide_preferred_recorder(tid: int) -> Optional[str]:
    """F22: vor jedem Recording-Start: war der letzte Versuch ein Fehler?
       Wenn ja UND nicht schon native+api → forciere native+api für dieses Mal.
       Wenn native+api selbst gescheitert ist → kein Pinning (sonst Endlosschleife).
       F40: 'stall_killed_partial' zählt als Teilerfolg (File wurde gespeichert,
       Stream-URL ist nur expired) → keine Recorder-Änderung nötig."""
    outcome, recorder = get_last_recording_attempt(tid)
    if not outcome or outcome in ("ok", "running", "stall_killed_partial"):
        return None    # Letzter war erfolgreich oder es gibt keinen → auto
    if recorder == "native+api":
        return None    # native+api ist gerade gescheitert → nicht erneut pinnen
    return "native_api"

