# ---------- X18: Manual Recording ----------
_MANUAL_RECORDINGS = {}    # manual_id -> asyncio.subprocess.Process

async def trigger_manual_recording(username: str, duration_secs: int = 300,
                                     session=None) -> dict:
    """Startet eine manuelle Aufnahme (max 5min default). Läuft parallel
       zur normalen Worker-Pipeline. Wird in eigener Tabelle gespeichert.
       Triggered from /api/recordings/manual/start."""
    username = clean_username(username)
    if not username:
        return {"ok": False, "error": "ungültiger username"}
    duration_secs = max(10, min(int(duration_secs or 300), 3600))

    # File-Path
    ts = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
    output_file = os.path.join(
        RECORDINGS_DIR, f"manual_{username}_{ts}.mp4")

    # DB-Entry anlegen
    try:
        with db_conn() as conn:
            cur = conn.execute(
                "INSERT INTO manual_recordings "
                "(username, max_duration_secs, started_at, output_file, status) "
                "VALUES (?,?,?,?,?)",
                (username, duration_secs,
                 datetime.now(timezone.utc).isoformat(),
                 output_file, "starting"))
            conn.commit()
            manual_id = cur.lastrowid
    except Exception as e:
        return {"ok": False, "error": f"db: {e}"}

    # Build recording cmd
    try:
        cmd, recorder = await build_recording_cmd(
            username, output_file, duration_secs, session=session)
    except Exception as e:
        try:
            with db_conn() as conn:
                conn.execute(
                    "UPDATE manual_recordings SET status='failed', "
                    "ended_at=? WHERE id=?",
                    (datetime.now(timezone.utc).isoformat(), manual_id))
                conn.commit()
        except Exception: pass
        return {"ok": False, "error": f"build_cmd: {e}", "manual_id": manual_id}
    if cmd is None:
        try:
            with db_conn() as conn:
                conn.execute(
                    "UPDATE manual_recordings SET status='resolve_failed', "
                    "ended_at=? WHERE id=?",
                    (datetime.now(timezone.utc).isoformat(), manual_id))
                conn.commit()
        except Exception: pass
        return {"ok": False, "error": "kein Recorder verfügbar / nicht live",
                "manual_id": manual_id}

    # Spawn
    try:
        proc = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=asyncio.subprocess.DEVNULL,
            stderr=asyncio.subprocess.PIPE)
    except Exception as e:
        try:
            with db_conn() as conn:
                conn.execute(
                    "UPDATE manual_recordings SET status='spawn_failed', "
                    "ended_at=? WHERE id=?",
                    (datetime.now(timezone.utc).isoformat(), manual_id))
                conn.commit()
        except Exception: pass
        return {"ok": False, "error": f"spawn: {e}", "manual_id": manual_id}

    try:
        with db_conn() as conn:
            conn.execute(
                "UPDATE manual_recordings SET status='running', recorder_pid=? "
                "WHERE id=?", (proc.pid, manual_id))
            conn.commit()
    except Exception: pass

    _MANUAL_RECORDINGS[manual_id] = proc
    log_event("manual.recording.start", "info",
              f"Manual recording @{username} for {duration_secs}s (id={manual_id})",
              {"manual_id": manual_id, "username": username,
               "duration": duration_secs, "recorder": recorder})

    # Background-Task: wartet auf Exit, updated den Eintrag
    async def _wait_and_finish():
        # BUG-FIX: stderr_bytes war als unused variable vorhanden — bei status="empty"
        # (Aufnahme endete mit leerer Datei) ist stderr der einzige Hinweis auf den Fehler.
        # Jetzt: im DB-Eintrag und im log_event gespeichert.
        _stderr_tail = ""
        try:
            try:
                _, stderr_bytes = await asyncio.wait_for(
                    proc.communicate(), timeout=duration_secs + 60)
                if stderr_bytes:
                    _stderr_tail = _ffmpeg_stderr_tail(
                        stderr_bytes.decode(errors="ignore"), max_len=400)
            except asyncio.TimeoutError:
                try: proc.kill()
                except Exception: pass
                try: await proc.communicate()
                except Exception: pass
        except Exception:
            pass
        finally:
            _MANUAL_RECORDINGS.pop(manual_id, None)
            file_size = None
            if os.path.exists(output_file):
                try: file_size = os.path.getsize(output_file)
                except OSError: pass
            status = "completed" if (file_size and file_size > 1024) else "empty"
            try:
                with db_conn() as conn:
                    conn.execute(
                        "UPDATE manual_recordings SET status=?, ended_at=?, file_size=? "
                        "WHERE id=?",
                        (status, datetime.now(timezone.utc).isoformat(),
                         file_size, manual_id))
                    conn.commit()
            except Exception: pass
            log_event("manual.recording.end", "info" if status == "completed" else "warning",
                      f"Manual #{manual_id} @{username} → {status} ({(file_size or 0)/1024/1024:.1f} MB)"
                      + (f" | stderr: {_stderr_tail[:200]}" if status == "empty" and _stderr_tail else ""),
                      {"manual_id": manual_id, "status": status, "file_size": file_size,
                       "stderr_tail": _stderr_tail[:400] if status == "empty" else ""})

    _spawn(_wait_and_finish(), name=f"manual-rec-{manual_id}")

    return {"ok": True, "manual_id": manual_id, "output_file": output_file,
            "recorder": recorder, "duration_secs": duration_secs}

def stop_manual_recording(manual_id: int) -> dict:
    proc = _MANUAL_RECORDINGS.get(manual_id)
    if proc is None:
        return {"ok": False, "error": "manual recording not running"}
    # BUG-FIX: proc ist ein asyncio-Subprocess — .terminate() manipuliert den
    # Transport und MUSS auf dem Event-Loop-Thread laufen. Diese Funktion wird
    # aber aus dem Flask-Thread aufgerufen. Vorher: direkter proc.terminate()
    # cross-thread → undefiniertes Verhalten / mögliche Transport-Errors.
    # Jetzt: auf den Main-Loop schedulen.
    try:
        if _MAIN_LOOP is not None and _MAIN_LOOP.is_running():
            _MAIN_LOOP.call_soon_threadsafe(proc.terminate)
            return {"ok": True}
        # Fallback: Loop nicht verfügbar → direkter Kill via PID (thread-safe)
        proc.terminate()
        return {"ok": True}
    except Exception as e:
        return {"ok": False, "error": str(e)}

