# ---------- X24: Stream-URL-Inspector (live test) ----------
async def inspect_stream_url(username: str, session=None) -> dict:
    """Probiert resolve_tiktok_live_stream und prüft die HLS-URL via HTTP HEAD.
       Liefert: ttfb, headers, resolved-format etc."""
    username = clean_username(username)
    if not username:
        return {"ok": False, "error": "ungültiger username"}
    started = _time_mod.monotonic()
    own_session = False
    if session is None:
        session = aiohttp.ClientSession()
        own_session = True
    try:
        info = await resolve_tiktok_live_stream(username, session, mode="auto")
        resolve_ms = int((_time_mod.monotonic() - started) * 1000)
        if not info:
            return {"ok": False, "error": "resolver returned None",
                    "resolve_ms": resolve_ms}
        url = info.get("hls_url") or info.get("flv_url")
        if not url:
            return {"ok": False, "error": "no playable URL in resolve",
                    "resolve_ms": resolve_ms,
                    "resolved": {"via": info.get("via")}}
        # HEAD request für TTFB
        head_started = _time_mod.monotonic()
        head_info = None
        try:
            async with session.get(url, headers=_LIVE_RESOLVER_HEADERS,
                                    timeout=aiohttp.ClientTimeout(total=10),
                                    allow_redirects=True) as resp:
                head_info = {
                    "status": resp.status,
                    "content_type": resp.headers.get("Content-Type"),
                    "content_length": resp.headers.get("Content-Length"),
                    "ttfb_ms": int((_time_mod.monotonic() - head_started) * 1000),
                }
                if resp.status == 200 and ".m3u8" in url.lower():
                    # m3u8-Playlist anschauen
                    text = await resp.text()
                    head_info["m3u8_lines"] = text.count("\n")
                    head_info["m3u8_segments"] = text.count(".ts")
        except Exception as e:
            head_info = {"error": str(e)}
        return {
            "ok": True,
            "username": username,
            "resolve_ms": resolve_ms,
            "via": info.get("via"),
            "hls_url": info.get("hls_url"),
            "flv_url": info.get("flv_url"),
            "url_test": head_info,
        }
    finally:
        if own_session:
            try: await session.close()
            except Exception: pass

