# ============================================================
# F47: Storage-Stats + Auto-Cleanup
# ============================================================
# Disk fills up over time because handle_recording_finished löscht erfolgreich
# hochgeladene Recording-Files NICHT von Disk (Design-Entscheidung — User
# soll lokale Kopie behalten). Wir bieten jetzt:
# 1. Sichtbarkeit: get_storage_stats() → Dashboard-Widget
# 2. Opt-in Auto-Cleanup: RECORDINGS_RETAIN_DAYS env var
# Beide arbeiten gegen den RECORDINGS_DIR und sind unabhängig vom Archive
# (Archive ist explizit vom User gepflegt).

RECORDINGS_RETAIN_DAYS = _env_int("RECORDINGS_RETAIN_DAYS", 0)
# 0 = nie auto-löschen (Default — safest). >0 = nach N Tagen löschen.


def get_storage_stats() -> dict:
    """Dashboard-Widget-Daten. Liefert Recordings + Archive + freier Platz."""
    rec_stats = _dir_stats(RECORDINGS_DIR)
    arch_stats = _dir_stats(ARCHIVE_DIR) if ARCHIVE_DIR else {"exists": False}
    # Freier Platz auf der Disk wo RECORDINGS_DIR liegt
    try:
        st = shutil.disk_usage(RECORDINGS_DIR if os.path.isdir(RECORDINGS_DIR) else ".")
        # B1-Fix: used_percent ergänzen. api_health_score und api_ai_diagnose
        # haben das Feld erwartet, fanden es aber nie — Disk-Component im
        # Health-Score blieb deshalb permanent bei 70/100 mit Note "?".
        used_pct = round(st.used / st.total * 100, 1) if st.total else None
        disk = {"total_bytes": st.total, "used_bytes": st.used,
                "free_bytes": st.free, "used_percent": used_pct}
    except Exception as e:
        log.warning(f"disk_usage failed: {e}")
        disk = {"total_bytes": None, "used_bytes": None,
                "free_bytes": None, "used_percent": None}
    # DB-Count der Recording-Einträge (Datei evt. gelöscht aber DB-Eintrag bleibt)
    try:
        with db_conn() as conn:
            db_count = conn.execute("SELECT COUNT(*) AS c FROM recordings").fetchone()
            db_count = db_count["c"] if db_count else 0
    except Exception as e:
        log.warning(f"recordings count failed: {e}")
        db_count = None
    return {
        "recordings_dir": rec_stats,
        "archive_dir":    arch_stats,
        "disk":           disk,
        "db_recording_count": db_count,
        "retention_days": RECORDINGS_RETAIN_DAYS,
    }

def cleanup_old_recordings(days: int = None, dry_run: bool = False) -> dict:
    """Löscht Recordings-Files älter als `days` Tage von Disk. DB-Einträge
       werden NICHT gelöscht (User kann immer noch sehen dass es Aufnahmen
       gab — sie sind nur nicht mehr abrufbar). Wenn dry_run=True: zählt nur.

       Aufrufer: hourly background task (wenn RECORDINGS_RETAIN_DAYS > 0)
       oder manueller Dashboard-Button."""
    if days is None:
        days = RECORDINGS_RETAIN_DAYS
    if days <= 0:
        return {"deleted": 0, "freed_bytes": 0, "skipped": 0, "errors": 0,
                "reason": "RECORDINGS_RETAIN_DAYS=0 (cleanup disabled)"}
    if not os.path.isdir(RECORDINGS_DIR):
        return {"deleted": 0, "freed_bytes": 0, "skipped": 0, "errors": 0,
                "reason": f"{RECORDINGS_DIR} does not exist"}
    cutoff = _time_mod.time() - (days * 86400)
    deleted = 0; freed = 0; skipped = 0; errors = 0
    try:
        for entry in os.scandir(RECORDINGS_DIR):
            if not entry.is_file(follow_symlinks=False):
                continue
            try:
                st = entry.stat(follow_symlinks=False)
            except OSError:
                errors += 1; continue
            if st.st_mtime >= cutoff:
                skipped += 1; continue
            if dry_run:
                deleted += 1; freed += st.st_size
                continue
            try:
                os.remove(entry.path)
                deleted += 1; freed += st.st_size
            except OSError as e:
                log.warning(f"cleanup_old_recordings: {entry.path}: {e}")
                errors += 1
    except OSError as e:
        log.warning(f"cleanup_old_recordings scandir: {e}")
        return {"deleted": deleted, "freed_bytes": freed, "skipped": skipped,
                "errors": errors + 1, "error": str(e)}
    return {"deleted": deleted, "freed_bytes": freed, "skipped": skipped,
            "errors": errors, "dry_run": dry_run, "retain_days": days}


# ============================================================
# F48: Per-User-Statistiken
# ============================================================
# Für Dashboard-Widget + /topusers Telegram-Command. Aggregiert über
# recording_attempts (Erfolgs-Rate, Dauer) und recordings (Anzahl/Größe).



# ============================================================
# F57: Recording-Outcome-Breakdown
# ============================================================
# Aggregiert recording_attempts nach outcome über ein Zeitfenster.
# Hilft beim Spotten von Trends: "wieso scheitern in letzter Zeit so
# viele Aufnahmen? — ah, 80% early_disconnect, also TikTok-CDN-Problem."
# Default-Window 24h, alternatv 7d via API-Param.

# Bekannte Outcomes mit Label + Status-Klasse für die UI.
# Reihenfolge bestimmt die Anzeige (häufigste/wichtigste zuerst).
_OUTCOME_META = {
    "ok":                    ("OK",                 "good"),
    "stall_killed_partial":  ("OK (Stall, partial)","warn"),
    "early_disconnect":      ("Early Disconnect",   "bad"),
    "stall_killed":          ("Stall (kill, 0B)",   "bad"),
    "codec_header_fail":     ("Codec/Input-Fehler", "bad"),   # B59
    "hevc_unsupported":      ("HEVC – ffmpeg-Update nötig", "bad"),  # B64
    "stream_dead":           ("Stream Dead (404)",  "bad"),   # B43
    "resolve_failed":        ("Resolve Failed",     "bad"),
    "start_failed":          ("Start Failed",       "bad"),
    "fail":                  ("Fail (sonstig)",     "bad"),
    "running":               ("Running",            "muted"),
}

def get_outcome_breakdown(hours: int = 24) -> dict:
    """Returns {total, since_iso, by_outcome:[{key,label,status,count,pct}],
                top_failing_users:[{username, fail_count}], early_disconnect_users:[...]}.
       hours: Zeitfenster (max 168 = 7 Tage)."""
    hours = max(1, min(int(hours or 24), 168))
    since = (datetime.now(timezone.utc) - timedelta(hours=hours)).isoformat()

    with db_conn() as conn:
        rows = conn.execute(
            "SELECT outcome, COUNT(*) AS c FROM recording_attempts "
            "WHERE started_at >= ? GROUP BY outcome ORDER BY c DESC",
            (since,)).fetchall()
        total = sum(r["c"] for r in rows)
        # F57: Top User mit Failures (alles außer ok/partial)
        top_fail = conn.execute(
            "SELECT username, COUNT(*) AS c FROM recording_attempts "
            "WHERE started_at >= ? "
            "AND outcome NOT IN ('ok', 'stall_killed_partial', 'running') "
            "GROUP BY username ORDER BY c DESC LIMIT 5",
            (since,)).fetchall()
        # F57: Top User mit early_disconnect (das ist der TikTok-Pain-Point)
        top_ed = conn.execute(
            "SELECT username, COUNT(*) AS c FROM recording_attempts "
            "WHERE started_at >= ? AND outcome = 'early_disconnect' "
            "GROUP BY username ORDER BY c DESC LIMIT 5",
            (since,)).fetchall()

    by_outcome = []
    for r in rows:
        key = r["outcome"] or "unknown"
        label, status = _OUTCOME_META.get(key, (key, "muted"))
        pct = round(r["c"] / total * 100, 1) if total else 0
        by_outcome.append({"key": key, "label": label, "status": status,
                           "count": r["c"], "pct": pct})

    return {
        "total":      total,
        "hours":      hours,
        "since":      since,
        "by_outcome": by_outcome,
        "top_failing_users": [{"username": r["username"], "fail_count": r["c"]}
                              for r in top_fail],
        "early_disconnect_users": [{"username": r["username"], "count": r["c"]}
                                    for r in top_ed],
    }

