# Authorization
# -----------------------------
def _is_authorized(update: Update) -> bool:
    if not ALLOWED_USER_IDS and not ALLOWED_CHAT_IDS:
        return True   # open mode
    uid = update.effective_user.id if update.effective_user else None
    cid = update.effective_chat.id if update.effective_chat else None
    if ALLOWED_USER_IDS and uid in ALLOWED_USER_IDS:
        return True
    if ALLOWED_CHAT_IDS and cid in ALLOWED_CHAT_IDS:
        return True
    return False

def _can_stop_tracking(update: Update, chat_id: int, username: str) -> tuple:
    """F24: Darf der User dieses Tracking stoppen?
       1. Admin (in ALLOWED_USER_IDS) → ja
       2. Wenn ALLOWED_USER_IDS leer UND User hat das Tracking selbst angelegt → ja
       3. Sonst → nein
       Returns (allowed, reason_if_denied)."""
    uid = update.effective_user.id if update.effective_user else None
    if uid is None:
        return False, "kein User"
    # 1. Admin-Liste hat Vorrang
    if ALLOWED_USER_IDS:
        if uid in ALLOWED_USER_IDS:
            return True, None
        return False, "Nur der konfigurierte Admin darf Trackings stoppen."
    # 2. Open-Mode: nur der Original-Tracker darf
    try:
        with db_conn() as conn:
            row = conn.execute(
                "SELECT added_by FROM trackings WHERE group_id=? AND username=?",
                (chat_id, username)).fetchone()
            if row and row["added_by"] == uid:
                return True, None
            if not row:
                return False, "Tracking nicht gefunden."
            return False, "Nur der User der das Tracking angelegt hat darf es stoppen."
    except Exception as e:
        log.warning(f"_can_stop_tracking lookup: {e}")
        return False, "Fehler beim Berechtigungs-Check."

