async def tiktok(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not _is_authorized(update): return
    if not context.args:
        await update.message.reply_text(_nc_i18n.t("Bitte: <code>/tiktok username</code>"),
                                        parse_mode=ParseMode.HTML); return
    username = clean_username(context.args[0])
    if not username:
        await update.message.reply_text(_nc_i18n.t("⚠️ Ungültiger Username.")); return
    msg = await update.message.reply_text(_nc_i18n.t("⏳ <i>Analysiere TikTok-Profil…</i>"),
                                          parse_mode=ParseMode.HTML)
    scraper: TikTokScraper = context.application.bot_data["scraper"]
    try:
        # F14: Profile-Cache via Redis (60s TTL) — entlastet TikTok bei
        # häufigen Lookups desselben Users.
        cache_key = f"profile:{username}"
        data = await redis_get_json(cache_key)
        if data is None:
            data = await scraper.fetch_profile(username)
            if data.get("ok"):
                await redis_set_json(cache_key, data, ttl=PROFILE_CACHE_TTL)
        info = await _get_live_info(username, session=scraper.session)
        # F33: None bedeutet "unbekannt" — wir behandeln das hier wie 'offline'
        # für die Anzeige, aber loggen es separat
        if info["is_live"] is None:
            log.info(f"/tiktok @{username}: live-status nicht ermittelbar")
            info = {"is_live": False, "info": None}
        if not data.get("ok"):
            await msg.edit_text(
                f"⚠️ <b>FEHLER · @{safe(username)}</b>\n"
                f"<i>{safe(str(data.get('error')))}</i>",
                parse_mode=ParseMode.HTML); return
        save_tiktok_check(update.effective_user.id, username, data)
        await msg.edit_text(
            _nc_i18n.t(build_report(data, info)),
            parse_mode=ParseMode.HTML,
            disable_web_page_preview=True,
            reply_markup=profile_keyboard(username, info.get("is_live", False)))
    except Exception as e:
        log.exception(f"/tiktok @{username} failed")
        await msg.edit_text(
            _nc_i18n.t(f"⚠️ <b>FEHLER · @{safe(username)}</b>\n<i>{safe(str(e))}</i>"),
            parse_mode=ParseMode.HTML)

