async def track_exact(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """B125: /track_exact <name> — Handle WOERTLICH uebernehmen, ohne
    URL-Erkennung.

    Notwendig geworden durch "@www.tiktok.comrabi1978": ein GUELTIGER
    TikTok-Handle (22 Zeichen, nur Buchstaben/Ziffern/Punkte), der
    offenkundig genau so gewaehlt wurde, dass jede automatische
    URL-Erkennung ihn zerlegt. Fuer solche Namen braucht es einen Weg,
    der gar nicht erst interpretiert.
    """
    if not _is_authorized(update): return
    if not context.args:
        await update.message.reply_text(
            "Benutzung: <code>/track_exact name</code>\n"
            "<i>Nimmt den Namen buchstabengetreu — keine URL-Erkennung. "
            "Für Handles, die wie eine URL aussehen.</i>",
            parse_mode=ParseMode.HTML); return
    name = context.args[0].strip().lstrip("@")
    if not is_valid_tiktok_username(name):
        await update.message.reply_text(
            f"⚠️ <code>{safe(name)}</code> kann kein TikTok-Handle sein.\n"
            "<i>Erlaubt: 2–24 Zeichen, nur Buchstaben, Ziffern, Punkt und "
            "Unterstrich; kein Punkt am Ende.</i>",
            parse_mode=ParseMode.HTML); return
    gid = update.effective_chat.id
    if add_tracking(gid, name, update.effective_user.id):
        await update.message.reply_text(
            _nc_i18n.t(f"✅ <b>@{safe(name)}</b> wird getrackt <i>(wörtlich übernommen)</i>."),
            parse_mode=ParseMode.HTML)
    else:
        await update.message.reply_text(
            _nc_i18n.t(f"ℹ️ <b>@{safe(name)}</b> wird bereits getrackt."),
            parse_mode=ParseMode.HTML)


async def track(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not _is_authorized(update): return
    if not context.args:
        await update.message.reply_text(_nc_i18n.t("Benutzung: <code>/track @username</code>"),
                                        parse_mode=ParseMode.HTML); return
    _raw_in = context.args[0]
    username = clean_username(_raw_in)
    if not username:
        await update.message.reply_text(_nc_i18n.t("⚠️ Ungültiger Username.")); return
    # B125: Hat clean_username den Namen VERAENDERT, das sichtbar machen.
    # Anlass war "@www.tiktok.comrabi1978" — ein echter Handle, der wie eine
    # URL aussieht. Wer so einen Namen tippt, soll sofort sehen, ob der Bot
    # ihn verstanden oder umgedeutet hat, statt es Wochen spaeter am
    # ausbleibenden Mitschnitt zu merken.
    _stripped = _raw_in.strip().lstrip("@")
    if username != _stripped:
        await update.message.reply_text(
            f"ℹ️ Eingabe als URL gelesen → getrackt wird <b>@{safe(username)}</b>.\n"
            f"<i>Heißt der Kanal wirklich </i><code>{safe(_stripped)}</code><i>, "
            f"nimm </i><code>/track_exact {safe(_stripped)}</code><i> — "
            f"das speichert den Namen unverändert.</i>",
            parse_mode=ParseMode.HTML)
    # F64: Quota-Check vor dem Insert damit wir eine bessere Fehlermeldung
    # geben können (sonst bekäme der User "BEREITS AKTIV" obwohl es nicht stimmt).
    chat_id = update.effective_chat.id
    if MAX_TRACKINGS_PER_CHAT > 0:
        current = count_trackings_for_chat(chat_id)
        if current >= MAX_TRACKINGS_PER_CHAT:
            # Check ob's nicht schon getrackt wird (dann wär's kein Quota-Issue)
            with db_conn() as conn:
                exists = conn.execute(
                    "SELECT 1 FROM trackings WHERE group_id=? AND username=? LIMIT 1",
                    (chat_id, username)).fetchone()
            if not exists:
                await update.message.reply_text(
                    f"🚫 <b>QUOTA ERREICHT</b>\n"
                    f"<i>Dieser Chat hat bereits {current}/{MAX_TRACKINGS_PER_CHAT} "
                    f"Trackings. Erst alte mit <code>/untrack</code> entfernen.</i>",
                    parse_mode=ParseMode.HTML); return
    added = add_tracking(chat_id, username, update.effective_user.id)
    if added:
        # F35: Sofortiger Check beim Hinzufügen — Worker schaut innerhalb der
        # nächsten 5s rein. User muss nicht bis zum nächsten Interval warten.
        with db_conn() as conn:
            row = conn.execute(
                "SELECT id FROM trackings WHERE group_id=? AND username=?",
                (chat_id, username)).fetchone()
        if row:
            _NEXT_CHECK_AT[row["id"]] = 0   # sofort fällig
        text = (f"✅ <b>TRACKING AKTIV · @{safe(username)}</b>\n"
                f"<i>Benachrichtigung bei Live-Stream + automatische Aufnahme.</i>\n"
                f"<i>Erster Check läuft jetzt…</i>\n"
                f"\n"
                f"<code>Alle Trackings: /tracklist</code>")
    else:
        text = (f"ℹ️ <b>BEREITS AKTIV · @{safe(username)}</b>\n"
                f"<i>Tracking läuft schon in dieser Gruppe.</i>")
    await update.message.reply_text(_nc_i18n.t(text), parse_mode=ParseMode.HTML)

