async def tracklist(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not _is_authorized(update): return
    trackings = get_trackings_for_group(update.effective_chat.id)
    if not trackings:
        await update.message.reply_text(
            "📋 <b>TRACKINGS</b>\n"
            "<i>Keine aktiven Trackings in dieser Gruppe.</i>\n"
            "\n"
            "Starte ein Tracking mit:\n"
            "<code>/track @username</code>",
            parse_mode=ParseMode.HTML); return

    live_n = sum(1 for t in trackings if t["last_live"])
    rec_n  = sum(1 for t in trackings if t["recording"])
    paused_n = sum(1 for t in trackings
                   if "paused" in t.keys() and t["paused"])

    # F65: Build pre-table: status icon + handle (left-padded) + flags + notes
    handle_w = max(len(t["username"]) for t in trackings) + 1  # for the @
    rows = []
    for t in trackings:
        is_paused = ("paused" in t.keys() and t["paused"])
        # F65: Pause-Icon hat Vorrang über Live (User hat manuell gestoppt)
        icon = "⏸" if is_paused else ("🔴" if t["last_live"] else "⚫")
        handle = ("@" + t["username"]).ljust(handle_w + 1)
        flags = []
        if t["last_live"] and not is_paused: flags.append("LIVE")
        if t["recording"]: flags.append("•REC")
        if is_paused: flags.append("PAUSED")
        # F65: Notes inline anzeigen wenn vorhanden — limited width damit
        # die pre-Tabelle nicht zu breit wird
        note = (t["notes"] if "notes" in t.keys() else None) or ""
        if note:
            if len(note) > 30:
                note = note[:27] + "..."
            flags.append(f"// {note}")
        rows.append(f"{icon} {handle}  {' '.join(flags)}")

    body = "\n".join(rows)
    status_extra = f", {paused_n} paused" if paused_n else ""
    text = (
        f"📋 <b>TRACKINGS · {len(trackings)} aktiv "
        f"({live_n} live, {rec_n} rec{status_extra})</b>\n"
        f"\n"
        f"<pre>{body}</pre>\n"
        f"\n"
        f"<code>Aktualisiert: {utc_clock()} UTC</code>"
    )
    await update.message.reply_text(_nc_i18n.t(text), parse_mode=ParseMode.HTML)

async def diag(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F11: Selbst-Diagnose direkt aus Telegram. Zeigt was im Stack
       installiert/erreichbar ist und welcher Recorder aktiv wäre."""
    if not _is_authorized(update): return
    msg = await update.message.reply_text(_nc_i18n.t("⏳ <i>Diagnose läuft…</i>"),
                                          parse_mode=ParseMode.HTML)

    # 1) Recorder-Binaries
    # F43: streamlink entfernt — wird nicht mehr unterstützt
    ytdlp_bin = shutil.which("yt-dlp") or shutil.which("yt_dlp")
    ff        = shutil.which("ffmpeg")

    async def _probe_version(bin_path):
        # F42-Bug-Hunt-Fix B4: bei Timeout/Exception nicht nur das `await`
        # canceln — auch den Subprocess killen+reapen. Sonst läuft das
        # --version-binary orphan weiter (oder bleibt als Zombie liegen).
        proc = None
        try:
            proc = await asyncio.create_subprocess_exec(
                bin_path, "--version",
                stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.PIPE)
            out, _ = await asyncio.wait_for(proc.communicate(), timeout=10)
            return out.decode(errors="ignore").strip().split("\n")[0]
        except asyncio.TimeoutError:
            if proc:
                try: proc.kill()
                except Exception: pass
                try: await asyncio.wait_for(proc.wait(), timeout=2)
                except Exception: pass
            return "Timeout"
        except Exception as e:
            if proc and proc.returncode is None:
                try: proc.kill()
                except Exception: pass
                try: await asyncio.wait_for(proc.wait(), timeout=2)
                except Exception: pass
            return f"Fehler: {e}"

    yt_version = await _probe_version(ytdlp_bin) if ytdlp_bin else "—"
    # F43: streamlink-Version + Plugin-Probe entfernt

    # 2) Aktiver Recorder (was die echte Aufnahme nehmen würde)
    # native: braucht nur ffmpeg + unsere Resolver-Funktion
    # F43: streamlink raus der active-Auswahl
    native_ok = bool(ff)
    if RECORDER_PREF == "native":
        active = "native" if native_ok else None
    elif RECORDER_PREF == "ytdlp":
        active = "ytdlp" if ytdlp_bin else None
    else:  # auto
        if native_ok:    active = "native"
        elif ytdlp_bin:  active = "ytdlp"
        else:            active = None
    active_str = f"✅ {active} (Pref={RECORDER_PREF})" if active else "❌ KEIN Recorder!"

    # 3) Cookies
    cookies = _load_cookies_dict()
    important = ["sessionid_ss", "sessionid", "ttwid", "tt_chain_token"]
    have = [c for c in important if c in cookies]
    missing = [c for c in important if c not in cookies]

    # 4) DB / paths
    db_ok = os.path.exists(DB_PATH)
    rec_dir_ok = os.path.isdir(RECORDINGS_DIR)
    log_dir_ok = os.path.isdir(LOG_DIR)

    # 5) Trackings
    with db_conn() as conn:
        active_n = conn.execute("SELECT COUNT(*) FROM trackings WHERE recording=1").fetchone()[0]
        tracked = conn.execute("SELECT COUNT(*) FROM trackings").fetchone()[0]

    # 6) Redis
    redis_state = "❌ nicht installiert (pip install redis)" if redis_aio is None else None
    if redis_state is None:
        r = await get_redis()
        if r is None:
            redis_state = f"❌ nicht erreichbar ({REDIS_URL})"
        else:
            try:
                info = await r.info("server")
                ver = info.get("redis_version", "?")
                redis_state = f"✅ {ver} @ {REDIS_URL}"
            except Exception as e:
                redis_state = f"⚠️ verbunden, info-Fehler: {e}"

    # 7) LLM (Brain-Runtime / freeai)
    llm_models = await llm_list_models()
    if llm_models is None:
        llm_state = "❌ kein LLM erreichbar (Brain-Runtime + freeai-Basen down)"
    elif not llm_models:
        llm_state = "⚠️ erreichbar, aber keine Modell-Liste"
    else:
        has_default = AI_MODEL in llm_models or \
                      any(m.startswith(AI_MODEL + ":") for m in llm_models)
        marker = "✅" if has_default else "⚠️"
        # Modell-Liste auf max 3 begrenzen
        sample = ", ".join(llm_models[:3])
        if len(llm_models) > 3:
            sample += f" +{len(llm_models)-3}"
        llm_state = f"{marker} {len(llm_models)} Modell(e): {sample}"

    rows = [
        ("Recorder",     active_str),
        ("native",       "✅ ffmpeg + JSON-Resolver" if native_ok else "❌ ffmpeg fehlt"),
        ("yt-dlp",       yt_version if ytdlp_bin else "❌ nicht installiert"),
        # F43: streamlink + SL-Plugin Zeilen entfernt
        ("ffmpeg",       "✅ " + ff if ff else "❌ NICHT INSTALLIERT"),
        ("Cookies",      f"{len(cookies)} ({len(have)}/{len(important)} kritisch)"
                         if cookies else "❌ leer/fehlt"),
        ("Redis",        redis_state),
        ("Claude/LLM",   llm_state),
        ("Datenbank",    "✅ " + DB_PATH if db_ok else "❌ fehlt"),
        ("Rec-Verz.",    "✅ " + RECORDINGS_DIR if rec_dir_ok else "❌ fehlt"),
        ("Log-Verz.",    "✅ " + LOG_DIR if log_dir_ok else "❌ fehlt"),
        ("Trackings",    f"{tracked} aktiv ({active_n} aufnehmend)"),
    ]
    body = pre_table(rows, align='left')

    extra_lines = []
    if missing and cookies:
        extra_lines.append(
            f"<i>Fehlende kritische Cookies: <code>{', '.join(missing)}</code></i>")
    # F43: streamlink raus dem Check
    if not native_ok and not ytdlp_bin:
        extra_lines.append("<b>⚠️ Kein Recorder verfügbar!</b>")
        extra_lines.append(
            "<i>Mindestens <code>apt install ffmpeg</code> für den nativen Recorder.</i>")
    elif not native_ok:
        extra_lines.append(
            "<i>ffmpeg fehlt — der native Recorder braucht das. "
            "<code>apt install ffmpeg</code></i>")
    if RECORDER_PREF == "native" and active != "native":
        extra_lines.append(
            "<i>RECORDER=native gesetzt aber ffmpeg fehlt — "
            "läuft auf Fallback hinaus.</i>")

    extra = ("\n\n" + "\n".join(extra_lines)) if extra_lines else ""

    text = (
        f"🔧 <b>DIAGNOSE</b>\n\n"
        f"<pre>{body}</pre>"
        f"{extra}"
    )
    try:
        await msg.edit_text(_nc_i18n.t(text), parse_mode=ParseMode.HTML)
    except Exception as e:
        log.warning(f"diag edit failed: {e}")
        await msg.edit_text(_nc_i18n.t("Diagnose abgeschlossen — siehe debug.log."))

async def teststream(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F11: 30-Sekunden-Probe-Recording mit kompletter Diagnose-Ausgabe.
       Macht genau was die echte Aufnahme machen würde, aber nur kurz und
       meldet das Ergebnis zurück nach Telegram statt still in den Logs."""
    if not _is_authorized(update): return
    if not context.args:
        await update.message.reply_text(
            "Benutzung: <code>/teststream username</code>\n"
            "<i>Macht eine 30-Sekunden-Probe-Aufnahme und zeigt was der Recorder "
            "wirklich macht. Bestes Diagnose-Tool für 'Aufnahmen funktionieren nicht'.</i>",
            parse_mode=ParseMode.HTML); return

    username = clean_username(context.args[0])
    if not username:
        await update.message.reply_text(_nc_i18n.t("⚠️ Ungültiger Username.")); return

    msg = await update.message.reply_text(
        _nc_i18n.t(f"⏳ <i>Probe-Aufnahme @{safe(username)} (max 30s)…</i>"),
        parse_mode=ParseMode.HTML)

    # Step 1: live status
    scraper = context.application.bot_data.get("scraper")
    session = scraper.session if scraper else None
    info = await _get_live_info(username, session=session)
    if info["is_live"] is None:
        await msg.edit_text(
            f"⚠️ <b>STATUS UNBEKANNT · @{safe(username)}</b>\n"
            f"<i>TikTok antwortet aktuell nicht — Test abgebrochen.</i>",
            parse_mode=ParseMode.HTML); return
    if not info["is_live"]:
        await msg.edit_text(
            f"⚫ <b>NICHT LIVE · @{safe(username)}</b>\n"
            f"<i>TikTok meldet: nicht live. Test abgebrochen.</i>",
            parse_mode=ParseMode.HTML); return

    # Step 2 + 3: Recorder bauen (mit echtem test_file). Eine Auflösung statt zwei.
    test_file = os.path.join(
        RECORDINGS_DIR,
        f"_probe_{username}_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')}.mp4")
    scraper: TikTokScraper = context.application.bot_data.get("scraper")
    session = scraper.session if scraper else None
    cmd, recorder = await build_recording_cmd(username, test_file, 30, session=session)
    if cmd is None:
        await msg.edit_text(
            "❌ <b>Kein Recorder verfügbar / Stream nicht auflösbar</b>\n"
            "<i>Native: ffmpeg fehlt oder Resolver findet keine Stream-URL.\n"
            "yt-dlp: nicht installiert.</i>\n\n"
            "Fix: <code>apt install ffmpeg</code> (für native) oder "
            "<code>pip install -U yt-dlp</code>",
            parse_mode=ParseMode.HTML); return
    has_cookies = os.path.exists(COOKIE_FILE) and bool(_load_cookies_dict())

    stdout_text = stderr_text = ""
    rc = None
    try:
        log.info(f"teststream: {recorder} cmd: {' '.join(redact_cmd_for_log(cmd))}")
        proc = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE)
        try:
            stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=45)
            rc = proc.returncode
        except asyncio.TimeoutError:
            try: proc.kill()
            except Exception: pass
            try:
                stdout, stderr = await proc.communicate()
                rc = -9
            except Exception:
                stdout, stderr = b"", b""
        stdout_text = stdout.decode(errors='ignore') if stdout else ""
        stderr_text = stderr.decode(errors='ignore') if stderr else ""
    except Exception as e:
        await msg.edit_text(
            f"❌ <b>{safe(recorder)} Start fehlgeschlagen</b>\n"
            f"<code>{safe(str(e))[:300]}</code>",
            parse_mode=ParseMode.HTML); return

    # Step 4: results
    file_exists = os.path.exists(test_file)
    file_size = os.path.getsize(test_file) if file_exists else 0
    success = file_exists and file_size > 1024  # >1 KB = etwas wurde geschrieben
    if file_exists:
        try: os.remove(test_file)
        except OSError: pass

    if success:
        rows = [
            ("Recorder", recorder),
            ("Datei",    f"{file_size/1024/1024:.2f} MB"),
            ("Cookies",  "ja" if has_cookies else "nein"),
            ("rc",       str(rc)),
        ]
        body = pre_table(rows, align='left')
        await msg.edit_text(
            f"✅ <b>PROBE OK · @{safe(username)}</b>\n"
            f"<i>Aufnahme würde funktionieren ({recorder}).</i>\n\n"
            f"<pre>{body}</pre>",
            parse_mode=ParseMode.HTML); return

    # Failure: categorize + show stderr tail
    sl = (stderr_text + stdout_text).lower()
    # F43: streamlink-spezifische Kategorie ('no plugin can handle') entfernt
    if "unsupported url" in sl:
        cat = "Recorder versteht TikTok-URL nicht — Recorder updaten"
    elif "no playable streams" in sl:
        cat = "Kein Stream auffindbar (TikTokLive sagt live, Recorder findet nichts)"
    elif "this user is offline" in sl or "user is currently not live" in sl \
         or "is not currently live" in sl:
        cat = "User offline laut Recorder (Detection-Lag oder gerade beendet)"
    elif "403" in stderr_text or "forbidden" in sl:
        cat = "TikTok blockiert (HTTP 403) — Cookies abgelaufen oder fehlen"
    elif "login required" in sl or "sign in to confirm" in sl:
        cat = "Login nötig — Cookies neu exportieren"
    elif "timeout" in sl or "timed out" in sl:
        cat = "Verbindungs-Timeout"
    else:
        cat = "Unbekannt — siehe Tail unten"

    tail = (stderr_text or stdout_text)[-700:]
    rows = [
        ("Recorder", recorder),
        ("Cookies",  "ja" if has_cookies else "NEIN"),
        ("rc",       str(rc)),
        ("Datei",    f"{file_size} B" if file_exists else "nicht erstellt"),
    ]
    body = pre_table(rows, align='left')
    text = (
        f"❌ <b>PROBE FEHLGESCHLAGEN · @{safe(username)}</b>\n"
        f"<i>{safe(cat)}</i>\n\n"
        f"<pre>{body}</pre>\n\n"
        f"<b>{safe(recorder)} Output (Tail):</b>\n"
        f"<pre>{safe(tail)}</pre>"
    )
    # Telegram message hard limit is 4096 chars
    if len(text) > 3900:
        text = text[:3900] + "\n…</pre>"
    try:
        await msg.edit_text(_nc_i18n.t(text), parse_mode=ParseMode.HTML)
    except Exception as e:
        log.warning(f"teststream edit failed: {e}")
        await msg.edit_text(
            _nc_i18n.t(f"❌ Test fehlgeschlagen ({safe(cat)}). Siehe debug.log."),
            parse_mode=ParseMode.HTML)

# =============================================================================
# F16: File-Support für /ai (Text + Bilder)
# =============================================================================
# - Text-Files: Inhalt wird in den Prompt eingebettet (mit Längen-Cap)
# - Bilder: per Base64 als 'images' Feld an Ollama (Vision-Model nötig: llava,
#   llama3.2-vision, etc. — entweder als AI_MODEL oder AI_VISION_MODEL)
# - PDFs werden NICHT geparst (würde extra Dependency brauchen) — wir geben
#   eine freundliche Meldung
# -----------------------------------------------------------------------------

async def _extract_file_payload(bot, file_obj, mime_hint: str = "") -> dict:
    """Lädt eine Telegram-Datei und entscheidet wie sie an die LLM geht.
       Returns dict: {kind, content_text|content_b64, size, name, mime, error}

       v4.0-W28: der Download bleibt hier (I/O), die reine Klassifikation/
       Decodierung liegt in nc/filepayload.py (bitgenau geprüft)."""
    result = {"kind": None, "size": 0, "name": "", "mime": mime_hint, "error": None}

    name = getattr(file_obj, "file_name", "") or ""
    result["name"] = name
    fsize = getattr(file_obj, "file_size", None)
    if fsize is not None:
        result["size"] = int(fsize)
        rej = _nc_fp.size_reject(fsize, AI_FILE_MAX_BYTES)
        if rej:
            result.update(rej)
            return result

    mime = (getattr(file_obj, "mime_type", None) or mime_hint or "").lower()
    result["mime"] = mime

    try:
        tg_file = await file_obj.get_file()
        bio = io.BytesIO()
        await tg_file.download_to_memory(bio)
        raw = bio.getvalue()
        result["size"] = len(raw)
    except Exception as e:
        result["kind"] = "error"
        result["error"] = f"Download fehlgeschlagen: {e}"
        return result

    result.update(_nc_fp.classify_downloaded(raw, name=name, mime=mime,
                                             max_chars=AI_TEXT_MAX_CHARS))
    return result



async def _run_ai_call(update, context, prompt_text: str,
                        file_obj=None, mime_hint: str = ""):
    """F16: gemeinsame Logik für /ai (mit/ohne Datei).
       prompt_text ist die User-Frage (Caption oder Args). file_obj ist optional
       ein Telegram File/PhotoSize/Document das als Kontext mitgeschickt wird."""
    user_id = update.effective_user.id
    chat_id = update.effective_chat.id

    if not await ai_rate_limit_check(user_id):
        await update.message.reply_text(
            f"🚦 <b>Limit erreicht</b>\n"
            f"<i>Max {AI_RATE_LIMIT_PER_MIN} Anfragen/min. Kurz warten.</i>",
            parse_mode=ParseMode.HTML); return

    try: await context.bot.send_chat_action(chat_id, action="typing")
    except Exception: pass

    msg = await update.message.reply_text(
        _nc_i18n.t(f"🤔 <i>Denke nach…{' (mit Datei)' if file_obj else ''}</i>"),
        parse_mode=ParseMode.HTML)

    # Datei verarbeiten falls vorhanden
    file_kind = None
    file_size = None
    file_block = ""
    images = None
    use_model = AI_MODEL

    if file_obj is not None:
        payload = await _extract_file_payload(context.bot, file_obj, mime_hint=mime_hint)
        file_kind = payload["kind"]
        file_size = payload.get("size")

        if payload.get("error") and payload["kind"] in ("too_big","pdf","binary","error"):
            err_text = (
                f"⚠️ <b>Datei nicht verarbeitet</b>\n"
                f"<i>{safe(payload['error'])}</i>")
            await msg.edit_text(_nc_i18n.t(err_text), parse_mode=ParseMode.HTML)
            add_ai_log_entry(chat_id, user_id, prompt_text, None, AI_MODEL, 0,
                             error=f"file_{payload['kind']}: {payload['error']}",
                             file_kind=payload["kind"], file_size=file_size)
            return

        if payload["kind"] == "image":
            images = [payload["content_b64"]]
            # Vision-Modell wählen
            if AI_VISION_MODEL:
                use_model = AI_VISION_MODEL
            elif not _looks_like_vision_model(AI_MODEL):
                # Best-effort warnung — Ollama meldet sich selbst wenn Modell kein Bild kann
                log.info(f"/ai mit Bild aber {AI_MODEL} sieht nicht nach Vision-Modell aus.")
        elif payload["kind"] == "text":
            # Text in Prompt einbetten
            tag = payload.get("name") or "datei"
            file_block = (
                f"\n\n[Datei: {tag} · {payload['size']} bytes]\n"
                f"```\n{payload['content_text']}\n```\n"
            )

    full_prompt = (prompt_text or "Analysiere das.") + file_block

    history = await ai_history_load(chat_id, user_id)
    messages = [{"role": "system", "content": AI_SYSTEM_PROMPT}]
    messages.extend(history)
    user_msg = {"role": "user", "content": full_prompt}
    if images:
        user_msg["images"] = images
    messages.append(user_msg)

    started = datetime.now(timezone.utc)
    # FIX: vorher AI_TIMEOUT (120s) -> killte langsame Modelle (claude-fable auf CPU braucht laenger).
    # Jetzt wie die Dashboard-AI: grosszuegiger Timeout, der praktisch nur bei totaler Stille greift.
    response, err_kind = await llm_chat(messages, model=use_model, timeout=AI_STREAM_TIMEOUT)
    elapsed = (datetime.now(timezone.utc) - started).total_seconds()
    duration_ms = int(elapsed * 1000)

    if response is None:
        err_text_map = {
            "net":        "Kein LLM erreichbar (Brain-Runtime + freeai-Basen). Netz/llama-server prüfen.",
            "timeout":    f"LLM hat länger als {AI_TIMEOUT}s gebraucht — Backend zu langsam oder hängt.",
            "rate_limit": "freeai: alle Basen im Rate-Limit (429) — kurz warten, Rotation läuft.",
            "auth":       "freeai: Base verlangt API-Key (FREEAI_BASES 'url|key' setzen oder Base wechseln).",
            "http":       "LLM-HTTP-Fehler. Siehe debug.log.",
            "empty":      "LLM lieferte leere Antwort. Siehe debug.log.",
        }.get(err_kind, "Unbekannter Fehler.")
        await msg.edit_text(
            _nc_i18n.t(f"⚠️ <b>AI nicht verfügbar</b>\n<i>{err_text_map}</i>"),
            parse_mode=ParseMode.HTML)
        add_ai_log_entry(chat_id, user_id, prompt_text, None, use_model, duration_ms,
                         error=err_kind, file_kind=file_kind, file_size=file_size)
        return

    # Verlauf + Counter
    await ai_history_append(chat_id, user_id, "user",
                            (prompt_text or "") + (f" [+{file_kind}]" if file_kind else ""))
    await ai_history_append(chat_id, user_id, "assistant", response)
    try:
        r = await get_redis()
        if r is not None: await r.incr("ai_calls_total")
    except Exception: pass

    # Persist log row
    add_ai_log_entry(chat_id, user_id, prompt_text, response, use_model, duration_ms,
                     error=None, file_kind=file_kind, file_size=file_size)

    # Antwort als plain text + Footer
    file_marker = f" · {file_kind}" if file_kind else ""
    footer = f"\n\n— {elapsed:.1f}s · {use_model}{file_marker}"
    chunks = split_for_telegram(response + footer, 4000)
    if len(chunks) == 1:
        try: await msg.edit_text(_nc_i18n.t(chunks[0]))
        except Exception as e: log.warning(f"AI edit_text failed: {e}")
    else:
        try: await msg.edit_text(_nc_i18n.t(chunks[0]))
        except Exception: pass
        for c in chunks[1:]:
            try: await update.message.reply_text(_nc_i18n.t(c))
            except Exception as e: log.warning(f"AI follow-up reply failed: {e}")


async def ai(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F14/F16: Chat mit lokalem LLM. Optional Datei als Caption-Anhang."""
    if not _is_authorized(update): return

    msg = update.message
    file_obj = None
    mime_hint = ""

    # Falls die Message einen Anhang HAT (Document oder Photo), nimm den
    if msg.document:
        file_obj = msg.document
    elif msg.photo:
        file_obj = msg.photo[-1]   # größte Auflösung
        mime_hint = "image/jpeg"

    # Args auslesen
    if not context.args and not file_obj:
        await update.message.reply_text(
            "💬 <b>AI-Chat</b>\n"
            "<i>Frage direkt nach dem Befehl stellen.</i>\n\n"
            "<code>/ai erkläre HLS in 3 Sätzen</code>\n"
            "<code>/ai schreib mir ein bash-script…</code>\n\n"
            "<b>📎 Dateien:</b> Datei oder Bild senden mit Caption "
            "<code>/ai &lt;frage&gt;</code> — Inhalt wird mitgegeben.\n"
            f"<i>Limits: max {AI_FILE_MAX_BYTES//1024//1024} MB Datei, "
            f"{AI_TEXT_MAX_CHARS} Zeichen Text.</i>\n\n"
            f"<code>/aireset</code>  — Verlauf löschen\n"
            f"<i>Modell: <code>{safe(AI_MODEL)}</code>"
            f"{(' · Vision: '+safe(AI_VISION_MODEL)) if AI_VISION_MODEL else ''}</i>",
            parse_mode=ParseMode.HTML); return

    prompt_text = " ".join(context.args).strip() if context.args else ""
    await _run_ai_call(update, context, prompt_text,
                       file_obj=file_obj, mime_hint=mime_hint)


async def on_ai_media(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F16: Triggert auf Documents/Photos die als Caption '/ai ...' haben.
       Damit kann der User einfach Datei + Caption schicken statt /ai-Befehl mit Anhang."""
    if not _is_authorized(update): return
    msg = update.message
    if not msg: return
    caption = (msg.caption or "").strip()
    if not caption.lower().startswith("/ai"):
        return  # ignore — anderer Anhang
    # Caption-Args parsen: alles nach "/ai"
    parts = caption.split(maxsplit=1)
    prompt_text = parts[1] if len(parts) > 1 else ""

    file_obj = None; mime_hint = ""
    if msg.document:
        file_obj = msg.document
    elif msg.photo:
        file_obj = msg.photo[-1]
        mime_hint = "image/jpeg"
    if file_obj is None:
        return

    await _run_ai_call(update, context, prompt_text,
                       file_obj=file_obj, mime_hint=mime_hint)


async def aireset(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F14: Verlauf für (chat, user) löschen."""
    if not _is_authorized(update): return
    user_id = update.effective_user.id
    chat_id = update.effective_chat.id
    await ai_history_clear(chat_id, user_id)
    await update.message.reply_text(
        _nc_i18n.t("🧹 <b>AI-Verlauf gelöscht</b>\n<i>Nächste Frage startet frisch.</i>"),
        parse_mode=ParseMode.HTML)

# =============================================================================
# F19: Recording-Diagnose, Cleanup, Stats — neue Commands
# =============================================================================
async def recstatus(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F19: zeigt die letzten 10 Aufnahme-Versuche (Erfolg + Fehler)."""
    if not _is_authorized(update): return
    rows = get_recent_recording_attempts(limit=10)
    if not rows:
        await update.message.reply_text(
            "📭 <b>Keine Aufnahme-Versuche</b>\n"
            "<i>Sobald jemand getrackt wird und live geht, erscheinen hier "
            "alle Versuche (auch fehlgeschlagene).</i>",
            parse_mode=ParseMode.HTML); return

    lines = ["<b>🎬 LETZTE AUFNAHME-VERSUCHE</b>"]
    icons = {"ok": "✅", "running": "⏳", "offline_or_protected": "💤",
             "forbidden_403": "🔒", "timeout": "⏱", "no_plugin": "🚫",
             "empty_output": "📭", "fail": "❌", "crash": "💥",
             "start_failed": "💥", "codec_header_fail": "🎞", "hevc_unsupported": "🎞"}
    for r in rows:
        rc = r["returncode"] if r["returncode"] is not None else "—"
        icon = icons.get(r["outcome"], "•")
        size_mb = (r["file_size"] or 0) / 1024 / 1024
        size_s = f"{size_mb:.1f}MB" if size_mb >= 0.1 else "—"
        ts = (r["started_at"] or "")[5:19].replace("T", " ")
        dur = f"{r['duration_secs']}s" if r["duration_secs"] else "—"
        lines.append(
            f"\n{icon} <code>{safe(ts)}</code>  @{safe(r['username'])}\n"
            f"   <i>{safe(r['recorder'] or '?')} · "
            f"rc={rc} · {dur} · {size_s} · {safe(r['outcome'])}</i>")
        if r["outcome"] not in ("ok", "running") and r["stderr_tail"]:
            tail = r["stderr_tail"][-200:].strip()
            lines.append(f"   <pre>{safe(tail)}</pre>")
    await update.message.reply_text(_nc_i18n.t("\n".join(lines)), parse_mode=ParseMode.HTML)


async def cleanup(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F19: räumt verwaiste recording=1 Locks weg + alte Probe-Dateien."""
    if not _is_authorized(update): return
    msg = await update.message.reply_text(_nc_i18n.t("🧹 <i>Räume auf…</i>"),
                                          parse_mode=ParseMode.HTML)
    cleaned_locks = 0
    # F42-Bug-Hunt-Fix B7: Race-Condition mit Spawn-Fenster. Vorher hat /cleanup
    # einfach ALLE recording=1 Rows geprüft. Wenn ein Worker gerade zwischen
    # try_acquire_recording_lock und set_recording_file war (pid IS NULL),
    # hat _is_process_running(None) False zurückgegeben → Lock gecleart →
    # ein paar ms später setzte set_recording_file pid/output_file mit
    # recording=0 in der DB → Zustand inkonsistent. Schlimmster Fall: ein
    # zweiter Worker für den gleichen Tracking nimmt erneut auf (Doppel-
    # Recording). Jetzt: gleiche Logik wie der reaper — pid=NULL Rows nur
    # cleanen wenn der Spawn-Timestamp alt ist oder gar nicht existiert.
    with db_conn() as conn:
        # 1. Klassische Orphan-PIDs: pid IS NOT NULL aber Prozess weg
        rows = conn.execute(
            "SELECT id, pid, username FROM trackings "
            "WHERE recording=1 AND pid IS NOT NULL").fetchall()
        for r in rows:
            if not _is_process_running(r["pid"]):
                conn.execute(
                    "UPDATE trackings SET recording=0, output_file=NULL, pid=NULL "
                    "WHERE id=?", (r["id"],))
                cleaned_locks += 1
                log.info(f"cleanup: orphan-lock @{r['username']} (id={r['id']}) freigegeben")

        # 2. Stuck-Locks im Spawn-Fenster: pid IS NULL. Nur cleanen wenn
        #    der Spawn-Marker fehlt (Crash aus vorigem Run) ODER zu alt ist.
        now_mono = _time_mod.monotonic()
        stuck = conn.execute(
            "SELECT id, username FROM trackings "
            "WHERE recording=1 AND pid IS NULL").fetchall()
        for r in stuck:
            tid_ = r["id"]
            spawn_at = _RECORDING_SPAWN_AT.get(tid_)
            if spawn_at is None or (now_mono - spawn_at > _RECORDING_SPAWN_TIMEOUT):
                conn.execute(
                    "UPDATE trackings SET recording=0, output_file=NULL, pid=NULL "
                    "WHERE id=? AND recording=1 AND pid IS NULL", (tid_,))
                _RECORDING_SPAWN_AT.pop(tid_, None)
                cleaned_locks += 1
                age = f"{now_mono - spawn_at:.0f}s alt" if spawn_at else "kein Marker"
                log.info(f"cleanup: stuck-lock @{r['username']} (id={tid_}, {age}) freigegeben")
        conn.commit()

    # Probe-Dateien (vom /teststream) > 24h alt
    cleaned_probes = 0
    cutoff = datetime.now(timezone.utc).timestamp() - 86400
    try:
        for f in glob.glob(os.path.join(RECORDINGS_DIR, "_probe_*.mp4")):
            try:
                if os.path.getmtime(f) < cutoff:
                    os.remove(f); cleaned_probes += 1
            except OSError: pass
    except Exception: pass

    # F69: Orphan _part_*.mp4 Dateien aus split_and_send_video. Wenn der
    # Upload-Flow während des Splits crashed (Bot-Restart, OOM, etc.), bleiben
    # die _part_NNN.mp4-Files zurück. Sind nutzlos ohne ihren Eltern-Recording-
    # Kontext, fressen aber Disk. Hier weg räumen — Pattern matched genau
    # was split_and_send_video generiert (prefix = f"{filepath}_part",
    # output = f"{prefix}_%03d.mp4").
    cleaned_orphan_parts = 0
    try:
        for f in glob.glob(os.path.join(RECORDINGS_DIR, "*_part_*.mp4")):
            try:
                # Defensiv: nur löschen wenn > 1h alt damit wir keine
                # gerade-laufende Split-Operation killen.
                if os.path.getmtime(f) < datetime.now(timezone.utc).timestamp() - 3600:
                    os.remove(f); cleaned_orphan_parts += 1
                    log.info(f"cleanup: orphan part-file entfernt: {os.path.basename(f)}")
            except OSError: pass
    except Exception: pass

    # Recording-Attempts älter als 30 Tage
    cleaned_attempts = 0
    try:
        with db_conn() as conn:
            cutoff_iso = (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()
            cur = conn.execute(
                "DELETE FROM recording_attempts WHERE started_at < ?", (cutoff_iso,))
            cleaned_attempts = cur.rowcount or 0
            conn.commit()
    except Exception: pass

    # B122-PERF: tiktok_checks hatte als EINZIGE Log-Tabelle keine Aufraeumung.
    # Sie waechst mit jedem Live-Check — bei adaptivem Polling um Zehntausende
    # Zeilen pro Tag, jede mit dem kompletten Profil-JSON. Gemessen: 3 Mio
    # Zeilen = 403 MB Datei, und die Aggregate in get_stats() stiegen dabei
    # auf 635 ms pro Aufruf.
    #
    # Fachlich ist die Tabelle ein Verlaufsprotokoll: gelesen wird sie nur
    # fuer die letzten 50 Eintraege (get_all_checks) und fuer Gesamtsummen.
    # Aeltere Zeilen haben keinen Leser. Deshalb Kappung nach Alter UND ein
    # harter Zeilen-Deckel, falls jemand die Tage hochsetzt.
    cleaned_checks = 0
    try:
        with db_conn() as conn:
            if CHECKS_RETENTION_DAYS > 0:
                cut_checks = (datetime.now(timezone.utc)
                              - timedelta(days=CHECKS_RETENTION_DAYS)).isoformat()
                cur = conn.execute(
                    "DELETE FROM tiktok_checks WHERE created_at < ?", (cut_checks,))
                cleaned_checks = cur.rowcount or 0
            if CHECKS_MAX_ROWS > 0:
                row = conn.execute("SELECT COUNT(*) FROM tiktok_checks").fetchone()
                over = (row[0] if row else 0) - CHECKS_MAX_ROWS
                if over > 0:
                    conn.execute(
                        "DELETE FROM tiktok_checks WHERE id IN "
                        "(SELECT id FROM tiktok_checks ORDER BY id ASC LIMIT ?)",
                        (over,))
                    cleaned_checks += over
            if cleaned_checks:
                conn.commit()
                _nc_stats.invalidate_stats_cache()   # Cache sofort invalidieren
    except Exception as e:
        log.warning("Retention tiktok_checks fehlgeschlagen: %s", e)

    # ── B127-PERF: die uebrigen Log-Tabellen ────────────────────────────
    cleaned_events = cleaned_ailog = thinned_snaps = cleaned_overlay = 0
    cleaned_modlog = cleaned_audit = 0
    try:
        with db_conn() as conn:
            _now = datetime.now(timezone.utc)

            if EVENTLOG_RETENTION_DAYS > 0:
                _cut = (_now - timedelta(days=EVENTLOG_RETENTION_DAYS)).isoformat()
                cleaned_events = conn.execute(
                    "DELETE FROM event_log WHERE ts < ?", (_cut,)).rowcount or 0

            if AI_LOG_RETENTION_DAYS > 0:
                # B127: bis hierher war diese Einstellung wirkungslos.
                _cut = (_now - timedelta(days=AI_LOG_RETENTION_DAYS)).isoformat()
                cleaned_ailog = conn.execute(
                    "DELETE FROM ai_log WHERE created_at < ?", (_cut,)).rowcount or 0

            if SNAPSHOT_THIN_AFTER_DAYS > 0:
                # AUSDUENNEN statt loeschen: jenseits der Frist bleibt pro
                # User und Kalendertag der juengste Snapshot stehen. Die
                # Wachstumskurve bleibt damit ueber Jahre lesbar, waehrend
                # die stuendlichen Zwischenwerte verschwinden.
                _cut = (_now - timedelta(days=SNAPSHOT_THIN_AFTER_DAYS)).isoformat()
                thinned_snaps = conn.execute(
                    "DELETE FROM profile_snapshots WHERE captured_at < ? "
                    "AND id NOT IN (SELECT MAX(id) FROM profile_snapshots "
                    "               WHERE captured_at < ? "
                    "               GROUP BY username, substr(captured_at,1,10))",
                    (_cut, _cut)).rowcount or 0

            if OVERLAY_RETENTION_DAYS > 0:
                # SONDERFALL GELD: 'donation' wird NIE geloescht. Diese Zeilen
                # speisen das Spendenziel und die Gegenprobe der Finanzamt-
                # Auswertung (nc/ledger.crosscheck). Sie zu kappen wuerde
                # Einnahmen aus der Historie verschwinden lassen — genau der
                # Fehler, den das Ledger-Design vermeiden soll.
                # Follows und Gifts sind Reichweite, kein Geld, und duerfen weg.
                _cut = (_now - timedelta(days=OVERLAY_RETENTION_DAYS)).isoformat()
                cleaned_overlay = conn.execute(
                    "DELETE FROM overlay_events WHERE ts < ? AND kind <> 'donation'",
                    (_cut,)).rowcount or 0

            # W15 (Audit-Runde 3): kick_mod_log und audit_log hatten INSERTs,
            # aber NIE ein DELETE — sie wuchsen unbegrenzt (jede AZRAEL-Chatzeile
            # und jeder Schreibzugriff landet dort). Ueber Monate blaeht das die
            # DB auf: langsamere Abfragen, groessere Backups, Plattendruck.
            if MODLOG_RETENTION_DAYS > 0:
                _cut = (_now - timedelta(days=MODLOG_RETENTION_DAYS)).isoformat()
                cleaned_modlog = conn.execute(
                    "DELETE FROM kick_mod_log WHERE ts < ?", (_cut,)).rowcount or 0
            if AUDITLOG_RETENTION_DAYS > 0:
                _cut = (_now - timedelta(days=AUDITLOG_RETENTION_DAYS)).isoformat()
                cleaned_audit = conn.execute(
                    "DELETE FROM audit_log WHERE created_at < ?", (_cut,)).rowcount or 0

            if (cleaned_events or cleaned_ailog or thinned_snaps or cleaned_overlay
                    or cleaned_modlog or cleaned_audit):
                conn.commit()
            if cleaned_modlog or cleaned_audit:
                log.info("Retention: %d Mod-Log- und %d Audit-Zeilen entfernt.",
                         cleaned_modlog, cleaned_audit)
    except Exception as e:
        log.warning("Retention Log-Tabellen fehlgeschlagen: %s", e)

    rows = [
        ("Orphan-Locks", cleaned_locks),
        ("Checks (>%dd)" % CHECKS_RETENTION_DAYS, cleaned_checks),
        ("Event-Log (>%dd)" % EVENTLOG_RETENTION_DAYS, cleaned_events),
        ("AI-Log (>%dd)" % AI_LOG_RETENTION_DAYS, cleaned_ailog),
        ("Snapshots ausgeduennt", thinned_snaps),
        ("Overlay ohne Spenden (>%dd)" % OVERLAY_RETENTION_DAYS, cleaned_overlay),
        ("Probe-Files (>24h)", cleaned_probes),
        ("Orphan-Parts (>1h)", cleaned_orphan_parts),       # F69
        ("Attempts (>30d)", cleaned_attempts),
    ]
    body = pre_table([(k, str(v)) for k, v in rows], align='left')
    await msg.edit_text(_nc_i18n.t(f"🧹 <b>CLEANUP</b>\n{body}"), parse_mode=ParseMode.HTML)


async def stats(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F19: globale Bot-Statistik (Trackings, Recordings, AI, Disk-Usage)."""
    if not _is_authorized(update): return
    with db_conn() as conn:
        n_trackings = conn.execute("SELECT COUNT(*) FROM trackings").fetchone()[0]
        n_active    = conn.execute("SELECT COUNT(*) FROM trackings WHERE recording=1").fetchone()[0]
        n_live      = conn.execute("SELECT COUNT(*) FROM trackings WHERE last_live=1").fetchone()[0]
        n_recs      = conn.execute("SELECT COUNT(*) FROM recordings").fetchone()[0]
        n_attempts  = conn.execute("SELECT COUNT(*) FROM recording_attempts").fetchone()[0]
        n_attempts_ok = conn.execute(
            "SELECT COUNT(*) FROM recording_attempts WHERE outcome='ok'").fetchone()[0]
        n_checks    = conn.execute("SELECT COUNT(*) FROM tiktok_checks").fetchone()[0]
        n_ai        = conn.execute("SELECT COUNT(*) FROM ai_log").fetchone()[0]

    # Disk-Usage von Recordings
    rec_size = 0
    rec_files = 0
    try:
        for f in glob.glob(os.path.join(RECORDINGS_DIR, "*.mp4")):
            try:
                rec_size += os.path.getsize(f); rec_files += 1
            except OSError: pass
    except Exception: pass

    # Bot-Uptime
    uptime_secs = (datetime.now(timezone.utc) - _BOT_START_TIME).total_seconds() \
        if _BOT_START_TIME else 0

    success_rate = (n_attempts_ok / n_attempts * 100) if n_attempts else 0

    lines = [("Uptime",     fmt_duration(uptime_secs)),
             ("Trackings",  f"{n_trackings} ({n_live} live, {n_active} aufnehmend)"),
             ("Recordings", f"{n_recs} ({rec_files} files, {rec_size/1024/1024:.0f} MB)"),
             ("Versuche",   f"{n_attempts} ({success_rate:.0f}% ok)"),
             ("/tiktok-Calls", str(n_checks)),
             ("/ai-Calls",  str(n_ai))]
    body = pre_table(lines, align='left')
    await update.message.reply_text(_nc_i18n.t(f"<b>📊 STATS</b>\n{body}"),
                                    parse_mode=ParseMode.HTML)


# ============================================================
# F55: Daily Summary Report
# ============================================================
# Einmal am Tag (Default 09:00 lokal) ein Status-Briefing in einen
# konfigurierten Chat posten. Beinhaltet: Aktivität letzte 24h
# (Aufnahmen, Versuche, Erfolgsquote), Top-3 User, Storage-Status,
# Cookie-Health. Aktiviert via DAILY_SUMMARY_CHAT_ID env var.
# Auch on-demand via /summary command verfügbar.

DAILY_SUMMARY_CHAT_ID = _env_int("DAILY_SUMMARY_CHAT_ID", 0)   # 0 = disabled
DAILY_SUMMARY_HOUR = _env_int_range("DAILY_SUMMARY_HOUR", 9, 0, 23)         # 0-23, lokal

# F61: Disk-Space-Alarm
# Warnt EINMAL wenn Disk-Usage über DISK_ALARM_THRESHOLD geht (transition-
# basiert — kein Spam). Reset wenn wieder unter Threshold. Separater Chat
# möglich, fallback DAILY_SUMMARY_CHAT_ID. Loop läuft alle DISK_ALARM_INTERVAL
# Sekunden (default 1h — Polling, weil Recordings die Disk auch wieder freigeben).
DISK_ALARM_CHAT_ID = _env_int("DISK_ALARM_CHAT_ID", 0)   # 0 = nutzt DAILY_SUMMARY_CHAT_ID
# B38: 1-100% sinnvoller Bereich. Vorher: =200 → silent failure (nie alarm).
DISK_ALARM_THRESHOLD = _env_int_range("DISK_ALARM_THRESHOLD", 85, 1, 100)
# B38: min 60s damit nicht jemand versehentlich =0 setzt (busy-loop).
DISK_ALARM_INTERVAL = _env_int_range("DISK_ALARM_INTERVAL", 3600, 60, 86400)
_DISK_ALARM_LAST_STATE = {"over": False}   # Transition-Tracking
# #3: Proaktiver Cookie-Alarm (Telegram) BEVOR kritische Auth-Cookies ablaufen — sonst
# bricht der Recorder still (403). Nutzt dieselbe Kadenz/Chat wie der Disk-Alarm.
COOKIE_ALARM_ENABLED = os.getenv("COOKIE_ALARM_ENABLED", "1").strip().lower() in ("1","true","yes","on","y")
_COOKIE_ALARM_LAST = {"level": "ok"}       # Transition-Tracking (ok|warn|crit)

# F63: Quiet Hours — während dieser Stunden (lokal) werden LIVE-Notifications
# unterdrückt (Aufnahmen + Uploads laufen weiter, nur kein "@user is LIVE!"-Spam
# nachts). Stunden inklusive Start, exklusive End: START=22, END=7 → quiet 22:00-07:00.
# Wenn START==END oder beide 0 → Feature deaktiviert.
# B38: clampen auf 0-23 statt blind übernehmen.
QUIET_HOURS_START = _env_int_range("QUIET_HOURS_START", 0, 0, 23)
QUIET_HOURS_END   = _env_int_range("QUIET_HOURS_END", 0, 0, 23)

# F67: Startup/Shutdown-Notifications
# Wenn gesetzt, postet der Bot bei jedem Start/Stop eine Nachricht in den
# konfigurierten Chat. Default: nutzt DAILY_SUMMARY_CHAT_ID falls vorhanden.
# Auf 0 = explizit deaktiviert. Praktisch um zu sehen wann der Bot gecrasht
# ist (wenn nur Startup-Notif kommt ohne vorheriges Shutdown).
STARTUP_NOTIFY_CHAT_ID = _env_int("STARTUP_NOTIFY_CHAT_ID", 0)
BRAIN_ALERT_CHAT_ID = _env_int("BRAIN_ALERT_CHAT_ID", 0)   # B153: Ziel fuer Sentinel-Alarme (0 = Fallback-Kette)

# B153: Brain-Sentinel-crit-Alarme -> Telegram. Laeuft aus dem Brain-Thread,
# daher fire-and-forget auf den Main-Loop (blockiert den Tick nie). Fail-open.
_BRAIN_NOTIFY_SEEN: dict = {}                 # text -> monotonic (Spam-Bremse)
_BRAIN_NOTIFY_COOLDOWN_S = _env_int("BRAIN_NOTIFY_COOLDOWN_S", 1200)


def _brain_notify(text: str):
    """B153: Sentinel-crit-Alarm an Telegram. Zielkette:
       BRAIN_ALERT_CHAT_ID -> DISK/DAILY/STARTUP_CHAT_ID -> DM an erste Admin-ID.
       Spam-Bremse: identischer Text im Cooldown wird verworfen. Wirft NIE nach aussen."""
    try:
        chat_id = (BRAIN_ALERT_CHAT_ID or DISK_ALARM_CHAT_ID
                   or DAILY_SUMMARY_CHAT_ID or STARTUP_NOTIFY_CHAT_ID)
        if not chat_id and ALLOWED_USER_IDS:
            chat_id = sorted(ALLOWED_USER_IDS)[0]      # Fallback: DM an Admin
        if not chat_id:
            log.warning("BRAIN-ALARM (kein Ziel-Chat gesetzt): %s", text)
            return
        now = _time_mod.monotonic()
        last = _BRAIN_NOTIFY_SEEN.get(text)
        if last is not None and (now - last) < _BRAIN_NOTIFY_COOLDOWN_S:
            return                                     # identischer Alarm im Cooldown
        _BRAIN_NOTIFY_SEEN[text] = now
        if len(_BRAIN_NOTIFY_SEEN) > 200:
            cutoff = now - _BRAIN_NOTIFY_COOLDOWN_S
            for k in [k for k, v in list(_BRAIN_NOTIFY_SEEN.items()) if v < cutoff]:
                _BRAIN_NOTIFY_SEEN.pop(k, None)
        loop = globals().get("_MAIN_LOOP")
        _app = globals().get("bot_app")
        if loop is None or not loop.is_running() or _app is None:
            log.warning("BRAIN-ALARM (Loop/Bot nicht bereit): %s", text)
            return
        asyncio.run_coroutine_threadsafe(_safe_send(_app.bot, chat_id, text), loop)
    except Exception as e:
        log.warning("brain-notify Fehler: %s (%s)", e, text)

def _is_quiet_hours(now: Optional[datetime] = None) -> bool:
    """F63: True wenn die aktuelle LOKALE Uhrzeit in der quiet-window liegt.
       Window wraps over midnight wenn END < START (z.B. 22-7 = von 22:00
       bis 07:00 next day). Falls START==END: deaktiviert."""
    if QUIET_HOURS_START == QUIET_HOURS_END:
        return False
    h = (now or datetime.now()).hour
    if QUIET_HOURS_START < QUIET_HOURS_END:
        # z.B. 9-17 → quiet von 9 bis 17 (Geschäftszeiten Suppression)
        return QUIET_HOURS_START <= h < QUIET_HOURS_END
    # z.B. 22-7 → quiet von 22-23 ODER 0-6 (wraps midnight)
    return h >= QUIET_HOURS_START or h < QUIET_HOURS_END


def _build_daily_summary() -> str:
    """Baut den Summary-Text. Synchron — alles aus DB. Wird auch von
       /summary command + autopost benutzt."""
    now = datetime.now(timezone.utc)
    cutoff = (now - timedelta(hours=24)).isoformat()
    with db_conn() as conn:
        # Aktuelle Status-Zahlen
        n_track = conn.execute("SELECT COUNT(*) AS c FROM trackings").fetchone()["c"]
        n_paused = conn.execute(
            "SELECT COUNT(*) AS c FROM trackings WHERE COALESCE(paused,0)=1"
        ).fetchone()["c"]
        n_live = conn.execute(
            "SELECT COUNT(*) AS c FROM trackings WHERE last_live=1").fetchone()["c"]
        n_rec_active = conn.execute(
            "SELECT COUNT(*) AS c FROM trackings WHERE recording=1").fetchone()["c"]

        # Last-24h-Aktivität
        rec_24h = conn.execute(
            "SELECT COUNT(*) AS c FROM recordings WHERE created_at >= ?", (cutoff,)
        ).fetchone()["c"]
        att_24h_total = conn.execute(
            "SELECT COUNT(*) AS c FROM recording_attempts WHERE started_at >= ?",
            (cutoff,)).fetchone()["c"]
        att_24h_ok = conn.execute(
            "SELECT COUNT(*) AS c FROM recording_attempts WHERE started_at >= ? "
            "AND outcome IN ('ok', 'stall_killed_partial')", (cutoff,)
        ).fetchone()["c"]
        att_24h_ed = conn.execute(
            "SELECT COUNT(*) AS c FROM recording_attempts WHERE started_at >= ? "
            "AND outcome = 'early_disconnect'", (cutoff,)).fetchone()["c"]

        # Top 3 User der letzten 24h nach Aufnahmen
        top_rows = conn.execute(
            "SELECT username, COUNT(*) AS n FROM recordings "
            "WHERE created_at >= ? GROUP BY username ORDER BY n DESC LIMIT 3",
            (cutoff,)).fetchall()

    success_pct = int(att_24h_ok / att_24h_total * 100) if att_24h_total else 0

    # Storage
    storage = get_storage_stats()
    disk = storage.get("disk", {}) or {}
    rec_size_mb = (storage.get("recordings_dir", {}).get("total_bytes") or 0) / 1024 / 1024
    disk_pct = None
    if disk.get("total_bytes") and disk.get("used_bytes"):
        disk_pct = int(disk["used_bytes"] / disk["total_bytes"] * 100)

    # Cookie-Health
    ch = get_cookie_health()

    # Bauen
    lines = []
    lines.append(f"<b>📋 DAILY SUMMARY</b> <i>{now.strftime('%d.%m.%Y')}</i>")
    lines.append("")
    lines.append("<b>Status jetzt:</b>")
    lines.append(f"  {n_track} Trackings ({n_live} live, {n_rec_active} aufnehmend"
                 + (f", {n_paused} pausiert" if n_paused else "") + ")")
    lines.append("")
    lines.append("<b>Letzte 24h:</b>")
    if att_24h_total:
        lines.append(f"  {rec_24h} Aufnahmen erfolgreich gespeichert")
        lines.append(f"  {att_24h_total} Versuche · {success_pct}% Erfolg"
                     + (f" · {att_24h_ed} early-disconnects" if att_24h_ed else ""))
    else:
        lines.append("  <i>keine Aufnahme-Aktivität</i>")

    if top_rows:
        lines.append("")
        lines.append("<b>Top User (24h):</b>")
        for i, r in enumerate(top_rows, 1):
            lines.append(f"  {i}. @{safe(r['username'])} — {r['n']} Aufnahmen")

    lines.append("")
    lines.append("<b>Storage:</b>")
    if disk_pct is not None:
        warn = " ⚠️" if disk_pct > 85 else ""
        lines.append(f"  Disk: {disk_pct}% belegt{warn}")
    lines.append(f"  Recordings: {rec_size_mb:.0f} MB")
    if storage.get("retention_days") and storage["retention_days"] > 0:
        lines.append(f"  Auto-Cleanup: nach {storage['retention_days']} Tagen")

    lines.append("")
    lines.append("<b>Cookies:</b>")
    icon = {"ok": "✅", "warning": "⚠️", "critical": "🚨",
            "missing": "❌", "parse_error": "❌"}.get(ch["status"], "❓")
    lines.append(f"  {icon} {ch['headline']}")

    return "\n".join(lines)


async def summary_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F55: On-demand Status-Briefing in den aktuellen Chat."""
    if not _is_authorized(update): return
    try:
        text = _build_daily_summary()
    except Exception as e:
        log.error(f"summary_cmd build failed: {e}", exc_info=True)
        await update.message.reply_text(_nc_i18n.t(f"❌ Summary fehlgeschlagen: {e}")); return
    await update.message.reply_text(_nc_i18n.t(text), parse_mode=ParseMode.HTML)


# ---- V37: Kick-Zuschauer-Sampler (Sende-Timeline bekommt Kontext) ------------
_VIEWER_SAMPLES = _collections.deque(maxlen=720)   # (ts, count) — ~12h bei 60s-Takt


def _kick_slug():
    # v4.1-W9: nach nc/kickapi.py geloest, damit nc/routes/kick.py den Slug
    # direkt importieren kann statt ueber nc.ctx.
    return _nc_kickapi.slug()


# B138: Kick-Follower. Die offizielle API v1 /public/v1/channels liefert
# followers_count NICHT — deshalb stand im Kanalstatus dauerhaft ein Strich,
# waehrend Zuschauer und Titel korrekt ankamen (der Aufruf klappt ja, das Feld
# fehlt schlicht). Twitch zeigt seine Zahl, weil es dafuer einen EIGENEN
# Endpunkt gibt (helix/channels/followers). Das Gegenstueck fuer Kick ist der
# keyless v2-Endpunkt, den _viewer_sample_loop ohnehin schon anspricht.
_KICK_FOLLOWERS = {"n": None, "ts": 0.0}
_KICK_FOLLOWERS_TTL = 300.0     # Follower aendern sich langsam; 5 min reichen


async def _kick_follower_count(session=None):
    """Follower-Zahl ueber kick.com/api/v2/channels/<slug> (public, keyless).

    Gecacht, weil channel_info() aus der Verify-Schleife im Prueftakt laeuft —
    ohne Cache haetten wir alle 120 s einen zusaetzlichen Fremdabruf, nur um
    eine Zahl anzuzeigen, die sich stundenlang nicht aendert.
    Rueckgabe None = nicht ermittelbar; der Aufrufer zeigt dann den Strich.
    """
    now = _time_mod.monotonic()
    if (_KICK_FOLLOWERS["n"] is not None
            and now - _KICK_FOLLOWERS["ts"] < _KICK_FOLLOWERS_TTL):
        return _KICK_FOLLOWERS["n"]
    slug = _kick_slug()
    if not slug:
        # Ohne KICK_CHANNEL_URL kennen wir den Kanal nicht. Einmal sagen,
        # nicht bei jedem Takt — sonst flutet es das Log.
        if _KICK_FOLLOWERS["ts"] == 0.0:
            log.info("Kick-Follower: KICK_CHANNEL_URL nicht gesetzt — ohne den "
                     "Kanal-Link laesst sich die Zahl nicht abrufen.")
            _KICK_FOLLOWERS["ts"] = now
        return None
    try:
        import aiohttp
        sess = session or await _get_ai_session()
        async with sess.get(
                f"https://kick.com/api/v2/channels/{slug}",
                timeout=aiohttp.ClientTimeout(total=10),
                headers={"User-Agent": "Mozilla/5.0"}) as r:
            if r.status != 200:
                log.debug("Kick-Follower: HTTP %s fuer %s", r.status, slug)
                return _KICK_FOLLOWERS["n"]
            j = await r.json(content_type=None)
        n = j.get("followers_count")
        if n is None:
            n = j.get("followersCount")     # Feldname hat schon einmal gewechselt
        if n is not None:
            _KICK_FOLLOWERS.update(n=int(n), ts=now)
            return int(n)
    except Exception as e:
        # Kein Fehlerfall fuer den Betreiber: die Zahl ist Beiwerk, der
        # Sendebetrieb haengt nicht daran. Aber nachvollziehbar bleiben.
        log.debug("Kick-Follower nicht abrufbar: %s", e)
    return _KICK_FOLLOWERS["n"]


async def _viewer_sample_loop():
    """Pollt kick.com/api/v2/channels/<slug> (public, keyless) alle 60s —
       aber NUR solange ein Restream läuft. Speichert (ts, viewer_count) für
       Timeline/Report; Fehler sind still (Viewer sind nice-to-have)."""
    import aiohttp
    slug = _kick_slug()
    if not slug:
        return
    while True:
        try:
            await asyncio.sleep(60)
            if not _RESTREAM_ACTIVE_ALL:
                continue
            session = await _get_ai_session()
            async with session.get(
                    f"https://kick.com/api/v2/channels/{slug}",
                    timeout=aiohttp.ClientTimeout(total=10),
                    headers={"User-Agent": "Mozilla/5.0"}) as r:
                if r.status != 200:
                    continue
                j = await r.json(content_type=None)
            ls = j.get("livestream") or {}
            cnt = ls.get("viewer_count")
            if cnt is not None:
                _VIEWER_SAMPLES.append((_time_mod.time(), int(cnt)))
        except asyncio.CancelledError:
            return
        except Exception as e:
            # Vorher stilles continue: faellt die Stichprobe dauerhaft aus,
            # bleibt die Zuschauerkurve leer und niemand erfaehrt warum.
            _loop_fehler("_viewer_sample_loop", e)
            continue



# v4.1-W9: Cache und Sendeprotokoll liegen in nc/kickapi.py. Die Aliase halten
# die 12 Lesestellen im Bot-Kern unveraendert — und es ist DASSELBE Objekt:
# der Sendepfad hier schreibt, /api/kick/sendcheck im Blueprint liest. Eine
# zweite Kopie und die Diagnose meldete ewig "noch kein Sendeversuch".
_KICK_BID_CACHE = _nc_kickapi.BID_CACHE
_KICK_SEND_LAST = _nc_kickapi.SEND_LAST


async def _kick_broadcaster_id():
    return await _nc_kickapi.broadcaster_id()


def _viewer_stats(since_ts=None):
    pts = [(t, c) for (t, c) in _VIEWER_SAMPLES if not since_ts or t >= since_ts]
    if not pts:
        return {"now": None, "peak": None, "avg": None, "points": []}
    vals = [c for _, c in pts]
    return {"now": vals[-1], "peak": max(vals),
            "avg": round(sum(vals) / len(vals)),
            "points": [{"t": int(t), "v": c} for t, c in pts[-120:]]}


async def _db_vacuum_loop():
    """V37: wöchentliches VACUUM+ANALYZE — ERGÄNZT die F82-Loop (die macht
       alle 6h wal_checkpoint+optimize, aber bewusst kein VACUUM). VACUUM
       kompaktiert die Datei nach Monaten von Inserts/Deletes wirklich.
       Nur SQLite; MariaDB-Backend ist ein No-op."""
    if DB_BACKEND == "mariadb":
        return
    while True:
        try:
            await asyncio.sleep(7 * 24 * 3600)
            def _run():
                with db_conn() as conn:
                    # Nicht still: schlaegt das woechentlich fehl, waechst die
                    # Datenbank unbegrenzt weiter und der Planer arbeitet mit
                    # veralteter Statistik — beides sieht man erst viel spaeter.
                    try:
                        conn.execute("ANALYZE")
                    except Exception as e:
                        _loop_fehler("_db_vacuum_loop/ANALYZE", e)
                    try:
                        conn.execute("VACUUM")
                    except Exception as e:
                        _loop_fehler("_db_vacuum_loop/VACUUM", e)
            await asyncio.to_thread(_run)
            log.info("DB-Wartung: ANALYZE+VACUUM durchgelaufen.")
        except asyncio.CancelledError:
            return
        except Exception as e:
            log.warning("DB-Wartung: %s", e)


async def _daily_summary_loop(bot_app):
    """F55: Hintergrund-Loop. Wartet bis zur nächsten Stunde X (DAILY_SUMMARY_HOUR),
       postet das Summary in DAILY_SUMMARY_CHAT_ID, schläft 24h."""
    while True:
        try:
            now = datetime.now()
            # Nächste DAILY_SUMMARY_HOUR im lokalen TZ berechnen
            target = now.replace(hour=DAILY_SUMMARY_HOUR, minute=0, second=0, microsecond=0)
            if target <= now:
                target += timedelta(days=1)
            wait_secs = max(60, (target - now).total_seconds())
            log.info(f"Daily-Summary nächster Run: {target} (in {wait_secs/3600:.1f}h)")
            await asyncio.sleep(wait_secs)
            try:
                text = _build_daily_summary()
                await bot_app.bot.send_message(
                    chat_id=DAILY_SUMMARY_CHAT_ID,
                    text=text, parse_mode=ParseMode.HTML)
                log.info(f"Daily-Summary erfolgreich gepostet zu chat={DAILY_SUMMARY_CHAT_ID}")
            except Exception as e:
                log.error(f"Daily-Summary posten fehlgeschlagen: {e}", exc_info=True)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error(f"_daily_summary_loop unerwarteter Fehler: {e}", exc_info=True)
            await asyncio.sleep(3600)   # bei Wiederholung Fehler nicht zu schnell


async def _disk_alarm_loop(bot_app):
    """F61: Pollt Disk-Usage alle DISK_ALARM_INTERVAL Sekunden. Postet EINMAL
       eine Warnung wenn Threshold überschritten wird (transition-basiert).
       Reset wenn wieder unter Threshold. So kein Spam wenn Disk dauerhaft
       voll ist — aber neue Warnung wenn nach Cleanup wieder voll läuft."""
    chat_id = DISK_ALARM_CHAT_ID or DAILY_SUMMARY_CHAT_ID
    if not chat_id:
        log.warning("Disk-Alarm: kein chat_id konfiguriert — Loop beendet sich")
        return
    while True:
        try:
            try:
                storage = get_storage_stats()
                disk = storage.get("disk") or {}
                total = disk.get("total_bytes")
                used = disk.get("used_bytes")
                if total and used:
                    pct = int(used / total * 100)
                    was_over = _DISK_ALARM_LAST_STATE["over"]
                    is_over = pct >= DISK_ALARM_THRESHOLD
                    # B40: State-Update gilt erst bei erfolgreichem Send.
                    # Vorher: send_message() failed (Telegram-Outage, Network-Blip)
                    # → wir loggen den Fehler, aber _DISK_ALARM_LAST_STATE["over"]
                    # wurde trotzdem auf True gesetzt → nächste Iteration sieht
                    # KEINE Transition mehr → Alert ist für immer verloren bis
                    # Disk unter Threshold rutscht und wieder rauf geht.
                    # Jetzt: State nur updaten wenn delivered (oder kein Transition).
                    delivered = True
                    if is_over and not was_over:
                        # Transition into overflow → alert
                        free_gb = round((total - used) / 1024**3, 1)
                        rec_size_mb = (storage.get("recordings_dir", {})
                                       .get("total_bytes") or 0) / 1024 / 1024
                        retention = storage.get("retention_days") or 0
                        msg = (f"🚨 <b>DISK-ALARM</b>\n\n"
                               f"Disk-Usage: <b>{pct}%</b> "
                               f"(Threshold: {DISK_ALARM_THRESHOLD}%)\n"
                               f"Frei: {free_gb} GB\n"
                               f"Recordings: {rec_size_mb:.0f} MB\n")
                        if retention == 0:
                            msg += ("\n<i>Tipp: RECORDINGS_RETAIN_DAYS in .env setzen "
                                    "für automatisches Cleanup, oder im Dashboard "
                                    "manuell Cleanup ausführen.</i>")
                        else:
                            msg += f"\n<i>Auto-Cleanup aktiv: {retention}d Retention.</i>"
                        try:
                            await bot_app.bot.send_message(
                                chat_id=chat_id, text=msg, parse_mode=ParseMode.HTML)
                            log.warning(f"Disk-Alarm gepostet: {pct}% belegt")
                        except Exception as e:
                            log.error(f"Disk-Alarm send failed: {e} — "
                                      f"state NICHT geupdated, retry beim nächsten Tick")
                            delivered = False
                    elif not is_over and was_over:
                        # Transition out of overflow → relief notification
                        try:
                            await bot_app.bot.send_message(
                                chat_id=chat_id,
                                text=f"✅ <b>Disk wieder OK</b> ({pct}%)",
                                parse_mode=ParseMode.HTML)
                            log.info(f"Disk-Alarm cleared: {pct}%")
                        except Exception as e:
                            log.warning(f"Disk-Alarm relief send failed: {e} — "
                                        f"state NICHT geupdated, retry beim nächsten Tick")
                            delivered = False
                    if delivered:
                        _DISK_ALARM_LAST_STATE["over"] = is_over
            except Exception as e:
                # v4.1-W5: war log.warning. Scheitert die PRUEFUNG dauerhaft,
                # feuert der Platten-Alarm nie — und die Schleife laeuft weiter,
                # von aussen ununterscheidbar von "Platte in Ordnung".
                _loop_fehler("_disk_alarm_loop/check", e)
            await asyncio.sleep(DISK_ALARM_INTERVAL)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error(f"_disk_alarm_loop unerwarteter Fehler: {e}", exc_info=True)
            await asyncio.sleep(DISK_ALARM_INTERVAL)




async def _cookie_alarm_loop(bot_app):
    """#3: Proaktiver Cookie-Alarm. Pollt get_cookie_health() und postet EINMAL pro
       Zustandswechsel (ok→warn→crit) nach Telegram — kein Spam, Relief bei Rückkehr
       auf 'ok'. Gleiche Kadenz/Chat wie der Disk-Alarm. So sieht man Cookie-Ablauf
       BEVOR der Recorder still scheitert, statt erst beim Nachsehen."""
    chat_id = DISK_ALARM_CHAT_ID or DAILY_SUMMARY_CHAT_ID
    if not chat_id:
        log.warning("Cookie-Alarm: kein chat_id konfiguriert — Loop beendet sich")
        return
    await asyncio.sleep(60)        # Boot abwarten
    while True:
        try:
            try:
                h = get_cookie_health()
                level, msg = _cookie_alarm_level(h)
                last = _COOKIE_ALARM_LAST["level"]
                if level != "ok" and level != last:
                    try:
                        await bot_app.bot.send_message(chat_id=chat_id, text=msg,
                                                       parse_mode=ParseMode.HTML)
                        _COOKIE_ALARM_LAST["level"] = level
                        log.warning("Cookie-Alarm (%s) gepostet: %s", level, h.get("headline"))
                    except Exception as e:
                        log.error("Cookie-Alarm send failed: %s — retry nächster Tick", e)
                elif level == "ok" and last != "ok":
                    try:
                        await bot_app.bot.send_message(
                            chat_id=chat_id, text="✅ <b>Cookies wieder OK</b>",
                            parse_mode=ParseMode.HTML)
                        _COOKIE_ALARM_LAST["level"] = "ok"
                        log.info("Cookie-Alarm cleared")
                    except Exception as e:
                        log.warning("Cookie-Alarm relief send failed: %s", e)
            except Exception as e:
                # v4.1-W5: war log.warning — dasselbe Muster wie beim
                # Platten-Alarm: scheitert die Pruefung, meldet niemand mehr
                # abgelaufene Cookies, und Aufnahmen scheitern spaeter mit 403.
                _loop_fehler("_cookie_alarm_loop/check", e)
            await asyncio.sleep(DISK_ALARM_INTERVAL)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            log.error("_cookie_alarm_loop unerwarteter Fehler: %s", e, exc_info=True)
            await asyncio.sleep(DISK_ALARM_INTERVAL)


async def bulkadd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F56: Bulk-add mehrere Trackings in einem Befehl.
       Usage: /bulkadd @user1 @user2 user3 ...
       Oder: als Reply zu einem Text mit User-Liste → der Reply-Text wird gesplittet."""
    if not _is_authorized(update): return
    chat_id = update.effective_chat.id
    user_id = update.effective_user.id

    # Argument-Quellen: explizite Args, ODER Reply-Text
    raw = " ".join(context.args or [])
    if not raw and update.message.reply_to_message and update.message.reply_to_message.text:
        raw = update.message.reply_to_message.text
    if not raw:
        await update.message.reply_text(
            "<i>Benutzung:</i>\n"
            "<code>/bulkadd @user1 @user2 user3 …</code>\n"
            "Oder reply auf eine Nachricht mit der User-Liste.",
            parse_mode=ParseMode.HTML); return
    candidates = [c for c in re.split(r'[\s,;\n]+', raw) if c]
    if not candidates:
        await update.message.reply_text(_nc_i18n.t("⚠️ Keine Usernames erkannt.")); return
    if len(candidates) > 200:
        await update.message.reply_text(
            "⚠️ Max 200 Usernames pro Bulk-Call. "
            f"Du hast {len(candidates)} angegeben — bitte aufteilen."); return

    result = bulk_add_trackings(chat_id, candidates, added_by=user_id)

    # Sofort-Recheck für alle neuen
    if result["added"]:
        try:
            with db_conn() as conn:
                rows = conn.execute(
                    "SELECT id FROM trackings WHERE group_id=? AND username IN ("
                    + ",".join("?" * len(result["added"])) + ")",
                    [chat_id] + result["added"]
                ).fetchall()
                for r in rows:
                    _NEXT_CHECK_AT[r["id"]] = 0
        except Exception as e:
            log.warning(f"bulkadd: recheck setup failed: {e}")

    lines = [f"📦 <b>BULK ADD</b> ({len(candidates)} verarbeitet)",
             f"  ✅ {len(result['added'])} hinzugefügt"]
    if result["duplicates"]:
        lines.append(f"  ⏭ {len(result['duplicates'])} bereits getrackt")
    if result["invalid"]:
        lines.append(f"  ❌ {len(result['invalid'])} ungültig")
    # F64: Quota-Hinweise wenn MAX_TRACKINGS_PER_CHAT greift
    qe = result.get("quota_exceeded", [])
    if qe:
        lines.append(f"  🚫 {len(qe)} abgelehnt (Quota erreicht: "
                     f"{MAX_TRACKINGS_PER_CHAT}/Chat)")
    # Erste 10 hinzugefügte anzeigen
    if result["added"]:
        sample = ", ".join(f"@{safe(u)}" for u in result["added"][:10])
        more = f" + {len(result['added']) - 10} weitere" if len(result['added']) > 10 else ""
        lines.append("")
        lines.append(f"<i>Neu: {sample}{more}</i>")
    await update.message.reply_text(_nc_i18n.t("\n".join(lines)), parse_mode=ParseMode.HTML)


async def topusers(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F48: Top-N getrackte User nach gewähltem Sort-Kriterium.
       Usage: /topusers [N=10] [sort=rec|bytes|success|recent]
       Default: top 10 nach Anzahl Aufnahmen."""
    if not _is_authorized(update): return
    # Args parsen — sehr nachsichtig
    n = 10
    sort_alias = {
        "rec":     "rec_count",      "recs":    "rec_count",
        "bytes":   "total_bytes",    "size":    "total_bytes",
        "success": "success_rate",   "ok":      "success_rate",
        "recent":  "last_recording", "last":    "last_recording",
    }
    sort_key = "rec_count"
    for a in (context.args or []):
        a = a.strip().lower()
        if a.isdigit():
            n = max(1, min(50, int(a)))
        elif a in sort_alias:
            sort_key = sort_alias[a]

    rows = get_per_user_stats(limit=n, sort_by=sort_key)
    if not rows:
        await update.message.reply_text(
            "📊 <b>TOP USERS</b>\n<i>Noch keine Daten — sobald jemand live geht "
            "und aufgenommen wird, zähle ich.</i>",
            parse_mode=ParseMode.HTML)
        return

    sort_label = {
        "rec_count":      "nach Aufnahmen",
        "total_bytes":    "nach Datenvolumen",
        "success_rate":   "nach Erfolgsquote",
        "last_recording": "nach letzter Aufnahme",
    }[sort_key]

    # Tabelle bauen
    table_rows = []
    for i, r in enumerate(rows, start=1):
        # Spaltenwerte je nach Sortierung — primary value steht hinten
        mb = (r["total_bytes"] or 0) / 1024 / 1024
        sr_pct = int(r["success_rate"] * 100) if r["attempt_count"] else 0
        if sort_key == "total_bytes":
            primary = f"{mb:.0f}MB · {r['rec_count']} recs"
        elif sort_key == "success_rate":
            primary = f"{sr_pct}% ({r['attempt_ok_count']}/{r['attempt_count']})"
        elif sort_key == "last_recording":
            last = (r["last_recording_at"] or "")[:10] or "—"
            primary = f"{last} · {r['rec_count']} recs"
        else:   # rec_count
            primary = f"{r['rec_count']} recs · {mb:.0f}MB"
        table_rows.append((f"{i:>2}. @{r['username']}", primary))

    body = pre_table(table_rows, align='left')
    text = (f"📊 <b>TOP {len(rows)} USERS</b> <i>({sort_label})</i>\n"
            f"{body}\n"
            f"<i>Sortier-Optionen: rec · bytes · success · recent</i>")
    await update.message.reply_text(_nc_i18n.t(text), parse_mode=ParseMode.HTML)


async def cookies_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F52: Zeigt den Cookie-Health-Status. Hilft bei 'Aufnahmen
       funktionieren plötzlich nicht mehr' — wenn die TikTok-Auth-Cookies
       abgelaufen sind, scheitern Resolves still und der User wundert sich."""
    if not _is_authorized(update): return
    h = get_cookie_health()
    icon = {"ok": "✅", "warning": "⚠️", "critical": "🚨",
            "missing": "❌", "parse_error": "❌"}.get(h["status"], "❓")
    lines = [
        ("Status",   f"{icon} {h['headline']}"),
        ("Datei",    "✅ vorhanden" if h["exists"] else "❌ fehlt"),
    ]
    if h["exists"]:
        age = h.get("file_age_days")
        lines.append(("Alter",
                      f"{age}d alt" if age is not None else "—"))
        lines.append(("Cookies", f"{h['total']} insg., "
                                 f"{len(h['critical_present'])}/{len(_TIKTOK_CRITICAL_COOKIES)} kritisch"))
        if h.get("oldest_expiry_days") is not None:
            d = h["oldest_expiry_days"]
            lines.append(("Auth läuft", f"in {d}d ab"))
        if h["critical_missing"]:
            lines.append(("Fehlt",
                          ", ".join(h["critical_missing"][:4])
                          + ("…" if len(h["critical_missing"]) > 4 else "")))
        if h["expired"]:
            lines.append(("Abgelaufen",
                          f"{len(h['expired'])} cookies"))
        if h["expiring_soon"]:
            soon = h["expiring_soon"][:3]
            lines.append(("Bald weg",
                          ", ".join(f"{c['name']}({c['days_left']}d)" for c in soon)))
    body = pre_table(lines, align='left')

    extra = ""
    if h["status"] in ("critical", "missing"):
        extra = ("\n<i>→ TikTok-Cookies exportieren und nach <code>"
                 f"{COOKIE_FILE}</code> kopieren.\n"
                 "Empfohlene Tools: Cookie-Editor (Chrome/Firefox), "
                 "Export als Netscape-Format.</i>")
    elif h["status"] == "warning":
        extra = ("\n<i>→ Cookies bald erneuern um Probleme zu vermeiden.</i>")

    await update.message.reply_text(_nc_i18n.t(f"<b>🍪 COOKIES</b>\n{body}{extra}"),
                                    parse_mode=ParseMode.HTML)


async def _pause_resume_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE,
                             paused: bool):
    """F53: gemeinsame Logik für /pause und /resume — nur das Flag dreht sich."""
    if not _is_authorized(update): return
    chat_id = update.effective_chat.id
    if not context.args:
        verb = "pausieren" if paused else "wieder aktivieren"
        await update.message.reply_text(
            f"<i>Welchen User {verb}?</i>\n"
            f"<code>/{'pause' if paused else 'resume'} username</code>",
            parse_mode=ParseMode.HTML); return
    username = clean_username(context.args[0])
    if not username:
        await update.message.reply_text(_nc_i18n.t("⚠️ Ungültiger Username.")); return
    # Tracking-ID für diesen User in diesem Chat suchen
    with db_conn() as conn:
        row = conn.execute(
            "SELECT id FROM trackings WHERE group_id=? AND username=?",
            (chat_id, username)).fetchone()
    if not row:
        await update.message.reply_text(
            _nc_i18n.t(f"<i>@{safe(username)} wird in diesem Chat nicht getrackt.</i>"),
            parse_mode=ParseMode.HTML); return
    tid = row["id"]
    set_tracking_paused(tid, paused)
    if not paused:
        # Resume: sofort recheck
        try: _NEXT_CHECK_AT[tid] = 0
        except Exception: pass
    icon = "⏸" if paused else "▶️"
    state = "pausiert" if paused else "wieder aktiv"
    await update.message.reply_text(
        _nc_i18n.t(f"{icon} <b>@{safe(username)}</b> ist {state}."),
        parse_mode=ParseMode.HTML)


async def pause_tracking(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F53: Pausiert das Tracking für einen User. Laufende Aufnahme wird
       NICHT gestoppt — nur weitere verhindert."""
    await _pause_resume_cmd(update, context, paused=True)


async def resume_tracking(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F53: Setzt ein pausiertes Tracking wieder aktiv + triggert sofort
       einen Live-Check (kein Warten auf nächsten Polling-Tick)."""
    await _pause_resume_cmd(update, context, paused=False)


async def stoprec(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F59: Stoppt eine aktive Aufnahme grazil.
       Usage: /stoprec @user
       SIGTERM → ffmpeg flushed moov-atom → file bleibt valide. Cleanup-Pipeline
       läuft normal weiter."""
    if not _is_authorized(update): return
    chat_id = update.effective_chat.id
    if not context.args:
        await update.message.reply_text(
            "<i>Welche Aufnahme stoppen?</i>\n"
            "<code>/stoprec username</code>",
            parse_mode=ParseMode.HTML); return
    username = clean_username(context.args[0])
    if not username:
        await update.message.reply_text(_nc_i18n.t("⚠️ Ungültiger Username.")); return
    with db_conn() as conn:
        row = conn.execute(
            "SELECT id, pid FROM trackings "
            "WHERE group_id=? AND username=? AND recording=1",
            (chat_id, username)).fetchone()
    if not row:
        await update.message.reply_text(
            _nc_i18n.t(f"<i>Keine aktive Aufnahme für @{safe(username)} in diesem Chat.</i>"),
            parse_mode=ParseMode.HTML); return
    pid = row["pid"]
    if not pid:
        await update.message.reply_text(
            "⚠️ Recording-Flag gesetzt aber kein PID — der Reaper räumt das "
            "beim nächsten Tick (5s) auf."); return
    # F59-Bug-Fix B36: PID-Reuse-Schutz — siehe api_recording_stop für Details
    if not _proc_is_recorder(pid):
        await update.message.reply_text(
            f"⚠️ PID {pid} ist nicht (mehr) unser Recorder-Prozess — "
            "wahrscheinlich schon beendet. Der Reaper räumt beim nächsten "
            "Tick (5s) auf."); return
    try:
        os.kill(pid, _signal_mod.SIGTERM)
        log.info(f"F59: /stoprec SIGTERM an PID {pid} (@{username})")
        await update.message.reply_text(
            f"⏹ Aufnahme @<b>{safe(username)}</b> wird grazil gestoppt "
            f"(PID {pid}, SIGTERM).\nFile wird finalisiert + hochgeladen.",
            parse_mode=ParseMode.HTML)
    except ProcessLookupError:
        await update.message.reply_text(
            _nc_i18n.t("<i>Process schon weg — natürlicher Exit kommt jeden Moment.</i>"),
            parse_mode=ParseMode.HTML)
    except Exception as e:
        await update.message.reply_text(_nc_i18n.t(f"❌ Stop fehlgeschlagen: {e}"))


async def quota(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F66: Zeigt Tracking-Quota-Status für den aktuellen Chat.
       Total, davon paused/recording, % verwendet wenn Quota gesetzt.
       Hilft wenn man unter MAX_TRACKINGS_PER_CHAT-Limit läuft und
       wissen will wie nah man am Limit ist."""
    if not _is_authorized(update): return
    chat_id = update.effective_chat.id
    with db_conn() as conn:
        rows = conn.execute(
            "SELECT recording, COALESCE(paused, 0) AS paused, last_live "
            "FROM trackings WHERE group_id=?",
            (chat_id,)).fetchall()
    total = len(rows)
    paused_n = sum(1 for r in rows if r["paused"])
    recording_n = sum(1 for r in rows if r["recording"])
    live_n = sum(1 for r in rows if r["last_live"])
    active_n = total - paused_n

    lines = [("Chat-ID",  str(chat_id)),
             ("Trackings", str(total))]
    if MAX_TRACKINGS_PER_CHAT > 0:
        pct = int(total / MAX_TRACKINGS_PER_CHAT * 100)
        remaining = MAX_TRACKINGS_PER_CHAT - total
        # F66: ASCII-Balken
        n = int(round(pct / 10))
        bar = ("█" * min(n, 10)) + ("░" * max(0, 10 - n))
        lines.append(("Quota",    f"{bar} {pct}% ({total}/{MAX_TRACKINGS_PER_CHAT})"))
        lines.append(("Verbleibt", str(max(0, remaining))))
    else:
        lines.append(("Quota",    "unbegrenzt (MAX_TRACKINGS_PER_CHAT=0)"))
    lines.append(("Aktiv",       str(active_n)))
    if paused_n: lines.append(("Pausiert",   str(paused_n)))
    if live_n:   lines.append(("Live",       str(live_n)))
    if recording_n: lines.append(("Aufnehmend", str(recording_n)))

    body = pre_table(lines, align='left')

    extra = ""
    if MAX_TRACKINGS_PER_CHAT > 0:
        if total >= MAX_TRACKINGS_PER_CHAT:
            extra = ("\n<b>🚫 Quota erreicht.</b> Neue Trackings werden abgelehnt. "
                     "Erst alte mit <code>/untrack @user</code> entfernen.")
        elif total >= MAX_TRACKINGS_PER_CHAT * 0.9:
            extra = ("\n<i>⚠️ Quota fast voll.</i>")
    await update.message.reply_text(
        _nc_i18n.t(f"<b>📊 QUOTA</b>\n{body}{extra}"),
        parse_mode=ParseMode.HTML)


async def logs_cmd(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F68: Zeigt die letzten N ERROR-Zeilen aus logs/error.log.
       Usage: /logs [N]   (default 10, max 30)
       Praktisch für Remote-Diagnose ohne SSH — z.B. wenn der Bot in einer
       systemd-Unit läuft und man unterwegs ist."""
    if not _is_authorized(update): return
    n = 10
    if context.args:
        try: n = max(1, min(30, int(context.args[0])))
        except ValueError: pass
    log_path = os.path.join(LOG_DIR, "error.log")
    if not os.path.exists(log_path):
        await update.message.reply_text(
            _nc_i18n.t("<i>error.log existiert (noch) nicht — gut, vermutlich keine Fehler.</i>"),
            parse_mode=ParseMode.HTML); return
    # Efficient tail: read last ~64KB, split lines, take last N
    try:
        size = os.path.getsize(log_path)
        with open(log_path, "rb") as f:
            if size > 65536:
                f.seek(size - 65536)
                _ = f.readline()  # skip likely-incomplete first line
            tail = f.read().decode("utf-8", errors="replace")
    except Exception as e:
        await update.message.reply_text(_nc_i18n.t(f"❌ Konnte error.log nicht lesen: {e}")); return

    lines = [l for l in tail.splitlines() if l.strip()]
    if not lines:
        await update.message.reply_text(
            _nc_i18n.t("<i>error.log ist leer — keine Fehler.</i>"),
            parse_mode=ParseMode.HTML); return
    selected = lines[-n:]
    # Telegram-Limit beachten: 4096 chars. Wir kürzen jede Zeile + truncate.
    out_lines = []
    total_len = 0
    for line in selected:
        # F68: Stack-traces können extrem lang sein. Pro Zeile cappen.
        if len(line) > 280:
            line = line[:277] + "…"
        if total_len + len(line) + 1 > 3500:
            out_lines.append(f"<i>… {len(selected) - len(out_lines)} weitere Zeilen abgeschnitten</i>")
            break
        out_lines.append(line)
        total_len += len(line) + 1
    body = "\n".join(out_lines)
    # Code-Block für monospace
    await update.message.reply_text(
        f"<b>📜 ERROR LOG · letzte {len(selected)} Zeilen</b>\n"
        f"<pre>{safe(body)}</pre>",
        parse_mode=ParseMode.HTML)


async def sysres(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F54: Zeigt System- und Bot-Prozess-Ressourcen. Wichtig für
       Diagnose von rc=-9 (OOM-Killer) und Memory-/FD-Leaks."""
    if not _is_authorized(update): return
    # Wir rufen die JSON-Funktion direkt auf — gleiche Daten wie Dashboard.
    # Flask-Context brauchen wir nicht weil wir die Response nicht senden,
    # nur das Dict.
    try:
        with dashboard_app.test_request_context('/api/system-resources'):
            d = api_system_resources().get_json()
    except Exception as e:
        await update.message.reply_text(_nc_i18n.t(f"❌ System-Stats fehlgeschlagen: {e}"))
        return

    def _fmt_bar(pct):
        if pct is None: return "—"
        # 10-Block-Balken: gefüllt nach Prozent
        n = int(round(pct / 10))
        return ("█" * n) + ("░" * (10 - n))

    lines = [("Uptime",   fmt_duration(d.get("uptime_secs") or 0))]
    # Disk
    if d.get("disk_percent") is not None:
        lines.append(("Disk",
            f"{_fmt_bar(d['disk_percent'])} {d['disk_percent']}% "
            f"({d['disk_used_gb']}/{d['disk_total_gb']} GB)"))
    # RAM (System)
    if d.get("mem_percent") is not None:
        lines.append(("RAM",
            f"{_fmt_bar(d['mem_percent'])} {d['mem_percent']}% "
            f"(verfügbar {d['mem_avail_gb']} GB)"))
    # Load Avg
    if d.get("load_1") is not None:
        lines.append(("Load",
            f"{d['load_1']:.2f} / {d['load_5']:.2f} / {d['load_15']:.2f}"))
    # Bot-Prozess (das eigentlich Interessante)
    if d.get("bot_rss_mb") is not None:
        lines.append(("Bot-RSS",
            f"{d['bot_rss_mb']} MB"
            + (" ⚠️ hoch!" if d['bot_rss_mb'] > 1500 else "")))
    if d.get("bot_threads") is not None:
        lines.append(("Bot-Threads", str(d['bot_threads'])))
    if d.get("bot_open_fds") is not None:
        warn = " ⚠️ leak?" if d['bot_open_fds'] > 500 else ""
        lines.append(("Bot-FDs", f"{d['bot_open_fds']}{warn}"))
    # Subprocesses
    if d.get("ffmpeg_procs") is not None:
        lines.append(("ffmpeg-Procs", str(d['ffmpeg_procs'])))
    if d.get("ytdlp_procs") is not None and d['ytdlp_procs'] > 0:
        lines.append(("ytdlp-Procs", str(d['ytdlp_procs'])))
    # Recordings auf Disk
    lines.append(("Recordings",
        f"{d.get('recordings_count', 0)} files · "
        f"{d.get('recordings_size_mb', 0)} MB"))

    body = pre_table(lines, align='left')

    extras = []
    if d.get("disk_percent") and d["disk_percent"] > 90:
        extras.append("<b>⚠️ Disk fast voll!</b> RECORDINGS_RETAIN_DAYS setzen "
                      "oder /cleanup ausführen.")
    if d.get("bot_rss_mb") and d["bot_rss_mb"] > 1500:
        extras.append("<b>⚠️ Bot-RSS hoch.</b> Bei OOM-Killer-Verdacht: "
                      "<code>dmesg | tail -50</code>.")
    if d.get("ffmpeg_procs") and d["ffmpeg_procs"] > 10:
        extras.append("<b>⚠️ Viele ffmpeg-Prozesse.</b> Verwaiste Aufnahmen? "
                      "<code>/cleanup</code> probieren.")
    extra_txt = ("\n\n" + "\n".join(extras)) if extras else ""

    await update.message.reply_text(
        _nc_i18n.t(f"<b>🖥 SYSTEM RESOURCES</b>\n{body}{extra_txt}"),
        parse_mode=ParseMode.HTML)


async def on_ai_reply(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """F19: Reply auf eine vorherige AI-Antwort des Bots → automatisch als
       AI-Follow-up verarbeiten ohne dass /ai nochmal getippt werden muss.

       Triggered nur wenn:
       - Message ist Reply auf irgendeine Bot-Message
       - Reply-Text enthält keine andere /command (nicht mit / starten)
       - User hat Conversation-History (sonst könnte es Zufall sein)"""
    if not _is_authorized(update): return
    msg = update.message
    if not msg or not msg.text: return
    if msg.text.startswith("/"): return  # explizite Commands haben Vorrang

    reply_to = msg.reply_to_message
    if not reply_to: return
    me = await context.bot.get_me()
    if not reply_to.from_user or reply_to.from_user.id != me.id: return

    # Nur loslegen wenn die Conversation-History für (chat, user) existiert.
    # Vermeidet dass jeder Bot-Reply (z.B. Ankündigungen) AI triggert.
    user_id = update.effective_user.id
    chat_id = update.effective_chat.id
    history = await ai_history_load(chat_id, user_id)
    if not history:
        return

    await _run_ai_call(update, context, msg.text)


async def on_azrael_mention(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """B138: AZRAEL antwortet in Telegram auf direkte Ansprache.

    Vorher gab es dafuer GAR KEINEN Handler: registriert waren nur Medien mit
    /ai-Caption und Antworten AUF eine Bot-Nachricht. Wer den Bot mit
    "@Azrael ..." anschrieb — in der Gruppe wie im Privatchat — bekam nie eine
    Antwort, weil die Nachricht durch keinen Filter fiel. Auf Discord und im
    Stream-Chat existiert die Ansprache laengst; Telegram fehlte schlicht.

    Privatchat: jede normale Nachricht ist eine Ansprache — dafuer schreibt man
    einem Bot. In Gruppen nur bei genanntem Namen, sonst kommentierte AZRAEL
    jede Zeile mit.
    """
    if not _is_authorized(update):
        return
    msg = update.message
    if not msg or not msg.text:
        return
    text = msg.text.strip()
    if text.startswith("/"):
        return                                   # Commands haben Vorrang
    if msg.reply_to_message:
        return                                   # deckt on_ai_reply ab
    privat = (update.effective_chat
              and update.effective_chat.type == "private")
    if not (privat or "azrael" in text.lower()):
        return
    # Den Namen aus der Frage nehmen, sonst antwortet die KI auf sich selbst.
    frage = re.sub(r"@?azrael\b[:,]?\s*", "", text, flags=re.I).strip() or text
    await _run_ai_call(update, context, frage[:600])


