async def on_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    q = update.callback_query
    if not _is_authorized(update):
        await q.answer(_nc_i18n.t("Nicht autorisiert."), show_alert=True); return
    data = q.data or ""
    if data.startswith("s:"):                  # stop tracking
        username = clean_username(data[2:])
        if not username:
            await q.answer(_nc_i18n.t("Ungültig.")); return
        chat_id = q.message.chat.id
        # F24: strikter Auth-Check für destruktive Aktion
        allowed, reason = _can_stop_tracking(update, chat_id, username)
        if not allowed:
            await q.answer(_nc_i18n.t(reason), show_alert=True); return
        _nc_trackingdb.remove_tracking(chat_id, username)
        await q.answer(_nc_i18n.t(f"@{username} – Tracking beendet."))
        try:
            await q.edit_message_reply_markup(reply_markup=None)
        except Exception: pass
        try:
            who = update.effective_user
            who_name = f"@{who.username}" if who and who.username else (
                       f"User #{who.id}" if who else "unbekannt")
            await context.bot.send_message(
                chat_id,
                f"🗑 <b>TRACKING BEENDET · @{safe(username)}</b>\n"
                f"<i>per Schnellaktion · {safe(who_name)}</i>",
                parse_mode=ParseMode.HTML)
        except Exception: pass
    else:
        await q.answer()

# -----------------------------
# Live-Erkennung (TikTokLive)
# -----------------------------
async def _get_live_info(username: str, session=None, force_fresh: bool = False) -> dict:
    """F33: Liefert {is_live: True|False|None, info: dict|None}.
       None bedeutet 'konnte nicht ermittelt werden' — Worker macht in dem
       Fall NICHTS (kein Notif, kein Status-Update). Sonst würde ein einzelner
       Network-Fehler einen falschen OFFLINE-Notif auslösen und beim nächsten
       Check einen falschen LIVE-Notif — Notification-Spam.

       Vorher hat die Funktion TikTokLiveClient.is_live() benutzt: pro Check
       neue Verbindung, nutzt unsere Cookies nicht, inkonsistent. Jetzt
       direkt unseren bewährten Resolver (webcast-api → HTML-Fallback) mit
       30s Cache pro Username (Multi-Chat-Dedup)."""
    if session is None:
        # Fallback wenn kein Session übergeben — geht zur alten TikTokLive-Methode.
        # Sollte nur bei interaktiven Commands passieren wo wir keinen scraper haben.
        is_live = None
        client = None
        try:
            client = TikTokLiveClient(unique_id=f"@{username}")
            is_live = bool(await client.is_live())
        except Exception as e:
            log.info(f"TikTokLive-Status für @{username}: {e}")
            return {"is_live": None, "info": None}
        finally:
            if client is not None:
                for closer in ("disconnect", "close"):
                    fn = getattr(client, closer, None)
                    if callable(fn):
                        try:
                            res = fn()
                            if asyncio.iscoroutine(res): await res
                            break
                        except Exception:
                            continue
        return {"is_live": is_live, "info": None}

    status, info = await get_live_status(username, session, force_fresh=force_fresh)
    if status == "live":
        return {"is_live": True, "info": info}
    if status == "offline":
        return {"is_live": False, "info": None}
    return {"is_live": None, "info": None}      # unknown

