# F71: Backoff-Watch — zeigt Trackings die aktuell in B45 stream-pause
# Backoff sind. Operator sieht WER warum nicht aufgenommen wird.
@dashboard_app.route("/api/backoff-watch")
def api_backoff_watch():
    """Liste aller Trackings im aktiven B45-Backoff mit Restzeit + Streak."""
    now = _time_mod.monotonic()
    watching = []
    # Build username lookup für Trackings die backed off sind
    if _STREAM_DEAD_BACKOFF_UNTIL:
        tids = list(_STREAM_DEAD_BACKOFF_UNTIL.keys())
        with db_conn() as conn:
            # Portabel: einzelne SELECTs (n ist klein, max 10-20)
            for tid in tids:
                until = _STREAM_DEAD_BACKOFF_UNTIL.get(tid, 0)
                remaining = int(max(0, until - now))
                if remaining <= 0:
                    continue
                streak = _STREAM_DEAD_STREAK.get(tid, 0)
                row = conn.execute(
                    "SELECT username, group_id, COALESCE(notes, '') AS notes "
                    "FROM trackings WHERE id=?", (tid,)).fetchone()
                if row:
                    watching.append({
                        "tracking_id": tid,
                        "username": row["username"],
                        "group_id": row["group_id"],
                        "notes": row["notes"] or "",
                        "streak": streak,
                        "remaining_secs": remaining,
                    })
    # Sort by remaining-time ascending (whose backoff ends soonest first)
    watching.sort(key=lambda x: x["remaining_secs"])
    # Plus Anzahl Trackings im "early-disconnect"-Retry-Mode
    early_retries = []
    if _EARLY_DISCONNECT_RETRY:
        tids = list(_EARLY_DISCONNECT_RETRY.keys())
        with db_conn() as conn:
            for tid in tids:
                count = _EARLY_DISCONNECT_RETRY.get(tid, 0)
                if count <= 0:
                    continue
                row = conn.execute(
                    "SELECT username FROM trackings WHERE id=?", (tid,)).fetchone()
                if row:
                    early_retries.append({
                        "tracking_id": tid,
                        "username": row["username"],
                        "retry_count": count,
                    })
    return jsonify({
        "stream_dead_backoff": watching,
        "early_disconnect_retry": early_retries,
        "threshold": _STREAM_DEAD_THRESHOLD,
    })


# F72: 7-Tage Recording-Success-Trend
@dashboard_app.route("/api/trend-7d")
def api_trend_7d():
    """Pro Tag der letzten 7 Tage: total, ok, success-rate. Für Sparkline."""
    days = []
    cutoff = datetime.now(timezone.utc) - timedelta(days=7)
    with db_conn() as conn:
        # Portabel über SQLite und MariaDB: pro Tag SUBSTR(started_at, 1, 10)
        rows = conn.execute(
            "SELECT SUBSTR(started_at, 1, 10) AS day, "
            "  COUNT(*) AS total, "
            "  SUM(CASE WHEN outcome IN ('ok', 'stall_killed_partial') "
            "    THEN 1 ELSE 0 END) AS ok_count "
            "FROM recording_attempts "
            "WHERE started_at >= ? "
            "GROUP BY SUBSTR(started_at, 1, 10) "
            "ORDER BY day ASC",
            (cutoff.isoformat(),)).fetchall()
    by_day = {r["day"]: (r["total"] or 0, r["ok_count"] or 0) for r in rows}
    # Ensure 7 days even if some have no data (so the bar chart has consistent layout)
    for i in range(7):
        d = (datetime.now(timezone.utc) - timedelta(days=6 - i)).strftime("%Y-%m-%d")
        total, ok = by_day.get(d, (0, 0))
        days.append({
            "day": d,
            "weekday": (datetime.now(timezone.utc) - timedelta(days=6 - i)).strftime("%a"),
            "total": total,
            "ok": ok,
            "rate": int(100.0 * ok / total) if total else None,
        })
    return jsonify({"days": days})


# ============================================================================
# F74: Brain-Visualization Backend  (erweitert: Historie, kognitive Last, Stream)
# ============================================================================
# Liefert den Zustand aller Bot-Subsysteme für die Brain-Viz im Dashboard.
# Jeder "Knoten" hat einen Status (idle/active/working/error) + Activity 0-100.
# ERWEITERT: pro Knoten eine Activity-Historie (Sparklines), abgeleitete
# kognitive Gesamt-Last, Anomalie-Flags und ein neuronaler Aktivitäts-Stream.
_BRAIN_HISTORY = {}            # node_key -> list[int]  (ring, letzte N activity-Werte)
_BRAIN_HISTORY_MAX = 40
_BRAIN_STREAM = []             # list[{ts, node, kind, text}]  (ring)
_BRAIN_STREAM_MAX = 50
_BRAIN_LOCK = _threading_for_db.Lock()
_BRAIN_LAST_STATUS = {}        # node_key -> letzter status (für Übergangs-Events)

def _brain_record(nodes: dict):
    """Schreibt aktuelle Activity-Werte in die Historie + erzeugt Stream-Events
       bei Status-Übergängen. Thread-safe, bounded."""
    nowiso = datetime.now(timezone.utc).isoformat()
    with _BRAIN_LOCK:
        for key, n in nodes.items():
            hist = _BRAIN_HISTORY.setdefault(key, [])
            hist.append(int(n.get("activity", 0)))
            if len(hist) > _BRAIN_HISTORY_MAX:
                del hist[:-_BRAIN_HISTORY_MAX]
            prev = _BRAIN_LAST_STATUS.get(key)
            cur = n.get("status")
            if prev is not None and prev != cur:
                # Status-Übergang → Stream-Event
                kind = "error" if cur == "error" else ("up" if cur in ("active", "working") else "down")
                _BRAIN_STREAM.append({
                    "ts": nowiso, "node": n.get("label", key),
                    "kind": kind, "text": f"{n.get('label', key)}: {prev} → {cur}",
                })
                if len(_BRAIN_STREAM) > _BRAIN_STREAM_MAX:
                    del _BRAIN_STREAM[:-_BRAIN_STREAM_MAX]
            _BRAIN_LAST_STATUS[key] = cur

def _brain_history_for(key):
    with _BRAIN_LOCK:
        return list(_BRAIN_HISTORY.get(key, []))

def _brain_stream_recent(limit=20):
    with _BRAIN_LOCK:
        return list(reversed(_BRAIN_STREAM[-limit:]))

def _brain_growth_snapshot():
    """V37-BRAINVIZ: EIN Wachstums-Datenpunkt (Wissen/Vektoren/Nutzer). Wird
    stuendlich vom Scheduler gerufen. Fehlertolerant — Brain evtl. noch nicht da."""
    try:
        from brain import get_brain
        b = get_brain()
        ks = b.knowledge.stats() if hasattr(b, "knowledge") else {}
        ss = b.semantic.stats() if hasattr(b, "semantic") else {}
        triples = int(ks.get("triples", 0))
        vectors = int(ss.get("vectors", 0))
        users = int(ss.get("users", 0))
        sessions = 0
        try:
            with db_conn() as conn:
                r = conn.execute("SELECT COUNT(DISTINCT session_id) AS c FROM chat_log").fetchone()
                sessions = int(r["c"]) if r and r["c"] else 0
        except Exception:
            pass
        with db_conn() as conn:
            conn.execute(
                "INSERT INTO brain_growth (ts, triples, vectors, users, sessions) "
                "VALUES (?,?,?,?,?)",
                (datetime.now(timezone.utc).isoformat(), triples, vectors, users, sessions))
            conn.commit()
        return True
    except Exception as e:
        log.debug("brain growth snapshot: %s", e)
        return False


