@dashboard_app.route("/api/brain/alarms")
def api_brain_alarms():
    """B158: Verlauf der Sentinel-Befunde (agent_finding-Events) fuer die Alarm-Zeitleiste."""
    lvl = (request.args.get("level") or "").strip()
    try:
        limit = _arg_int("limit", 120, 10, 300)
    except ValueError:
        limit = 120
    out = []
    try:
        from brain import get_brain
        for e in get_brain().memory.events(kind="agent_finding", limit=limit):
            d = e.get("data") or {}
            lv = d.get("level", "info")
            if lvl and lv != lvl:
                continue
            out.append({"ts": e.get("ts"), "agent": e.get("key", ""),
                        "level": lv, "text": str(d.get("text", ""))[:200]})
    except Exception as ex:
        return jsonify(ok=False, error=str(ex)[:120], alarms=[])
    return jsonify(ok=True, alarms=out, count=len(out))


@dashboard_app.route("/api/brain/growth")
def api_brain_growth():
    """V37-BRAINVIZ: Wachstumskurve — echte Zeitreihe, wie das Brain lernt.
    ?days=30 begrenzt. Liefert Serien für Wissen/Vektoren/Nutzer."""
    try:
        days = _arg_int("days", 30, 1, 365)
    except ValueError:
        days = 30
    out = {"ok": True, "points": [], "current": {}}
    try:
        with db_conn() as conn:
            cur = conn.cursor()
            try:
                cur.execute(
                    "SELECT ts, triples, vectors, users, sessions FROM brain_growth "
                    "WHERE ts >= datetime('now', ?) ORDER BY ts", ("-%d days" % days,))
            except Exception:
                cur.execute(
                    "SELECT ts, triples, vectors, users, sessions FROM brain_growth "
                    "WHERE ts >= (NOW() - INTERVAL %d DAY) ORDER BY ts" % days)
            for r in cur.fetchall():
                out["points"].append({
                    "ts": r["ts"], "triples": r["triples"], "vectors": r["vectors"],
                    "users": r["users"], "sessions": r["sessions"]})
        # aktueller Live-Stand (auch wenn noch kein Snapshot existiert)
        try:
            from brain import get_brain
            b = get_brain()
            out["current"] = {
                "triples": b.knowledge.stats().get("triples", 0),
                "vectors": b.semantic.stats().get("vectors", 0),
                "users": b.semantic.stats().get("users", 0),
                "predicates": b.knowledge.stats().get("predicates", {})}
        except Exception:
            pass
        return jsonify(out)
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 500


@dashboard_app.route("/api/brain")
def api_brain():
    """Real-time state aller Subsysteme + aktive Prozessliste + Historie."""
    now = _time_mod.monotonic()

    nodes = {}

    # CORE: immer aktiv (wir antworten ja)
    nodes["core"] = {"status": "active", "activity": 50, "label": "BOT CORE"}

    # WORKER: aktive Live-Checks. Wenn _NEXT_CHECK_AT viele Trackings hat → aktiv
    try:
        # _NEXT_CHECK_AT ist ein Modul-Level-Global, immer vorhanden — der
        # frühere "X" in globals()-Check war Dead Code (Hinweis aus Header).
        pending = len(_NEXT_CHECK_AT)
        nodes["worker"] = {
            "status": "active" if pending > 0 else "idle",
            "activity": min(100, pending * 5),
            "label": "WORKER",
            "detail": f"{pending} trackings",
        }
    except Exception:
        nodes["worker"] = {"status": "idle", "activity": 0, "label": "WORKER"}

    # RECORDER: aktive Recording-Prozesse
    try:
        with db_conn() as conn:
            row = conn.execute(
                "SELECT COUNT(*) AS c FROM trackings WHERE recording = 1").fetchone()
        active_recs = row["c"] or 0
        if active_recs > 0:
            status = "working"
            activity = min(100, 30 + active_recs * 20)
        else:
            status = "idle"
            activity = 0
        nodes["recorder"] = {
            "status": status, "activity": activity, "label": "RECORDER",
            "detail": f"{active_recs} active",
        }
    except Exception:
        nodes["recorder"] = {"status": "idle", "activity": 0, "label": "RECORDER"}

    # TIKTOK API: ableitbar aus letzten Worker-Cycles + backoff-state
    try:
        # BUG-FIX: list()-Snapshot — der Async-Worker kann _STREAM_DEAD_BACKOFF_UNTIL
        # parallel mutieren ('dictionary changed size during iteration').
        in_backoff = len([t for t, until in list(_STREAM_DEAD_BACKOFF_UNTIL.items())
                          if until > now])
        if in_backoff > 0:
            nodes["tiktok"] = {
                "status": "error" if in_backoff > 5 else "active",
                "activity": 40, "label": "TIKTOK",
                "detail": f"{in_backoff} in backoff",
            }
        else:
            nodes["tiktok"] = {"status": "active", "activity": 30, "label": "TIKTOK"}
    except Exception:
        nodes["tiktok"] = {"status": "idle", "activity": 0, "label": "TIKTOK"}

    # DATABASE: praktisch immer aktiv (wir lesen ja gerade)
    nodes["database"] = {"status": "active", "activity": 20, "label": "DATABASE"}

    # TELEGRAM: ableitbar aus letzter Aktivität (count messages in last 5min)
    try:
        cutoff = (datetime.now(timezone.utc) - timedelta(minutes=5)).isoformat()
        with db_conn() as conn:
            row = conn.execute(
                "SELECT COUNT(*) AS c FROM ai_log WHERE created_at >= ?",
                (cutoff,)).fetchone()
        recent = row["c"] or 0
        nodes["telegram"] = {
            "status": "active" if recent > 0 else "idle",
            "activity": min(100, recent * 10),
            "label": "TELEGRAM",
            "detail": f"{recent} msgs/5min",
        }
    except Exception:
        nodes["telegram"] = {"status": "idle", "activity": 0, "label": "TELEGRAM"}

    # AI/OLLAMA: aus letzter Rate
    try:
        with _AI_DASHBOARD_LOCK:
            ai_count = len(_AI_DASHBOARD_RATE)
        nodes["ai"] = {
            "status": "working" if ai_count > 0 else "idle",
            "activity": min(100, ai_count * 15),
            "label": "AI",
            "detail": f"{ai_count} calls/min",
        }
    except Exception:
        nodes["ai"] = {"status": "idle", "activity": 0, "label": "AI"}

    # ARCHIVE: storage stats
    try:
        with db_conn() as conn:
            row = conn.execute(
                "SELECT COUNT(*) AS c FROM recording_attempts "
                "WHERE outcome IN ('ok','stall_killed_partial')").fetchone()
        rec_count = row["c"] or 0
        nodes["archive"] = {
            "status": "active" if rec_count > 0 else "idle",
            "activity": 25,
            "label": "ARCHIVE",
            "detail": f"{rec_count} files",
        }
    except Exception:
        nodes["archive"] = {"status": "idle", "activity": 0, "label": "ARCHIVE"}

    # Active processes feed (was läuft GERADE)
    processes = []
    try:
        # B2-Fix: ALLES innerhalb des with db_conn()-Blocks halten. Vorher wurde
        # `conn.execute(...)` auf Z. 8433 außerhalb des with-Blocks aufgerufen.
        # SQLite ließ das durch (Connection wird nicht geschlossen beim exit),
        # MariaDB nicht: __exit__ → close() → Conn zurück in den Pool → der
        # nächste Aufruf liest aus einer fremden Connection oder crashed.
        with db_conn() as conn:
            recs = conn.execute(
                "SELECT username, output_file, pid FROM trackings WHERE recording = 1 LIMIT 8"
            ).fetchall()
            for r in recs:
                processes.append({
                    "type": "recording",
                    "label": f"Recording @{r['username']}",
                    "detail": os.path.basename(r['output_file'] or '') or '—',
                    "pid": r['pid'] or 0,
                })
            in_backoff = list(_STREAM_DEAD_BACKOFF_UNTIL.items())[:5]
            for tid, until in in_backoff:
                remaining = max(0, int(until - now))
                row = conn.execute(
                    "SELECT username FROM trackings WHERE id = ?", (tid,)).fetchone()
                if row and remaining > 0:
                    processes.append({
                        "type": "backoff",
                        "label": f"Backoff @{row['username']}",
                        "detail": f"{remaining}s remaining",
                        "pid": 0,
                    })
    except Exception:
        pass

    # PROXY: bei festem RECORD_PROXY trägt der feste Proxy 100% des TikTok-
    # Verkehrs — der rotierende Pool schläft dann (healthy=0, sähe „idle" aus).
    # Gesundheit daher aus der Fetch-Erfolgsrate (Status-Counter), sonst Pool.
    try:
        if RECORD_PROXY:
            dist = get_tiktok_status_distribution()
            total = dist.get("total", 0) or 0
            by = {d["code"]: d for d in dist.get("by_code", [])}
            ok = 100.0 * by.get(200, {}).get("count", 0) / total if total else None
            if total < 15 or ok is None:
                nodes["proxy"] = {"status": "active", "activity": 40,
                                  "label": "PROXY", "detail": "fester Proxy · aufwärmend"}
            else:
                st = "active" if ok >= 60 else ("working" if ok >= 25 else "error")
                nodes["proxy"] = {"status": st, "activity": max(6, min(100, int(ok))),
                                  "label": "PROXY",
                                  "detail": f"fester Proxy · {ok:.0f}% 200 ({total} Fetches)"}
        else:
            pr = PROXY_ROUTER.stats()
            healthy = pr.get("healthy", 0)
            nodes["proxy"] = {
                "status": "active" if healthy > 0 else ("error" if pr.get("total", 0) > 0 else "idle"),
                "activity": min(100, healthy * 8),
                "label": "PROXY",
                "detail": f"{healthy}/{pr.get('total',0)} healthy · {pr.get('strategy','')}",
            }
    except Exception:
        nodes["proxy"] = {"status": "idle", "activity": 0, "label": "PROXY"}

    # Historie + Stream aktualisieren (vor dem Anreichern lesen)
    _brain_record(nodes)

    # Pro-Knoten Historie (Sparkline) + Anomalie-Flag anhängen
    for key, n in nodes.items():
        hist = _brain_history_for(key)
        n["history"] = hist
        # Anomalie: aktueller Wert weicht stark vom jüngsten Mittel ab, oder error
        anomaly = (n.get("status") == "error")
        if len(hist) >= 6:
            recent = hist[-6:-1] or [0]
            avg = sum(recent) / len(recent)
            if avg > 0 and n.get("activity", 0) > avg * 2.2:
                anomaly = True
        n["anomaly"] = anomaly

    # Kognitive Gesamt-Last (gewichteter Mittelwert der Activity) + Brain-State
    acts = [n.get("activity", 0) for n in nodes.values()]
    cognitive_load = round(sum(acts) / len(acts)) if acts else 0
    error_nodes = [n.get("label") for n in nodes.values() if n.get("status") == "error"]
    working_nodes = sum(1 for n in nodes.values() if n.get("status") == "working")
    if error_nodes:
        brain_state = "STRESSED"
    elif cognitive_load > 60 or working_nodes >= 2:
        brain_state = "FOCUSED"
    elif cognitive_load > 20:
        brain_state = "ACTIVE"
    else:
        brain_state = "IDLE"

    return jsonify({
        "nodes": nodes,
        "processes": processes,
        "cognitive_load": cognitive_load,
        "brain_state": brain_state,
        "error_nodes": error_nodes,
        "stream": _brain_stream_recent(20),
        "timestamp": datetime.now(timezone.utc).isoformat(),
    })


# ============================================================================
# F75: AI Diagnose-Assistant (sichere Alternative zu Self-Modifying-Code)
# ============================================================================
# Sammelt Logs + Stats + recent Errors und befragt das LLM zur Diagnose.
# WICHTIG: Nur Vorschläge als Text. KEIN automatisches Code-Patching.
# Operator entscheidet ob/was angewendet wird.


# ============================================================================
# F76: Duplicate File Checker für Manual Archive
# ============================================================================
# Scannt MANUAL_ARCHIVE_DIR (oder ARCHIVE_DIR) nach doppelten Dateien.
# 2-stufiger Algorithmus für Performance:
#   1) Group by file-size (sehr schnell, eliminiert die meisten Singletons)
#   2) Für same-size-Gruppen: MD5-Hash (volltest <100MB, header-hash größer)
# Liefert Duplikat-Gruppen sortiert nach "verschwendetem Platz".

_MANUAL_ARCHIVE_DIR = os.getenv("MANUAL_ARCHIVE_DIR", "").strip()







# ============================================================================
# F77: Free Proxy Pool — fetch + validate + use public free proxy lists
# ============================================================================
# Quellen für free proxies (rotieren zwischen denen, manche down manchmal):
#   - proxyscrape.com API
#   - github.com/jetkai/proxy-list (raw txt)
#   - github.com/TheSpeedX/PROXY-List (raw txt)
#
# WICHTIG: Free proxies sind NOTORISCH unzuverlässig + können MITM machen.
# NICHT für sensitive Daten verwenden. Wir testen jeden Proxy bevor wir ihn
# in den Pool aufnehmen + entfernen tote Proxies automatisch.

_PROXY_POOL = []   # list of dicts: {url, source, last_check, latency_ms, ok_count, fail_count}
_PROXY_POOL_LOCK = _threading_for_db.Lock()
_PROXY_LAST_REFRESH = 0
_PROXY_REFRESH_INTERVAL = _env_int("PROXY_REFRESH_INTERVAL_SECS", 1800)   # 30 min
# #1: Periodischer Auto-Refresh des Free-Proxy-Pools, den ALLES (Resolve + Pull + Restream
# + Live-React) via _pick_pull_proxy() nutzt. Proxys werden jetzt GEGEN TIKTOK validiert
# (nur erreichbare landen im Pool) + bei Block sofort rotiert. DEFAULT "auto": nur wenn kein
# RECORD_PROXY/PROXY_LIST gesetzt ist (dann ist der Pool die Quelle). "on"=immer, "off"=nie.
PROXY_POOL_AUTO = os.getenv("PROXY_POOL_AUTO", "auto").strip().lower()
_PROXY_MAX_POOL_SIZE = _env_int("PROXY_MAX_POOL_SIZE", 20)
# Validierung GEGEN TIKTOK statt generisch google: ein Proxy, der google schafft, kann
# bei TikTok trotzdem 407 (Auth) / 403 (IP geblockt) liefern. Nur wer TikTok mit 2xx/3xx
# beantwortet, kommt in den Pool. Realistischer Browser-UA, sonst antwortet TikTok zickig.
_PROXY_TEST_URL = os.getenv("PROXY_TEST_URL", "https://www.tiktok.com/")
_PROXY_TEST_TIMEOUT = _env_int("PROXY_TEST_TIMEOUT_SECS", 6)
_PROXY_TEST_UA = os.getenv("PROXY_TEST_UA",
    "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
    "(KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36")

_PROXY_SOURCES = [
    {
        "name": "proxyscrape-http",
        "url": "https://api.proxyscrape.com/v2/?request=getproxies&protocol=http&timeout=5000&country=all",
        "format": "lines",   # one ip:port per line
    },
    {
        "name": "TheSpeedX-http",
        "url": "https://raw.githubusercontent.com/TheSpeedX/PROXY-List/master/http.txt",
        "format": "lines",
    },
]

def _fetch_proxy_list(source):
    """Holt die Proxy-Liste von einer Source. Returns list of 'ip:port' strings."""
    import urllib.request
    try:
        req = urllib.request.Request(source["url"], headers={"User-Agent": "TKT-OPS/1.0"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            content = resp.read().decode("utf-8", errors="ignore")
    except Exception as e:
        log.warning(f"proxy-source {source['name']} fetch failed: {e}")
        return []
    proxies = []
    for line in content.splitlines():
        line = line.strip()
        if not line or ":" not in line:
            continue
        # Validate ip:port format roughly
        if re.match(r"^\d{1,3}(\.\d{1,3}){3}:\d{1,5}$", line):
            proxies.append(line)
    return proxies


def _test_proxy(proxy):
    """Testet einen Proxy GEGEN TIKTOK (_PROXY_TEST_URL). Nur 2xx/3xx von TikTok über den
       Proxy = brauchbar. 407 (Proxy verlangt Auth), 403 (TikTok blockt die Proxy-IP) und
       Timeouts → unbrauchbar (fliegen raus). So landen NUR Proxys im Pool, über die TikTok
       tatsächlich erreichbar ist — das behebt die 407/Timeout-Welle. Returns (ok, latency)."""
    scheme = _proxy_scheme(proxy) if "://" in proxy else "http"
    host = proxy.split("://", 1)[-1]
    started = _time_mod.monotonic()
    ua = _PROXY_TEST_UA
    if scheme.startswith("socks"):
        # SOCKS braucht PySocks. Ohne → ehrlich (False, None) statt falsch-http-Test.
        if not _HAS_SOCKS:
            return False, None
        try:
            import requests as _rq
            pscheme = "socks5h" if scheme in ("socks5", "socks5h") else scheme
            proxies = {"http": f"{pscheme}://{host}", "https": f"{pscheme}://{host}"}
            resp = _rq.get(_PROXY_TEST_URL, proxies=proxies, timeout=_PROXY_TEST_TIMEOUT,
                           headers={"User-Agent": ua}, allow_redirects=True)
            if 200 <= resp.status_code < 400:
                return True, int((_time_mod.monotonic() - started) * 1000)
        except Exception:
            pass
        return False, None
    # HTTP(S)-Proxy via urllib (kein Extra-Dep). 3xx folgt urllib selbst; verbleibender
    # HTTPError (407/403/4xx/5xx) = schlecht.
    import urllib.request, urllib.error
    proxy_url = f"http://{host}"
    handler = urllib.request.ProxyHandler({"http": proxy_url, "https": proxy_url})
    opener = urllib.request.build_opener(handler)
    try:
        req = urllib.request.Request(_PROXY_TEST_URL, headers={"User-Agent": ua})
        with opener.open(req, timeout=_PROXY_TEST_TIMEOUT) as resp:
            if 200 <= getattr(resp, "status", 0) < 400:
                return True, int((_time_mod.monotonic() - started) * 1000)
    except urllib.error.HTTPError:
        return False, None     # 407 (Proxy-Auth) / 403 (IP geblockt) / sonstige → unbrauchbar
    except Exception:
        pass
    return False, None


# Pre-Flight: vor dem ECHTEN Pull denselben Proxy noch mal kurz gegen TikTok testen.
# Kurzer TTL-Cache, damit ein Burst von Aufnahme-Starts denselben Proxy nicht 10× testet.
_PROXY_PREFLIGHT_CACHE = {}     # url -> (monotonic_ts, ok_bool)
_PROXY_PREFLIGHT_LOCK = _threading_for_db.Lock()
_PROXY_PREFLIGHT_TTL = _env_int("PROXY_PREFLIGHT_TTL_SECS", 90)

def _quick_validate_proxy(proxy):
    """Testet EINEN Proxy gegen TikTok (über _test_proxy), mit TTL-Cache. Returns bool.
       Blockierend → Aufrufer ruft via asyncio.to_thread auf, um den Loop nicht zu blocken."""
    if not proxy:
        return False
    now = _time_mod.monotonic()
    with _PROXY_PREFLIGHT_LOCK:
        c = _PROXY_PREFLIGHT_CACHE.get(proxy)
        if c and (now - c[0]) < _PROXY_PREFLIGHT_TTL:
            return c[1]
    ok, _lat = _test_proxy(proxy)
    with _PROXY_PREFLIGHT_LOCK:
        _PROXY_PREFLIGHT_CACHE[proxy] = (now, ok)
        if len(_PROXY_PREFLIGHT_CACHE) > 256:        # klein halten (FIFO)
            _PROXY_PREFLIGHT_CACHE.pop(next(iter(_PROXY_PREFLIGHT_CACHE)), None)
    return ok


# F79: GeoIP-Cache für die Proxy-Globe-Visualisierung.
# Source: ip-api.com Batch-Endpoint (free, no API-Key, 45 req/min limit).
# B57 (Bug-Hunt): Cache hatte kein Limit → unbounded growth. Bei Pool-Refresh
# alle 30min × neue IPs jedesmal sind das ~10MB/Jahr. Jetzt: einfacher LRU-
# Cap auf 5000 Einträge. Drüber: ältester wird verworfen. Da Geo-Location
# pro IP stabil ist, ist ein FIFO-Eviction OK.
_PROXY_GEO_CACHE = {}    # ip -> {lat, lon, country, city, isp}
_PROXY_GEO_LOCK = _threading_for_db.Lock()
_PROXY_GEO_LAST_FETCH = 0   # monotonic ts der letzten ip-api Anfrage
_PROXY_GEO_CACHE_MAX = 5000   # B57: max entries before FIFO-eviction

def _proxy_geo_cache_put(ip, geo):
    """B57: Cache-write mit Größenlimit. Pythons dict behält insertion-order
       → wir können den ältesten Eintrag mit next(iter(...)) finden und poppen."""
    with _PROXY_GEO_LOCK:
        if ip in _PROXY_GEO_CACHE:
            # Move-to-end für LRU-Verhalten
            _PROXY_GEO_CACHE.pop(ip)
        _PROXY_GEO_CACHE[ip] = geo
        # Evict oldest wenn überm Limit
        while len(_PROXY_GEO_CACHE) > _PROXY_GEO_CACHE_MAX:
            oldest_ip = next(iter(_PROXY_GEO_CACHE))
            _PROXY_GEO_CACHE.pop(oldest_ip, None)

def _enrich_proxies_with_geo(proxies):
    """Fügt jedem Proxy-Dict {lat, lon, country, city, isp} hinzu.
       Cache hits = sofort, Cache misses = ein Batch-Call zu ip-api.com.
       Falls ip-api down: kein crash, fehlt halt das geo-Feld."""
    global _PROXY_GEO_LAST_FETCH
    import urllib.request, json as _json

    # Phase 1: cache hits direkt anwenden, misses sammeln
    unknown = []
    for p in proxies:
        ip = (p.get("url", "").split(":") or [""])[0]
        if not ip:
            continue
        with _PROXY_GEO_LOCK:
            cached = _PROXY_GEO_CACHE.get(ip)
        if cached:
            p.update(cached)
        else:
            unknown.append((p, ip))

    if not unknown:
        return proxies

    # Phase 2: rate-limit gegen ip-api.com (45 req/min — wir machen max 1 batch
    # alle 5s damit pool-refresh-storms uns nicht bannen)
    now = _time_mod.monotonic()
    if now - _PROXY_GEO_LAST_FETCH < 5:
        log.info(f"GeoIP rate-limit: skip enrichment ({len(unknown)} unknown remain)")
        return proxies

    # Phase 3: batch fetch (max 100 IPs pro request laut ip-api docs)
    batch_ips = [ip for _, ip in unknown[:100]]
    body = _json.dumps([{"query": ip,
                         "fields": "status,lat,lon,country,city,isp,query"}
                        for ip in batch_ips]).encode()
    try:
        req = urllib.request.Request(
            "http://ip-api.com/batch",
            data=body,
            headers={"Content-Type": "application/json",
                     "User-Agent": "TKT-OPS/1.0"})
        with urllib.request.urlopen(req, timeout=10) as resp:
            results = _json.loads(resp.read().decode("utf-8", errors="ignore"))
        _PROXY_GEO_LAST_FETCH = now
        # Index by IP (results are in request order but safer to map by query field)
        ip_to_geo = {}
        for r in results:
            if isinstance(r, dict) and r.get("status") == "success":
                ip_to_geo[r.get("query", "")] = {
                    "lat": r.get("lat"),
                    "lon": r.get("lon"),
                    "country": r.get("country", ""),
                    "city": r.get("city", ""),
                    "isp": (r.get("isp", "") or "")[:50],
                }
        # Apply + cache
        for proxy_dict, ip in unknown:
            geo = ip_to_geo.get(ip)
            if geo:
                proxy_dict.update(geo)
                _proxy_geo_cache_put(ip, geo)   # B57: bounded cache write
        log.info(f"GeoIP enriched {len(ip_to_geo)}/{len(batch_ips)} proxies")
    except Exception as e:
        log.warning(f"GeoIP batch fetch failed: {e}")
    return proxies


# B68: Anonymitäts-Klassifizierung für Pool-Proxies (cached, concurrent).
# Vorher wurde anonymity NUR beim manuellen /api/proxy/test gesetzt → im Pool-
# und Router-View blieb alles "unknown". Jetzt klassifiziert der Refresh-Zyklus
# (und ein Hintergrund-Trigger) die Anonymität automatisch.
_PROXY_ANON_CACHE = {}        # "ip:port" -> anon level
_PROXY_ANON_LOCK = _threading_for_db.Lock()
_PROXY_ANON_BG_RUNNING = [False]

def _classify_pool_anonymity(proxies, max_workers=10):
    """Setzt p['anonymity'] für jeden Pool-Proxy (in-place). Cache-Hits sofort,
       Misses via classify_proxy_anonymity (Netzwerk, daher concurrent). Spiegelt
       das Ergebnis auch in den PROXY_ROUTER. Best-effort: Fehler → 'unknown'."""
    from concurrent.futures import ThreadPoolExecutor, as_completed
    todo = []
    for p in proxies:
        url = p.get("url", "")
        if not url:
            continue
        with _PROXY_ANON_LOCK:
            cached = _PROXY_ANON_CACHE.get(url)
        if cached:
            p["anonymity"] = cached
        elif not p.get("anonymity") or p.get("anonymity") == "unknown":
            todo.append(p)
    if not todo:
        return proxies

    def _one(p):
        try:
            anon, _ = classify_proxy_anonymity(p["url"])
        except Exception:
            anon = "unknown"
        return p, (anon or "unknown")

    try:
        with ThreadPoolExecutor(max_workers=max_workers) as ex:
            for fut in as_completed([ex.submit(_one, p) for p in todo]):
                try:
                    p, anon = fut.result()
                    p["anonymity"] = anon
                    if anon and anon != "unknown":
                        with _PROXY_ANON_LOCK:
                            _PROXY_ANON_CACHE[p["url"]] = anon
                        try:
                            PROXY_ROUTER.set_anonymity(p["url"], anon)
                        except Exception:
                            pass
                except Exception:
                    pass
    except Exception as e:
        log.debug(f"anonymity classify pool failed: {e}")
    return proxies


def _classify_pool_anonymity_bg():
    """Stößt die Anonymitäts-Klassifizierung im Hintergrund an (non-blocking,
       nur EIN Lauf gleichzeitig, nur wenn unbekannte Proxies existieren)."""
    if _PROXY_ANON_BG_RUNNING[0]:
        return
    with _PROXY_POOL_LOCK:
        pool_ref = list(_PROXY_POOL)
    if not any((not p.get("anonymity") or p.get("anonymity") == "unknown")
               for p in pool_ref):
        return
    _PROXY_ANON_BG_RUNNING[0] = True

    def _run():
        try:
            _classify_pool_anonymity(pool_ref)
        finally:
            _PROXY_ANON_BG_RUNNING[0] = False
    threading.Thread(target=_run, daemon=True, name="proxy-anon").start()


def _refresh_proxy_pool():
    """Holt frische Listen, testet Kandidaten GEGEN TIKTOK, ersetzt den Pool.
       Bewährte Pool-Proxys werden mit-getestet → bleiben drin solange sie TikTok noch
       schaffen; tote fliegen raus. So bleibt der Pool zwischen Refreshes stabil gefüllt."""
    global _PROXY_LAST_REFRESH
    log.info("proxy-pool refresh started")
    candidates = []
    seen_urls = set()
    # Bestehende Pool-Proxys zuerst (re-test) → Stabilität statt Komplett-Austausch.
    with _PROXY_POOL_LOCK:
        for p in list(_PROXY_POOL):
            u = p.get("url")
            if u and u not in seen_urls:
                seen_urls.add(u)
                candidates.append((u, p.get("source", "pool")))
    for source in _PROXY_SOURCES:
        proxies = _fetch_proxy_list(source)
        for p in proxies[:50]:    # max 50 pro Source
            if p not in seen_urls:
                seen_urls.add(p)
                candidates.append((p, source["name"]))
    log.info(f"proxy-pool: {len(candidates)} candidates (inkl. bestehende) — teste gegen TikTok")

    # Test concurrent via threads
    from concurrent.futures import ThreadPoolExecutor, as_completed
    working = []
    with ThreadPoolExecutor(max_workers=20) as ex:
        future_to_proxy = {ex.submit(_test_proxy, p): (p, src) for p, src in candidates}
        for fut in as_completed(future_to_proxy):
            p, src = future_to_proxy[fut]
            try:
                ok, latency = fut.result()
                if ok:
                    working.append({
                        "url": p,
                        "source": src,
                        "latency_ms": latency,
                        "last_check": int(_time_mod.monotonic()),
                        "ok_count": 1,
                        "fail_count": 0,
                    })
                if len(working) >= _PROXY_MAX_POOL_SIZE:
                    # genug — cancel rest
                    for f in future_to_proxy:
                        f.cancel()
                    break
            except Exception:
                pass
    # Sort by latency ascending
    working.sort(key=lambda x: x["latency_ms"])
    working = working[:_PROXY_MAX_POOL_SIZE]
    # B68: Pool-Einträge mit Land (GeoIP) UND Anonymität anreichern, damit das
    # Dashboard beides anzeigt — nicht erst nach manuellem Test pro Proxy.
    try:
        _enrich_proxies_with_geo(working)
    except Exception as e:
        log.debug(f"geo enrich on refresh failed: {e}")
    try:
        _classify_pool_anonymity(working)
    except Exception as e:
        log.debug(f"anonymity classify on refresh failed: {e}")
    with _PROXY_POOL_LOCK:
        _PROXY_POOL.clear()
        _PROXY_POOL.extend(working)
        _PROXY_LAST_REFRESH = _time_mod.monotonic()
    log.info(f"proxy-pool refresh done: {len(working)} working proxies")
    # Nach jedem Refresh: Router-Health-State mit dem neuen Pool synchronisieren
    try:
        PROXY_ROUTER.sync_from_pool()
    except Exception as e:
        log.debug(f"proxy router sync failed: {e}")


async def _proxy_pool_refresh_loop():
    """#1: Hält den Free-Proxy-Pool gefüllt, den der Resolver (webcast/HTML/yt-dlp via
       get_random_proxy()) nutzt. Ohne diesen Loop wird der Pool NUR on-demand (API-
       Button) befüllt → im Normalbetrieb leer → get_random_proxy() liefert None →
       Resolves gehen direkt von der (oft geblockten) Server-IP raus → 403. Gated:
       läuft nur, wenn der Pool tatsächlich die aktive Proxy-Quelle ist."""
    mode = PROXY_POOL_AUTO
    if mode == "off":
        return
    if mode == "auto" and (RECORD_PROXY or PROXY_LIST):
        log.info("Proxy-Pool-Auto: RECORD_PROXY/PROXY_LIST gesetzt → Pool-Refresh aus "
                 "(explizite Quelle hat Vorrang).")
        return
    loop = asyncio.get_event_loop()
    await asyncio.sleep(15)        # Boot abwarten, dann sofort erster Refresh
    interval = max(300, _PROXY_REFRESH_INTERVAL)
    while True:
        try:
            await loop.run_in_executor(None, _refresh_proxy_pool)
            with _PROXY_POOL_LOCK:
                n = len(_PROXY_POOL)
            log.info("Proxy-Pool-Auto: Refresh fertig (%d Proxys im Pool).", n)
        except asyncio.CancelledError:
            raise
        except Exception as e:
            # v4.1-W5: war log.warning. Ohne Refresh altert der Pool, und die
            # Aufnahmen laufen nach und nach auf tote Proxies.
            _loop_fehler("_proxy_pool_refresh_loop", e)
        await asyncio.sleep(interval)


async def _ensure_proxy_ready(max_wait_secs=None):
    """Startup-GATE: stellt sicher, dass eine Proxy-Quelle STEHT, BEVOR Detection/Recording/
       Restream/Live-React loslegen. Ohne das gingen die ersten Pulls direkt von der (oft
       geblockten) Datacenter-IP raus → 403, bis der Pool nach ~15-30s gefüllt ist.
       - RECORD_PROXY/PROXY_LIST gesetzt → sofort bereit (feste Quelle).
       - PROXY_POOL_AUTO=off → bewusst ohne Pool starten (direkt).
       - sonst: Pool initial füllen + warten bis ≥1 TikTok-validierter Proxy da ist
         (bis max_wait), dann freigeben. Hängt NIE ewig: nach Timeout Start trotzdem,
         der Hintergrund-Refresh füllt weiter."""
    if RECORD_PROXY or PROXY_LIST:
        log.info("Proxy-Gate: feste Proxy-Quelle gesetzt → sofort bereit.")
        return
    if PROXY_POOL_AUTO == "off":
        log.info("Proxy-Gate: Pool aus (PROXY_POOL_AUTO=off) → Start ohne Pool (direkt).")
        return
    if max_wait_secs is None:
        max_wait_secs = _env_int("PROXY_GATE_MAX_WAIT_SECS", 60)
    loop = asyncio.get_event_loop()
    deadline = _time_mod.monotonic() + max(10, max_wait_secs)
    attempt = 0
    log.info("Proxy-Gate: baue Proxy-Pool auf, BEVOR Aufnahmen/Restream/Live-React starten…")
    while _time_mod.monotonic() < deadline:
        attempt += 1
        try:
            await loop.run_in_executor(None, _refresh_proxy_pool)
        except Exception as e:
            log.warning("Proxy-Gate: Refresh-Versuch %d fehlgeschlagen: %s", attempt, e)
        with _PROXY_POOL_LOCK:
            n = len(_PROXY_POOL)
        if n > 0:
            log.info("Proxy-Gate: %d TikTok-validierte Proxys im Pool → Start frei "
                     "(nach Versuch %d).", n, attempt)
            return
        log.warning("Proxy-Gate: noch kein tauglicher Proxy (Versuch %d) — retry in 5s…", attempt)
        await asyncio.sleep(5)
    log.warning("Proxy-Gate: nach %ds kein validierter Proxy → Start TROTZDEM. Resolves/Pulls "
                "gehen ggf. direkt raus, bis der Hintergrund-Refresh Proxys findet. Für "
                "stabilen Dauerbetrieb einen echten RECORD_PROXY setzen.", max_wait_secs)


