def classify_proxy_anonymity(proxy_url: str, timeout=6):
    """Klassifiziert Anonymität: elite / anonymous / transparent.
       Nutzt einen Judge-Endpoint (httpbin/get) und prüft ob die echte IP
       oder Proxy-Header durchsickern. Returns (anon_level, detail_dict).
       Security: 'transparent' = Proxy leakt deine echte IP → meiden.
       BUG-FIX: SOCKS-bewusst — socks5:// via requests+PySocks (wenn da)."""
    import json as _json
    scheme = _proxy_scheme(_normalize_proxy_url(proxy_url))
    host = proxy_url.split("://", 1)[-1]
    data = None
    try:
        if scheme.startswith("socks"):
            if not _HAS_SOCKS:
                return "unknown", {"error": "socks proxy needs PySocks"}
            import requests as _rq
            pscheme = "socks5h" if scheme in ("socks5", "socks5h") else scheme
            proxies = {"http": f"{pscheme}://{host}", "https": f"{pscheme}://{host}"}
            resp = _rq.get(_PROXY_ANON_JUDGE, proxies=proxies, timeout=timeout,
                           headers={"User-Agent": "TKT-OPS/1.0"})
            data = resp.json()
        else:
            import urllib.request
            norm = "http://" + host
            handler = urllib.request.ProxyHandler({"http": norm, "https": norm})
            opener = urllib.request.build_opener(handler)
            req = urllib.request.Request(_PROXY_ANON_JUDGE,
                                         headers={"User-Agent": "TKT-OPS/1.0"})
            with opener.open(req, timeout=timeout) as resp:
                data = _json.loads(resp.read().decode("utf-8", "ignore"))
    except Exception as e:
        return "unknown", {"error": str(e)}
    headers = {k.lower(): v for k, v in (data.get("headers") or {}).items()}
    # Proxy-verräterische Header
    leaky = [h for h in ("via", "x-forwarded-for", "forwarded",
                         "x-real-ip", "proxy-connection", "x-proxy-id")
             if h in headers]
    if not leaky:
        level = "elite"        # kein Hinweis auf Proxy-Nutzung
    elif "x-forwarded-for" in headers or "x-real-ip" in headers or "forwarded" in headers:
        level = "transparent"  # echte IP könnte durchsickern
    else:
        level = "anonymous"    # Proxy erkennbar (via) aber IP versteckt
    return level, {"leaky_headers": leaky, "origin": data.get("origin")}


