# ═══ F82: Betriebs-Endpoints + Header-Härtung ═══
@dashboard_app.route("/api/health")
def api_health():
    """F82: Liveness/Readiness für Monitoring (UptimeRobot, curl-Cron, …).
       Prüft echte DB-Erreichbarkeit statt nur 'Prozess lebt'."""
    db_ok = True
    try:
        with db_conn() as conn:
            conn.execute("SELECT 1").fetchone()
    except Exception:
        db_ok = False
    body = {"ok": db_ok, "db": ("ok" if db_ok else "fail"),
            "uptime_secs": int(_time_mod.time() - _BOOT_TS),
            "backend": DB_BACKEND}
    return jsonify(body), (200 if db_ok else 503)


@dashboard_app.after_request
def _sec_headers(resp):
    """F82: defensive Standard-Header. Rein additiv — ändert kein Verhalten
       des Dashboards (kein CSP, das die Inline-Scripts brechen würde)."""
    resp.headers.setdefault("X-Content-Type-Options", "nosniff")
    resp.headers.setdefault("X-Frame-Options", "SAMEORIGIN")
    resp.headers.setdefault("Referrer-Policy", "no-referrer")
    # v37 Welle 1: Audit-Log — nur Schreib-Aktionen (POST/PUT/DELETE) protokollieren
    try:
        if request.method in ("POST", "PUT", "DELETE") and request.path.startswith("/api/") \
           and not request.path.startswith("/api/ops/audit"):
            # SEC-AUDIT (v4.0-W13): echte IP — vorher konnte ein Angreifer die
            # protokollierte Herkunft per X-Forwarded-For faelschen (Spurenverwischung).
            ip = _client_ip()
            meth, pth, stat = request.method, request.path, resp.status_code

            def _aud():
                try:
                    with db_conn() as conn:
                        conn.execute("INSERT INTO audit_log (method, path, ip, status, created_at) "
                                     "VALUES (?,?,?,?,?)",
                                     (meth, pth, ip, stat, datetime.now(timezone.utc).isoformat()))
                except Exception:
                    pass
            # v4.0-W105 (Tiefenbughunt): frueher _spawn(asyncio.to_thread(_aud)).
            # after_request laeuft im Flask-Thread, dort gibt es keinen laufenden
            # Loop — create_task() warf jedes Mal, das except darunter schluckte
            # es, und KEIN einziger Schreibzugriff wurde protokolliert. Nachweis
            # war ein leeres audit_log nach drei POST/DELETE.
            # Ein eigener Thread braucht gar keinen Loop und schreibt auch
            # waehrend des Bot-Starts — bei einem Sicherheitsprotokoll ist das
            # die richtige Abwaegung.
            threading.Thread(target=_aud, name="audit-write", daemon=True).start()
    except Exception as e:
        # Nie propagieren: ein kaputtes Audit darf keine Antwort zerstoeren.
        # Aber auch nicht schweigen — sonst faellt das Protokoll wieder
        # jahrelang unbemerkt aus.
        log.error("Audit-Log-Eintrag fehlgeschlagen: %s", e, exc_info=e)
    return resp


