@dashboard_app.route("/archive/<int:eid>/download")
def archive_download(eid):
    if not ARCHIVE_DIR:
        abort(404)
    row = get_archive_entry(eid)
    if not row: abort(404)
    fp = row["filepath"]
    if not fp:
        abort(410)
    real_archive = os.path.realpath(ARCHIVE_DIR)
    real_file    = os.path.realpath(fp)
    try:
        if os.path.commonpath([real_archive, real_file]) != real_archive:
            log.warning(f"archive_download path-traversal-Versuch: {fp}")
            abort(403)
    except ValueError:
        abort(403)
    if not os.path.exists(real_file):
        abort(410)
    return send_from_directory(
        os.path.dirname(real_file),
        os.path.basename(real_file),
        as_attachment=True,
        download_name=row["filename"])



