@dashboard_app.route("/download/<int:recording_id>")
def download(recording_id):
    rec = get_recording_by_id(recording_id)
    if not rec: abort(404)
    filepath = os.path.realpath(rec["filepath"])
    allowed  = os.path.realpath(RECORDINGS_DIR)
    try:
        common = os.path.commonpath([filepath, allowed])              # C7
    except ValueError:
        abort(403)
    if common != allowed: abort(403)
    if not os.path.isfile(filepath): abort(404)
    return send_from_directory(allowed, os.path.relpath(filepath, allowed),
                               as_attachment=True)

def run_flask():
    # F24-Hang-Fix: threaded=True — sonst blockiert eine slow sync Route
    # (Redis/Ollama-Probes) den ganzen Server. Multi-threaded reicht für
    # unseren Last (Dashboard mit handful Polling-Requests/30s).
    # WEB_HOST wird respektiert (inkl. 0.0.0.0 für Remote-Zugriff). Wenn ohne
    # DASHBOARD_TOKEN öffentlich gebunden wird, ist _auth_guard() ein No-Op →
    # NUR eine deutliche Warnung, KEIN Force auf localhost (Operator-Entscheid).
    # Hinweis: Der App-Token greift im Browser-UI ohnehin nicht, weil das
    # Frontend keinen Authorization-Header sendet → auf einer Public-Box ist
    # eine Firewall-Regel die saubere Absicherung:
    #   ufw allow from <DEINE-IP> to any port <PORT>   (+ sonst Port dichtmachen)
    if not DASHBOARD_TOKEN and WEB_HOST not in ("127.0.0.1", "localhost", "::1"):
        log.warning("=" * 70)
        log.warning("SICHERHEIT: Dashboard hört auf %s:%s OHNE Token — damit im "
                    "Netz erreichbar (Cookie-Zugriff, Recordings löschen, "
                    "Config-Restore, Log-Tail).", WEB_HOST, DASHBOARD_PORT)
        log.warning("→ Zwei Wege: (a) DASHBOARD_TOKEN=<langes Geheimnis> in die "
                    ".env — seit v4.0-W13 wird er WIRKLICH geprueft (Aufruf "
                    "einmalig mit ?token=..., danach Cookie); (b) Port per "
                    "Firewall auf deine IP beschraenken: "
                    "ufw allow from <DEINE-IP> to any port %s", DASHBOARD_PORT)
    if DASHBOARD_TOKEN:
        log.info("Dashboard-Token AKTIV: extern nur mit Token (?token=... setzt ein "
                 "Cookie). Frei bleiben: Loopback/SSH-Tunnel, OAuth-Rueckrufe, "
                 "/healthz, /api/public/* und die OBS-Quelle /overlay + "
                 "/api/overlay/state (nur GET). Prometheus braucht in der "
                 "scrape_config: authorization: {type: Bearer, credentials: <TOKEN>}")
        log.warning("=" * 70)
    # V37-TLS: Dashboard optional direkt über HTTPS. Fuer den Twitch-OAuth-Flow
    # braucht es eine erreichbare HTTPS-URL (Twitch lehnt http://IP ab). Wer
    # keinen Reverse-Proxy betreibt, gibt hier Zertifikat + Key an und erreicht
    # das Dashboard unter https://<domain>:<port>. Let's-Encrypt-Pfade z.B.:
    #   DASHBOARD_TLS_CERT=/etc/letsencrypt/live/trevlix.dev/fullchain.pem
    #   DASHBOARD_TLS_KEY=/etc/letsencrypt/live/trevlix.dev/privkey.pem
    _tls_cert = (os.getenv("DASHBOARD_TLS_CERT", "") or "").strip()
    _tls_key = (os.getenv("DASHBOARD_TLS_KEY", "") or "").strip()
    _ssl_ctx = None
    if _tls_cert and _tls_key:
        if os.path.exists(_tls_cert) and os.path.exists(_tls_key):
            _ssl_ctx = (_tls_cert, _tls_key)
            log.info("Dashboard-TLS aktiv: https://<host>:%s (Zertifikat: %s)",
                     DASHBOARD_PORT, os.path.basename(_tls_cert))
        else:
            log.warning("DASHBOARD_TLS_CERT/KEY gesetzt, aber Datei(en) fehlen — "
                        "Dashboard startet unverschluesselt (HTTP).")
    dashboard_app.run(host=WEB_HOST, port=DASHBOARD_PORT,
                      debug=False, use_reloader=False, threaded=True,
                      ssl_context=_ssl_ctx)

# =============================================================================
# X-Series: Flask→Async-Bridge + 30 neue API-Endpoints
# =============================================================================
_MAIN_LOOP = None          # gesetzt in run_bot()
_GLOBAL_SCRAPER = None      # gesetzt in run_bot()

# ─────────────────────────────────────────────────────────────────────────────
# v4.0-W83: LOOP-STALL-WATCHDOG — Selbstdiagnose eines eingefrorenen Event-Loops.
#
# Hintergrund: ein Fork-Deadlock (W76) hatte den Loop hart eingefroren; die
# Ursache ließ sich NUR mit einem externen py-spy-Dump finden. Dieser Watchdog
# macht denselben Dump automatisch: ein Heartbeat-Task schlägt alle paar Sekunden
# auf dem Loop; ein UNABHÄNGIGER Daemon-Thread (der bei eingefrorenem Loop noch
# lebt) erkennt einen stehenden Heartbeat und schreibt einen Voll-Stack-Dump
# ALLER Threads (faulthandler) ins Journal + eine Datei — die blockierende Zeile
# steht dann sofort im Log, ohne py-spy. Ein Alarm geht best-effort an Telegram.
# ─────────────────────────────────────────────────────────────────────────────
_LOOP_HEARTBEAT_TS = 0.0
_LOOP_STALL_DUMPED = False
# v4.0-W88: Observability rund um den Watchdog.
_LOOP_STALL_COUNT = 0          # #erkannte Loop-Stalls seit Boot (in /healthz & /api/brain/health)
_BRIDGE_TICK_ALERTED = False   # Bridge-Tick-Stillstand nur EINMAL alarmieren


def _prune_stall_dumps(keep: int = 10):
    """Phase-1-Zerlegung: Logik in nc.procdiag; Wrapper hält Name/Signatur."""
    return _nc_procdiag.prune_stall_dumps(LOG_DIR, keep)


def _zombie_child_count() -> int:
    """Phase-1-Zerlegung: Logik in nc.procdiag; Wrapper hält Name/Signatur."""
    return _nc_procdiag.zombie_child_count()


def _dump_all_threads(reason: str = "manuell"):
    """Phase-1-Zerlegung: Logik in nc.procdiag; Wrapper hält Name/Signatur."""
    return _nc_procdiag.dump_all_threads(LOG_DIR, reason)


def _install_faulthandler():
    """v4.0-W88: faulthandler scharf — harte Crashes (Segfault) hinterlassen jetzt
       einen Python-Traceback im Journal. Zusätzlich SIGUSR1 → on-demand
       Thread-Dump (`kill -USR1 <pid>`), ohne py-spy. Linux-only, best-effort."""
    try:
        import faulthandler
        faulthandler.enable()
        if hasattr(_signal_mod, "SIGUSR1"):
            def _usr1(_sig, _frm):
                _dump_all_threads("SIGUSR1")
            try:
                _signal_mod.signal(_signal_mod.SIGUSR1, _usr1)
                log.info("faulthandler aktiv · SIGUSR1 → Thread-Dump (kill -USR1 %d)", os.getpid())
            except (ValueError, OSError):
                pass  # Signal nur im Haupt-Thread setzbar
    except Exception as _e:
        log.debug("faulthandler-Setup: %s", _e)



async def _loop_heartbeat():
    """Schlägt alle 2s den Loop-Heartbeat. Bleibt der Wert stehen, ist der
       Event-Loop synchron blockiert (Deadlock/blockierender Call)."""
    global _LOOP_HEARTBEAT_TS
    while True:
        _LOOP_HEARTBEAT_TS = _time_mod.monotonic()
        try:
            await asyncio.sleep(2.0)
        except asyncio.CancelledError:
            return


def _loop_watchdog_thread():
    """Eigener Daemon-Thread (NICHT am Loop): erkennt einen eingefrorenen
       Event-Loop und dumpt den Voll-Stack aller Threads. Läuft weiter, während
       der Loop hängt — genau dann, wenn man den Dump braucht."""
    import faulthandler
    global _LOOP_STALL_DUMPED, _LOOP_STALL_COUNT, _BRIDGE_TICK_ALERTED
    stall_s = _nc_envnum.env_float("LOOP_WATCHDOG_STALL_S", 30.0)
    check_s = _nc_envnum.env_float("LOOP_WATCHDOG_CHECK_S", 5.0)
    tick_stall_s = _nc_envnum.env_float("BRIDGE_TICK_STALL_S", 180.0)
    while True:
        _time_mod.sleep(check_s)
        # v4.0-W88: Bridge-Tick-Stillstand erkennen — der Brain war schon mal
        # still unten. War der Tick mal frisch und ist jetzt alt → EINMAL alarmieren.
        try:
            from brain import get_brain as _gb
            _last = getattr(_gb(), "last_tick_ts", 0) or 0
            if _last > 0:
                _tick_age = _time_mod.time() - _last
                if _tick_age > tick_stall_s and not _BRIDGE_TICK_ALERTED:
                    _BRIDGE_TICK_ALERTED = True
                    log.error("BRIDGE-TICK steht seit %.0fs — Agenten/Regeln laufen nicht.", _tick_age)
                    try:
                        _brain_notify("🟠 Brain-Tick steht seit %.0fs — Agenten/Regeln "
                                      "laufen nicht mehr. Dashboard → Brain-Zustand prüfen." % _tick_age)
                    except Exception:
                        pass
                elif _tick_age <= tick_stall_s:
                    _BRIDGE_TICK_ALERTED = False    # erholt → wieder scharf
        except Exception:
            pass

        hb = _LOOP_HEARTBEAT_TS
        if hb <= 0:
            continue                       # Heartbeat läuft noch nicht
        age = _time_mod.monotonic() - hb
        if age <= stall_s:
            _LOOP_STALL_DUMPED = False      # erholt → für die nächste Episode scharf
            continue
        if _LOOP_STALL_DUMPED:
            continue                        # eine Episode nur EINMAL dumpen (kein Spam)
        _LOOP_STALL_DUMPED = True
        _LOOP_STALL_COUNT += 1              # v4.0-W88: Zähler für /healthz & /api/brain/health
        path = None
        try:
            os.makedirs(LOG_DIR, exist_ok=True)
            path = os.path.join(LOG_DIR, "loop_stall_%d.txt" % int(_time_mod.time()))
            with open(path, "w") as fh:
                fh.write("LOOP-STALL: Event-Loop seit %.0fs eingefroren\n"
                         "(Zeitpunkt %s)\n\n"
                         % (age, datetime.now().isoformat(timespec="seconds")))
                faulthandler.dump_traceback(file=fh, all_threads=True)
        except Exception as _fe:
            log.error("LOOP-STALL: Dump-Datei fehlgeschlagen: %s", _fe)
        _prune_stall_dumps(keep=10)          # v4.0-W88: alte Dumps nicht anhäufen
        log.error("LOOP-STALL erkannt: Event-Loop seit %.0fs eingefroren%s. "
                  "Voll-Stack-Dump aller Threads folgt (kein py-spy nötig).",
                  age, (" — Datei: " + path) if path else "")
        try:
            faulthandler.dump_traceback(all_threads=True)   # zusätzlich ins Journal (stderr)
        except Exception:
            pass
        # Alarm best-effort — bei HARTEM Stall erreicht der Loop-Pfad Telegram
        # evtl. nicht; die Journal-Datei ist die verlässliche Quelle.
        try:
            _brain_notify("🔴 LOOP-STALL: Event-Loop seit %.0fs eingefroren. "
                          "Voll-Stack-Dump im Log%s. Bot vermutlich hängend — "
                          "Neustart prüfen." % (age, (" (" + os.path.basename(path) + ")") if path else ""))
        except Exception:
            pass


def _start_loop_watchdog():
    """v4.0-W83: aus run_bot() nach dem Setzen von _MAIN_LOOP aufrufen.
       Startet Heartbeat-Task + Monitor-Thread (per LOOP_WATCHDOG_ENABLED=0 aus)."""
    global _LOOP_HEARTBEAT_TS
    if _nc_envnum.env_int("LOOP_WATCHDOG_ENABLED", 1) == 0:
        log.info("Loop-Stall-Watchdog per LOOP_WATCHDOG_ENABLED=0 deaktiviert")
        return
    _LOOP_HEARTBEAT_TS = _time_mod.monotonic()
    _install_faulthandler()          # v4.0-W88: Crash-Tracebacks + SIGUSR1-Dump
    try:
        asyncio.ensure_future(_loop_heartbeat())
    except Exception as _e:
        log.warning("Loop-Heartbeat konnte nicht starten: %s", _e)
        return
    threading.Thread(target=_loop_watchdog_thread, name="loop-watchdog",
                     daemon=True).start()
    log.info("Loop-Stall-Watchdog aktiv (Stall-Schwelle %.0fs)",
             _nc_envnum.env_float("LOOP_WATCHDOG_STALL_S", 30.0))


def _run_async_from_flask(coro, timeout: float = 70.0):
    """Schedule a coroutine on the bot's main event loop and block until done.
       Wird aus dem Flask-Thread aufgerufen. Wenn der Loop noch nicht läuft
       (Bot startet gerade), wird ein RuntimeError('event loop not ready')
       geworfen. B86: Routes sollen das als transientes 503 behandeln, nicht als
       500 — nutze dafür _loop_not_ready(e) im except-Block (s.u.)."""
    if _MAIN_LOOP is None or not _MAIN_LOOP.is_running():
        try:
            coro.close()   # kein "never awaited"-Warning + Leak
        except Exception:
            pass
        raise RuntimeError("event loop not ready")
    fut = asyncio.run_coroutine_threadsafe(coro, _MAIN_LOOP)
    return fut.result(timeout=timeout)



def _scraper_session():
    """Best-effort aiohttp-Session vom globalen Scraper. None wenn nicht da."""
    try:
        return _GLOBAL_SCRAPER.session if _GLOBAL_SCRAPER else None
    except Exception:
        return None




