# ---------- X27: Bulk Profile-Lookup ----------
@dashboard_app.route("/api/profile/lookup-bulk", methods=["POST"])
def api_profile_lookup_bulk():
    data = request.get_json(silent=True) or {}
    usernames = data.get("usernames") or []
    if not isinstance(usernames, list) or not usernames:
        return jsonify(ok=False, error="usernames[] required"), 400
    usernames = [clean_username(u) for u in usernames[:20]]
    usernames = [u for u in usernames if u]
    async def _lookup_all():
        results = {}
        session = _scraper_session()
        own = False
        if session is None:
            session = aiohttp.ClientSession(); own = True
        try:
            for u in usernames:
                try:
                    info = await _get_live_info(u, session=session)
                    detail = info.get("info") or {}
                    results[u] = {
                        "is_live": info.get("is_live"),
                        "title": detail.get("title"),
                        "viewers": detail.get("viewer_count") or detail.get("viewers"),
                    }
                except Exception as e:
                    results[u] = {"error": str(e)}
        finally:
            if own:
                try: await session.close()
                except Exception: pass
        return results
    try:
        results = _run_async_from_flask(_lookup_all(), timeout=60)
    except Exception as e:
        return jsonify(ok=False, error=f"lookup failed: {e}"), 503
    return jsonify(ok=True, results=results)

