def _cfg_set(key, value):
    # v4.0-W111: nach nc/cfgstore.py geloest.
    return _nc_cfgstore.set_(key, value)




def _post_json_threaded(url, body, wid):
    """Feuert einen JSON-POST in einem Daemon-Thread (blockt nie den Caller/Loop).
       Aktualisiert last_status/last_fired_at/fail_count des Webhooks."""
    # SECURITY: nur http(s) zulassen — sonst SSRF/file:// über eine registrierte
    # Webhook-URL (z.B. internes Ziel anpingen via _urlopen). Schemata wie
    # file://, gopher://, ftp:// werden hier hart abgelehnt.
    if not isinstance(url, str) or not url.lower().startswith(("http://", "https://")):
        log.warning("Webhook %s: URL-Schema nicht erlaubt (nur http/https) — übersprungen", wid)
        return
    def _worker():
        status = "error"
        try:
            data = json.dumps(body, ensure_ascii=False).encode("utf-8")
            req = _UrlRequest(
                url, data=data, method="POST",
                headers={"Content-Type": "application/json",
                         "User-Agent": "tiktok-bot-webhook/1.0"})
            with _urlopen(req, timeout=8) as resp:
                status = f"{getattr(resp, 'status', resp.getcode())}"
        except Exception as e:
            status = f"err:{type(e).__name__}"
        now = datetime.now(timezone.utc).isoformat()
        ok = status[:1] in ("2", "3")
        try:
            with db_conn() as conn:
                if ok:
                    conn.execute("UPDATE webhooks SET last_status=?, last_fired_at=?, "
                                 "fail_count=0 WHERE id=?", (status[:32], now, wid))
                else:
                    conn.execute("UPDATE webhooks SET last_status=?, last_fired_at=?, "
                                 "fail_count=COALESCE(fail_count,0)+1 WHERE id=?",
                                 (status[:32], now, wid))
                conn.commit()
        except Exception:
            pass
    _threading_for_db.Thread(target=_worker, name=f"webhook-{wid}", daemon=True).start()


def _fire_webhooks(kind, severity, summary, payload):
    """Dispatch an alle aktivierten Webhooks die auf 'kind' hören. Best-effort:
       schluckt alle Fehler, blockt nie (jeder POST läuft in eigenem Thread).
       Wird aus log_event() aufgerufen → MUSS robust sein."""
    try:
        with db_conn() as conn:
            rows = conn.execute(
                "SELECT id, url, events FROM webhooks WHERE enabled=1").fetchall()
    except Exception:
        return
    if not rows:
        return
    body = {
        "event": kind,
        "severity": severity,
        "summary": summary,
        "payload": payload or {},
        "ts": datetime.now(timezone.utc).isoformat(),
        "source": "tiktok-bot",
    }
    for r in rows:
        try:
            if _webhook_event_match(r["events"], kind):
                _post_json_threaded(r["url"], body, r["id"])
        except Exception:
            continue


def _quiet_hours_config():
    # v4.0-W33: Normalisierung nach nc/cfgnorm.py (bitgenau geprüft).
    return _nc_cfgnorm.normalize_quiet_hours(_cfg_get("quiet_hours", {}))


def _in_quiet_hours(now_hour=None):
    """True wenn die aktuelle (lokale) Stunde im Quiet-Hours-Fenster liegt.
       Unterstützt über-Mitternacht-Fenster (z.B. 23→7)."""
    cfg = _quiet_hours_config()
    if not cfg["enabled"]:
        return False
    h = now_hour if now_hour is not None else datetime.now().hour
    s, e = cfg["start"], cfg["end"]
    if s == e:
        return False
    if s < e:
        return s <= h < e
    return h >= s or h < e          # Wrap über Mitternacht


def _tracking_max_duration(tid):
    """Per-Streamer-Aufnahmedauer-Override (Sekunden) oder None."""
    try:
        with db_conn() as conn:
            row = conn.execute("SELECT max_duration_override FROM trackings WHERE id=?",
                              (tid,)).fetchone()
        if row and row["max_duration_override"]:
            v = int(row["max_duration_override"])
            return v if v > 0 else None
    except Exception:
        pass
    return None


def _latest_popularity(conn, username):
    """Neuester follower_count für einen User aus profile_snapshots (oder 0)."""
    row = conn.execute(
        "SELECT follower_count FROM profile_snapshots WHERE username=? "
        "ORDER BY captured_at DESC LIMIT 1", (username,)).fetchone()
    return int(row["follower_count"]) if row and row["follower_count"] else 0





