@dashboard_app.route("/api/notifications/quiet-hours", methods=["GET", "POST"])
def api_quiet_hours():
    """GET: aktuelle Quiet-Hours-Config. POST {enabled, start, end} setzen.
       start/end sind Stunden 0-23 (über-Mitternacht-Fenster erlaubt, z.B. 23→7)."""
    if request.method == "POST":
        payload = request.get_json(silent=True) or {}
        try:
            enabled = bool(payload.get("enabled", False))
            start = int(payload.get("start", 23)) % 24
            end = int(payload.get("end", 7)) % 24
        except (TypeError, ValueError):
            return jsonify(ok=False, error="start/end müssen Stunden 0-23 sein."), 400
        _cfg_set("quiet_hours", {"enabled": enabled, "start": start, "end": end})
        return jsonify(ok=True, enabled=enabled, start=start, end=end)
    cfg = _quiet_hours_config()
    return jsonify(ok=True, currently_quiet=_in_quiet_hours(), **cfg)


