def _ov_clip_text(t, maxlen=None):
    """Text auf Overlay-Länge kürzen — an der letzten Satzgrenze, sonst hart."""
    t = " ".join(str(t or "").split())
    n = int(maxlen or AZRAEL_OVERLAY_MAXLEN)
    if len(t) <= n:
        return t
    cut = t[:n]
    for sep in (". ", "! ", "? ", "; "):
        p = cut.rfind(sep)
        if p > n * 0.55:
            return cut[:p + 1]
    p = cut.rfind(" ")
    return (cut[:p] if p > n * 0.6 else cut).rstrip(" ,;:") + " …"

