# V37-ADBLOCK: Fremdwerbung unterbinden. Erkennt Eigenwerbung Fremder (fremder
# Kanal-Link, "folgt mir auf...", fremder Discord-Invite) — schon EIN Vorkommen.
# Die eigenen Kanäle/Discord des Streamers sind ausgenommen (Allowlist aus .env),
# damit der Streamer und seine Mods weiter auf den eigenen Kram verweisen dürfen.
_AD_URL = re.compile(r"(?:https?://|www\.)?([a-z0-9-]+\.[a-z]{2,})(?:/\S*)?", re.I)
_AD_INVITE = re.compile(r"(?:discord\.gg|discord\.com/invite|t\.me|telegram\.me)/\S+", re.I)
_AD_PHRASE = re.compile(
    r"(?:folg(?:t|e)?\s+mir|check(?:t)?\s+(?:meinen?|my)|abonn?ier(?:t|e)?\s+mein|"
    r"schau(?:t)?\s+(?:bei\s+mir|auf\s+mein)|besuch(?:t|e)?\s+mein|"
    r"mein(?:en|em)?\s+(?:kanal|channel|stream|discord|profil)|"
    r"follow\s+me|sub\s+to\s+my|check\s+out\s+my)", re.I)


def _ad_allowlist():
    """Eigene Domains/Kanalnamen, die NICHT als Fremdwerbung gelten.
       v4.0-W56: Aufbaulogik nach nc/admod.py extrahiert (bitgenau geprüft)."""
    return _nc_admod.build_allowlist(
        os.getenv("KICK_CHANNEL_URL", ""),
        [os.getenv(ev, "") for ev in ("KICK_CHANNEL", "TWITCH_CHANNEL",
                                      "YOUTUBE_CHANNEL", "STREAMER_NAME")],
        _AD_URL)


def _own_invites():
    """Vollständige eigene Invite-Links (Domain ALLEIN reicht NICHT — sonst gälte
       jeder discord.gg-Invite als eigen). Vergleich auf ganzen Pfad."""
    out = set()
    v = (os.getenv("DISCORD_INVITE_URL", "") or "").strip().lower().rstrip("/")
    if v:
        # discord.gg/meinserver → 'discord.gg/meinserver'
        mm = re.search(r"(discord\.gg|discord\.com/invite|t\.me)/(\S+)", v)
        if mm:
            out.add(f"{mm.group(1)}/{mm.group(2)}")
    return out


def _detect_foreign_ad(text):
    """→ Grund-String bei Fremdwerbung, sonst None. Eigenes ist per Allowlist frei."""
    t = (text or "").lower()
    allow = _ad_allowlist()
    own_inv = _own_invites()
    # 1. fremder Invite-Link (Discord/Telegram) — voller Pfad muss eigenem gleichen
    for m in _AD_INVITE.finditer(t):
        seg = m.group(0).rstrip("/")
        if not any(seg.startswith(oi) or oi in seg for oi in own_inv):
            return "Fremdwerbung (Invite-Link)"
    # 2. fremde Domain — aber Plattform-Domains + Eigenes ausgenommen. Invite-
    #    Domains (discord.gg/t.me) hier ueberspringen, die macht Schritt 1.
    for m in _AD_URL.finditer(t):
        dom = m.group(1).lower()
        if dom in allow or dom in ("discord.gg", "discord.com", "t.me", "telegram.me"):
            continue
        return "Fremdwerbung (Link)"
    # 3. Werbe-Phrase MIT Verweis auf fremden Kanal/Namen
    if _AD_PHRASE.search(t):
        for m in re.finditer(r"@([a-z0-9_]{3,})", t):
            if m.group(1).lower() not in allow:
                return "Fremdwerbung (Eigenwerbung)"
        if re.search(r"folg|abonn|sub\s+to|follow\s+me|check\s+out", t):
            return "Fremdwerbung (Eigenwerbung)"
    return None


class KickModerator:
    """KI-Chat-Moderator für den EIGENEN Kick-Kanal. Liest den Chat (Websocket),
       beantwortet optional Fragen (Ollama) und moderiert optional Spam/Toxizität.
       Nutzt die offizielle Kick-API (OAuth 2.1 App-Token)."""
    def __init__(self):
        self._token = None
        self._token_exp = 0
        self._task = None
        self._engage_task = None
        self.running = False
        self._last_reply = 0.0
        self.cfg = {"auto_reply": False, "auto_moderate": False,
                    "sensitivity": 0.85, "engage_min": 0,
                    "persona": "freundlich, locker, hilfsbereit",
                    "persona_full": "",            # AZRAEL System-Prompt (leer = eingebaute Persona)
                    "reaction_prompt": "",         # AZRAEL Live-Reaction-Prompt (leer = eingebauter)
                    "auto_timeout_max_min": MOD_AUTO_TIMEOUT_MAX_MIN,
                    "greeting": "", "banned_words": [],
                    "learn_badwords": False,   # neue Schimpfwörter aus Live-Mod lernen (→ Review-Queue)
                    "learn_autoadd": False}    # gelernte Wörter sofort in banned_words übernehmen (riskant)
        # Persistierte Banned-Words laden (vom Dashboard-Import; übersteht Neustart)
        try:
            _bw = _load_banned_words_file()
            if _bw:
                self.cfg["banned_words"] = _bw
        except Exception:
            pass
        self.stats = {"seen": 0, "replied": 0, "moderated": 0, "connected": False,
                      "dc_seen": 0, "dc_moderated": 0}   # F93: Discord-KI-Mod-Zähler
        self.last_spoken = {"text": "", "ts": 0.0}    # für das Overlay (AI "spricht")
        # BUGHUNT: Begrenzung gleichzeitiger Ollama-Verarbeitungen, sonst staut sich
        # bei aktivem Chat eine unbegrenzte Task-Flut (RAM/CPU-Explosion).
        self._sema = asyncio.Semaphore(3)
        # AUSBAU: Spam-Heuristiken (ohne Ollama) + eskalierende Strafen pro User.
        self._infractions = {}     # user_id -> {"n", "ts"}  (eskalierende Timeouts, verjähren nach 1h)
        self._msg_hist = {}        # user_id -> [(ts, content_lower)]  (Flood/Repeat-Erkennung)
        self.cfg.setdefault("spam_filter", True)     # Caps/Flood/Link/Mention-Heuristik aktiv
        self.cfg.setdefault("block_ads", os.getenv("MOD_BLOCK_ADS", "1").strip().lower() in ("1", "true", "yes", "on", "y"))   # V37-ADBLOCK: Fremdwerbung unterbinden
        self.cfg.setdefault("max_caps_ratio", 0.7)   # >70% GROSSBUCHSTABEN (ab 10 Buchstaben) = Caps-Spam
        self.cfg.setdefault("flood_max", 5)          # >N Nachrichten im flood_window_s = Flood
        self.cfg.setdefault("flood_window_s", 7)     # Zeitfenster (Sek.) für Flood/Repeat
        self.cfg.setdefault("max_links", 2)          # >N URLs in einer Nachricht = Link-Spam
        self.cfg.setdefault("max_mentions", 5)       # >N @-Mentions = Mention-Spam
        self.cfg.setdefault("escalate", True)        # Wiederholungstäter → längere (gedeckelte) Timeouts
        self.cfg.setdefault("intensity", 1)          # Persona-Ton: 0=sanft, 1=normal, 2=streng

    async def _get_token(self, session):
        if self._token and _time_mod.monotonic() < self._token_exp - 30:
            return self._token
        if not (KICK_CLIENT_ID and KICK_CLIENT_SECRET):
            return None
        try:
            async with session.post(
                "https://id.kick.com/oauth/token",
                data={"grant_type": "client_credentials",
                      "client_id": KICK_CLIENT_ID, "client_secret": KICK_CLIENT_SECRET},
                timeout=aiohttp.ClientTimeout(total=15)) as resp:
                if resp.status != 200:
                    log.warning(f"Kick OAuth HTTP {resp.status}")
                    return None
                d = await resp.json()
                self._token = d.get("access_token")
                self._token_exp = _time_mod.monotonic() + int(d.get("expires_in", 3600))
                return self._token
        except Exception as e:
            log.warning(f"Kick OAuth Fehler: {e}")
            return None

    # V37-P4b: Dank für Subs/Gifts im EIGENEN Kick-Kanal. Template statt
    # LLM: ein Dankeschön muss in <1s raus und darf nie am LLM-Budget oder
    # einem Backend-Ausfall scheitern. 60s-Cooldown pro Gifter gegen
    # Combo-Spam (Kick feuert Gift-Events teils mehrfach).
    _THANK_LAST = {}

    async def _thank_own_gift(self, user, cnt, session=None):
        try:
            now = _time_mod.monotonic()
            last = self._THANK_LAST.get(user, 0.0)
            if now - last < 60:
                return
            self._THANK_LAST[user] = now
            if len(self._THANK_LAST) > 200:      # Speicher deckeln
                for k in list(self._THANK_LAST)[:100]:
                    self._THANK_LAST.pop(k, None)
            import random as _rnd
            if cnt and int(cnt) > 1:
                pool = [f"🖤 {user} haut {cnt}x Subs/Gifts raus — MASSIVER Support, danke dir!",
                        f"⚡ {cnt}x von {user}?! Der Kanal verneigt sich. Danke!",
                        f"🖤 {user} mit {cnt}x — du trägst den Stream. Danke!"]
            else:
                pool = [f"🖤 Danke für den Support, {user}!",
                        f"⚡ {user}, danke dir — genau solche Leute halten das hier am Laufen!",
                        f"🖤 Support von {user} — gesehen und gefeiert, danke!"]
            await self.send_message(_nc_i18n.t(_rnd.choice(pool)), session=session)
        except Exception as e:
            log.debug("Kick-Dank fehlgeschlagen: %s", e)

    async def send_message(self, content, session=None):
        own = False
        if session is None:
            session = aiohttp.ClientSession(); own = True
        try:
            # v4.0-W17: Kick lehnte den Chat-POST mit HTTP 401 "Unauthorized" ab.
            # Ursache: der APP-Token (client_credentials) darf NICHT im Chat
            # schreiben — dafuer braucht es den USER-Token mit Scope chat:write
            # (seit B169 vorhanden, wird schon fuer Titel/Kategorie genutzt).
            # Mit User-Token posten wir als "user", sonst Fallback "bot".
            _utok = await _kick_user_token(session)
            tok = _utok or await self._get_token(session)
            if not tok:
                _KICK_SEND_LAST.update(ts=_time_mod.time(), ok=False, status=0, bid=0,
                                       error="kein Token — KICK_CLIENT_ID/SECRET pruefen "
                                             "bzw. Kick im Dashboard verbinden")
                return False, "kein Token (client id/secret?)"
            payload = {"type": "user" if _utok else "bot", "content": content[:480]}
            _bid = KICK_BROADCASTER_ID or await _kick_broadcaster_id()
            if _bid:
                payload["broadcaster_user_id"] = _bid
            async with session.post(
                "https://api.kick.com/public/v1/chat",
                json=payload, headers={"Authorization": f"Bearer {tok}"},
                timeout=aiohttp.ClientTimeout(total=15)) as resp:
                ok = 200 <= resp.status < 300
                # v4.0-W10: bei Fehlern Kicks ANTWORTTEXT mitnehmen — "HTTP 400"
                # allein sagt nicht, ob Broadcaster-ID, Scope oder Inhalt schuld ist.
                detail = ""
                if not ok:
                    try:
                        detail = (await resp.text())[:180].replace("\n", " ").strip()
                    except Exception:
                        detail = ""
                    if not _bid:
                        detail = (detail + " · keine Broadcaster-ID aufloesbar "
                                  "(KICK_BROADCASTER_ID setzen)").strip()
                    if resp.status in (401, 403) and not _utok:
                        detail = (detail + " · App-Token darf nicht chatten — Kick im "
                                  "Dashboard verbinden (Scope chat:write)").strip()
                if ok:
                    _modlog("send", "bot", content)
                    self.last_spoken = {"text": content, "ts": _time_mod.monotonic()}
                _KICK_SEND_LAST.update(
                    ts=_time_mod.time(), ok=ok, status=resp.status, bid=_bid,
                    error=("" if ok else f"HTTP {resp.status}"
                           + (f": {detail}" if detail else "")))
                return ok, (None if ok else _KICK_SEND_LAST["error"])
        except Exception as e:
            _KICK_SEND_LAST.update(ts=_time_mod.time(), ok=False, status=0,
                                   error=str(e)[:180])
            return False, str(e)
        finally:
            if own:
                await session.close()

    async def timeout_user(self, user_id, minutes, reason, session):
        try:
            # v4.0-W17: Moderation braucht Nutzerrechte (Scope moderation:ban).
            # Mit reinem App-Token antwortet Kick 401 — wie beim Chat-Senden.
            tok = await _kick_user_token(session) or await self._get_token(session)
            if not tok:
                return False
            payload = {"user_id": user_id, "duration": max(1, min(minutes, 10080)),
                       "reason": reason[:100]}
            _bid = KICK_BROADCASTER_ID or await _kick_broadcaster_id()
            if _bid:
                payload["broadcaster_user_id"] = _bid
            async with session.post(
                "https://api.kick.com/public/v1/moderation/bans",
                json=payload, headers={"Authorization": f"Bearer {tok}"},
                timeout=aiohttp.ClientTimeout(total=15)) as resp:
                return 200 <= resp.status < 300
        except Exception:
            return False

    async def channel_info(self, session=None):
        """Kanal-Infos (live-Status, Zuschauer, Titel) via offizielle API."""
        own = False
        if session is None:
            session = aiohttp.ClientSession(); own = True
        try:
            tok = await self._get_token(session)
            if not tok:
                return None, "kein Token"
            params = {}
            _bid = KICK_BROADCASTER_ID or await _kick_broadcaster_id()
            if _bid:
                params["broadcaster_user_id"] = _bid
            async with session.get(
                "https://api.kick.com/public/v1/channels",
                params=params, headers={"Authorization": f"Bearer {tok}"},
                timeout=aiohttp.ClientTimeout(total=15)) as resp:
                if not (200 <= resp.status < 300):
                    return None, f"HTTP {resp.status}"
                d = await resp.json()
                row = (d.get("data") or [None])
                row = row[0] if isinstance(row, list) and row else d
                stream = (row or {}).get("stream") or {}
                # B138: followers_count steht in der v1-Antwort NICHT drin —
                # deshalb blieb die Anzeige auf "—", obwohl Zuschauer und Titel
                # ankamen. Rueckfall auf den keyless v2-Endpunkt (gecacht).
                _fol = (row or {}).get("followers_count")
                if _fol is None:
                    _fol = await _kick_follower_count(session)
                return {
                    "slug": (row or {}).get("slug"),
                    "title": (row or {}).get("stream_title") or stream.get("title"),
                    "category": ((row or {}).get("category") or {}).get("name"),
                    "is_live": bool(stream.get("is_live")),
                    "viewers": stream.get("viewer_count"),
                    "followers": _fol,
                }, None
        except Exception as e:
            return None, str(e)
        finally:
            if own:
                await session.close()

    async def update_channel(self, title=None, category_id=None, session=None):
        own = False
        if session is None:
            session = aiohttp.ClientSession(); own = True
        try:
            # B169: erst der USER-Token (channel:write), sonst App-Token-Fallback.
            tok = await _kick_user_token(session) or await self._get_token(session)
            if not tok:
                return False, "kein Token"
            payload = {}
            if title is not None: payload["stream_title"] = title[:140]
            if category_id: payload["category_id"] = int(category_id)
            if not payload:
                return False, "nichts zu ändern"
            async with session.patch(
                "https://api.kick.com/public/v1/channels",
                json=payload, headers={"Authorization": f"Bearer {tok}"},
                timeout=aiohttp.ClientTimeout(total=15)) as resp:
                if 200 <= resp.status < 300:
                    return True, None
                # B164: App-Token (client_credentials) darf einen Kanal NICHT
                # editieren — Kick verlangt dafür einen User-OAuth-Token mit
                # Scope channel:write. Klartext statt nacktem „HTTP 401".
                if resp.status in (401, 403):
                    return False, ("Kick: App-Token darf Titel/Kategorie nicht setzen — "
                                   "User-OAuth mit Scope channel:write nötig")
                return False, f"HTTP {resp.status}"
        except Exception as e:
            return False, str(e)
        finally:
            if own:
                await session.close()

    async def search_category(self, query, session=None):
        """B142: Kick-Kategorie per Name suchen → (category_id, name) oder
           (None, None). Nutzt GET /public/v1/categories?q=. Nimmt bevorzugt
           einen exakten (case-insensitiven) Namenstreffer, sonst den ersten."""
        q = (query or "").strip()
        if not q:
            return None, None
        own = False
        if session is None:
            session = aiohttp.ClientSession(); own = True
        try:
            tok = await self._get_token(session)
            if not tok:
                return None, None
            async with session.get(
                "https://api.kick.com/public/v1/categories",
                params={"q": q}, headers={"Authorization": f"Bearer {tok}"},
                timeout=aiohttp.ClientTimeout(total=15)) as resp:
                if not (200 <= resp.status < 300):
                    return None, None
                j = await resp.json(content_type=None)
            data = j.get("data") if isinstance(j, dict) else j
            data = data or []
            if not data:
                return None, None
            exact = next((d for d in data
                          if (d.get("name") or "").strip().lower() == q.lower()), None)
            pick = exact or data[0]
            return pick.get("id"), pick.get("name")
        except Exception as e:
            log.debug("Kick search_category: %s", e)
            return None, None
        finally:
            if own:
                await session.close()

    async def _classify(self, content):
        """Ollama-Klassifikation: gibt dict {toxic:0..1, question:bool} oder None."""
        sys = ("Klassifiziere die Chat-Nachricht. Antworte NUR mit JSON: "
               '{"toxic": <0.0-1.0>, "question": <true|false>}. '
               "toxic=Wahrscheinlichkeit für Spam/Beleidigung/Hass.")
        text, err = await ai_chat(
            [{"role": "system", "content": sys}, {"role": "user", "content": content[:500]}],
            timeout=20)
        if err or not text:
            return None
        try:
            raw = re.sub(r"^```(?:json)?|```$", "", text.strip(), flags=re.MULTILINE).strip()
            d = json.loads(raw)
            return {"toxic": float(d.get("toxic", 0)), "question": bool(d.get("question"))}
        except Exception:
            return None

    async def _extract_badwords(self, content):
        """Ollama: extrahiert aus einer als toxisch geflaggten Nachricht NUR echte
           Schimpf-/Hasswörter + Sprache. -> [{"word","lang"}] (leer bei Unklarheit)."""
        sys = ("Extrahiere aus der Chat-Nachricht NUR echte Schimpf-/Hasswörter "
               "(Beleidigungen, Slurs) — KEINE harmlosen Wörter. Antworte NUR mit JSON-Array "
               '[{"word":"<wort>","lang":"<ISO-639-1>"}]. Leeres Array [] wenn keines eindeutig.')
        text, err = await ai_chat(
            [{"role": "system", "content": sys}, {"role": "user", "content": content[:300]}],
            timeout=20)
        if err or not text:
            return []
        try:
            raw = re.sub(r"^```(?:json)?|```$", "", text.strip(), flags=re.MULTILINE).strip()
            arr = json.loads(raw)
            out = []
            if isinstance(arr, list):
                for it in arr[:8]:
                    if not isinstance(it, dict):
                        continue
                    w = str(it.get("word", "")).strip()[:40]
                    lg = str(it.get("lang", "")).strip()[:5].lower()
                    if w:
                        out.append({"word": w, "lang": lg or "?"})
            return out
        except Exception:
            return []

    async def _learn_from(self, content):
        """Lernt neue Schimpfwörter aus einer toxischen Nachricht: neue Kandidaten →
           Review-Queue. Optional sofortige Übernahme. -> Anzahl neu."""
        if not self.cfg.get("learn_badwords"):
            return 0
        now = _time_mod.monotonic()
        if now - getattr(self, "_last_learn", 0.0) < 5:   # Rate-Limit gegen Ollama-Flut
            return 0
        self._last_learn = now
        cands = await self._extract_badwords(content)
        if not cands:
            return 0
        known = {w.lower() for w in (self.cfg.get("banned_words") or [])}
        learned = _learned_load()
        known |= {str(x.get("word", "")).lower() for x in learned}
        added = 0
        for c in cands:
            w = c["word"]
            if not w or w.lower() in known:
                continue
            known.add(w.lower())
            learned.append({"word": w, "lang": c.get("lang", "?"), "example": content[:160],
                            "ts": _time_mod.time(), "promoted": bool(self.cfg.get("learn_autoadd"))})
            added += 1
            if self.cfg.get("learn_autoadd"):
                bw = list(self.cfg.get("banned_words") or [])
                bw.append(w)
                self.cfg["banned_words"] = _merge_banned_words(bw, [])
                _save_banned_words_file(self.cfg["banned_words"])
        if added:
            _learned_save(learned)
            _modlog("learn", "ai", f"{added} neue Wort-Kandidat(en)", {"example": content[:80]})
        return added

    async def _reply(self, sender, content, session):
        # AZRAEL-Persona: Dashboard-Override (cfg.persona_full) vor env/Default,
        # immer plus nicht-überschreibbare Safety-Rails. cfg.persona = Zusatz-Ton.
        base = (self.cfg.get("persona_full") or "").strip() or AZRAEL_PERSONA
        base += _persona_intensity_hint(self.cfg.get("intensity", 1))
        sys = base + " " + _MOD_SAFETY_RAILS
        tone = (self.cfg.get("persona") or "").strip()
        if tone and tone != "freundlich, locker, hilfsbereit":
            sys += f" Zusätzlicher Ton-Wunsch: {tone}."
        sys += f" Zuschauer '{sender}' schrieb:"
        _t0 = _time_mod.monotonic()
        text, err = await ai_chat(
            [{"role": "system", "content": sys}, {"role": "user", "content": content[:400]}],
            timeout=30)
        _ai_telemetry("Kick-Reply", len(content or ""), len(text or ""),
                      int((_time_mod.monotonic() - _t0) * 1000), bool(text), err)
        if err or not text:
            return
        ok, _ = await self.send_message(_nc_i18n.t(f"@{sender} {text.strip()}"), session)
        if ok:
            self.stats["replied"] += 1
            _modlog("reply", "bot", text.strip(), {"to": sender})

    async def react(self, statement: str, context=None, source=None):
        """AZRAEL reagiert LIVE (vor der Kamera) auf eine Aussage/Behauptung —
           menschlich, emotional und passend zum aktuellen Stream-Kontext, mit Logik
           + moralischem Kompass; stellt Zweifelhaftes in Frage, bleibt aber als KI
           transparent (kein absolutes Urteil). Via Ollama. Returns (text, err)."""
        statement = (statement or "").strip()
        if not statement:
            return None, "leere Aussage"
        base = ""
        if source:                                            # UPGRADE: pro-Streamer-Persona
            base = _streamer_persona_get(source)
        if not base:
            base = (self.cfg.get("persona_full") or "").strip() or AZRAEL_PERSONA
        rmode = (self.cfg.get("reaction_prompt") or "").strip() or AZRAEL_REACTION_PROMPT
        emo = ("Wirke menschlich und zeige passende, glaubwürdige Emotionen (Freude, "
               "Skepsis, Empörung, Belustigung, Mitgefühl) — je nach Lage, nie aufgesetzt.")
        ctx = (context if context is not None else _AZRAEL_CONTEXT.get("text", "")).strip()
        sys = base + _persona_intensity_hint(self.cfg.get("intensity", 1)) + " " + rmode + " " + emo + " " + _MOD_REACTION_RAILS
        msgs = [{"role": "system", "content": sys}]
        if ctx:
            msgs.append({"role": "system",
                         "content": f"Aktueller Kontext/Stimmung im Stream gerade: {ctx[:400]}"})
        msgs.append({"role": "user", "content": statement[:800]})
        async with self._sema:                        # Backoff (parallele AI-Calls deckeln)
            try:      # V37-B92: absolute Obergrenze — Loop darf NIE hängen
                text, err = await asyncio.wait_for(
                    ai_chat(msgs), timeout=REACTION_AI_TIMEOUT + 20)
            except asyncio.TimeoutError:
                text, err = None, "timeout (Reaction-Budget)"
        if err or not text:
            _react_warn("reactai", "⚠ AZRAEL reagiert NICHT — Reaction-AI (%s) Fehler: %s. "
                        "Keyless-Default ist REACTION_AI_PROVIDER=pollinations. Falls Ollama: läuft "
                        "es (`ollama ps`) + Modell gepullt? Schnelltest: AZRAEL → AI-Chat." %
                        (REACTION_AI_PROVIDER, err or "leere Antwort"))
            return None, (err or "keine Antwort")
        text = text.strip()
        audio = ""
        _dir = _LIVE_DIRECTORS.get(source) if source else None
        if _OVERLAY.get("voice_enabled") and _OVERLAY.get("voice_engine") == "piper" \
                and _OVERLAY.get("voice_reactions", True):
            try:
                _vrate = _dir.voice_style()["rate"] if _dir is not None else None   # F100: Energie → Tempo
                audio = await _piper_say(text, rate=_vrate, source_user=source) or ""
            except Exception:
                audio = ""
        # F100: Emotion bevorzugt aus der Regie-Stimmung (kohärent über Zeit),
        # Text-Heuristik als Fallback.
        _emo = _azrael_emotion(text)
        if _dir is not None:
            _emo = {"hype": "hype", "drama": "angry", "quiet": "neutral"}.get(_dir.mood, _emo)
        _AZRAEL_REACTION.update(ts=_time_mod.time(), statement=statement[:200],
                                text=text, active=True, audio=audio, source=(source or ""),
                                emotion=_emo)
        self.stats["reacted"] = self.stats.get("reacted", 0) + 1
        _modlog("reaction", "azrael", text, {"on": statement[:120], "src": source or ""})
        if DISCORD_WEBHOOK_URL:
            _spawn(_discord_notify(text, source), name="discord-notify")   # UPGRADE: Discord-Webhook (GC-sicher via _spawn)
        # B138: HIER fehlte der Weg ins eigentliche Publikum. Die Reaktion ging
        # an Stimme, Overlay, Dashboard und Discord — aber in keinen einzigen
        # Stream-Chat. _spawn statt await: wir halten oben self._sema, und ein
        # haengender Chat-Endpunkt darf die naechste Reaktion nicht aufhalten.
        _spawn(_azrael_reaction_to_chats(text, source), name="azrael-chat")
        return text, None

    def _banned_hit(self, content):
        low = content.lower()
        for w in (self.cfg.get("banned_words") or []):
            if w and w.lower() in low:
                return w
        return None

    def _spam_check(self, content, user_id):
        """Schnelle Heuristik OHNE Ollama. Gibt Grund-String zurück wenn Spam, sonst None.
           Erkennt CAPS-Spam, Link-/Mention-Spam, Flood und identische Wiederholungen."""
        if not self.cfg.get("spam_filter"):
            return None
        c = (content or "").strip()
        if not c:
            return None
        # V37-ADBLOCK: Fremdwerbung — schon EIN fremder Link / "folgt mir auf..." /
        # fremder Discord-Invite reicht. Eigene Links (eigener Kanal/Discord) sind
        # per Allowlist ausgenommen, damit der Streamer selbst werben darf.
        if self.cfg.get("block_ads", True):
            ad = _detect_foreign_ad(c)
            if ad:
                return ad
        # B165: zustandslose Gründe (CAPS/Link/Mention) via nc.modheuristics —
        # identische Reihenfolge/Grenzen, nur nicht mehr inline.
        sr = _nc_mod.stateless_reason(
            c, max_caps_ratio=float(self.cfg.get("max_caps_ratio", 0.7)),
            max_links=int(self.cfg.get("max_links", 2)),
            max_mentions=int(self.cfg.get("max_mentions", 5)))
        if sr:
            return sr
        if user_id:
            now = _time_mod.monotonic()
            win = float(self.cfg.get("flood_window_s", 7))
            hist = self._msg_hist.setdefault(user_id, [])
            hist.append((now, c.lower()))
            self._msg_hist[user_id] = [(t, m) for (t, m) in hist if now - t <= win]
            _nc_mod.prune_history(self._msg_hist, now, win)   # W14: kein Dauerwachstum
            recent = [m for (_t, m) in self._msg_hist.get(user_id, [])]
            fr = _nc_mod.flood_reason(recent, c.lower(),
                                      flood_max=int(self.cfg.get("flood_max", 5)))
            if fr:
                return fr
        return None

    def _escalation_minutes(self, user_id):
        """Eskalierende Timeout-Dauer für Wiederholungstäter, gedeckelt durch den autonomy-Cap.
           1. Verstoß → 1min, 2. → 5min, ab 3. → Cap. Infraktionen verjähren nach 1h."""
        cap = int(self.cfg.get("auto_timeout_max_min") or MOD_AUTO_TIMEOUT_MAX_MIN)
        if not self.cfg.get("escalate") or not user_id:
            return min(cap, 5)
        now = _time_mod.monotonic()
        rec = self._infractions.get(user_id) or {"n": 0, "ts": 0.0}
        if now - rec["ts"] > 3600:
            rec = {"n": 0, "ts": now}
        rec["n"] += 1
        rec["ts"] = now
        self._infractions[user_id] = rec
        return _nc_mod.escalation_minutes(rec["n"], cap=cap)  # B165: Leiter [1,5,cap]

    def _escalation_decide(self, user_id):
        """v4.0-W19: ("warn", 0) oder ("timeout", minuten). Zaehlt denselben
           Verstoss-Zaehler wie _escalation_minutes, entscheidet aber, ob es
           beim ERSTEN Mal nur eine oeffentliche Verwarnung gibt."""
        cap = int(self.cfg.get("auto_timeout_max_min") or MOD_AUTO_TIMEOUT_MAX_MIN)
        warn_first = _mod_warn_first(self.cfg)
        if not self.cfg.get("escalate") or not user_id:
            return ("timeout", min(cap, 5))
        now = _time_mod.monotonic()
        rec = self._infractions.get(user_id) or {"n": 0, "ts": 0.0}
        if now - rec["ts"] > 3600:
            rec = {"n": 0, "ts": now}
        rec["n"] += 1
        rec["ts"] = now
        self._infractions[user_id] = rec
        # W19: derselbe Leck-Typ wie bei den Flood-Historien (W14) — Eintraege
        # verjaehren inhaltlich, der Schluessel blieb aber ewig liegen.
        _nc_mod.prune_infractions(self._infractions, now)
        return _nc_mod.escalation_step(rec["n"], cap=cap, warn_first=warn_first)

    async def _handle(self, sender, content, user_id, session, roles=None):
        self.stats["seen"] += 1
        # v4.0-W16: das EIGENE Team nicht automoderieren. Vorher wurden Kicks
        # Badges gar nicht ausgewertet — ein Moderator (oder der Broadcaster)
        # mit Link/GROSSSCHRIFT kassierte einen Timeout vom eigenen Bot.
        # v4.0-W21 FIX: galt versehentlich fuer den GANZEN Handler — dadurch
        # bekamen Broadcaster/Moderatoren auch KEINE AZRAEL-Antworten mehr.
        _exempt = _mod_is_exempt(roles, self.cfg)
        # V37-W-SHIELD: Doxxing/Hate/Drohung — vor Banned-Words, vor KI.
        if self.cfg.get("auto_moderate") and user_id and not _exempt:
            _hard = _sentinel_screen(content)
            if _hard:
                if await self.timeout_user(user_id,
                        int(self.cfg.get("auto_timeout_max_min") or MOD_AUTO_TIMEOUT_MAX_MIN),
                        f"SENTINEL {_hard[0]}: {_hard[1]}", session):
                    self.stats["moderated"] += 1
                    _modlog("timeout", "sentinel-shield", content,
                            {"user": sender, "cat": _hard[0], "what": _hard[1]})
                return
        # BUGHUNT: Banned-Words zuerst (kein Ollama nötig) → sofortiger Timeout.
        if self.cfg.get("auto_moderate") and user_id and not _exempt:
            hit = self._banned_hit(content)
            if hit:
                if await self.timeout_user(user_id, int(self.cfg.get("auto_timeout_max_min") or MOD_AUTO_TIMEOUT_MAX_MIN), f"Banned word: {hit}", session):
                    self.stats["moderated"] += 1
                    _modlog("timeout", "filter", content, {"user": sender, "word": hit})
                return
            # AUSBAU: schnelle Spam-Heuristik (ohne Ollama) → eskalierender Cool-off-Timeout.
            sp = self._spam_check(content, user_id)
            if sp:
                # W19: beim ERSTEN Verstoss nur oeffentlich verwarnen — das
                # beendet die meisten Faelle, ohne jemanden stummzuschalten.
                action, mins = self._escalation_decide(user_id)
                if action == "warn":
                    await self.send_message(_nc_i18n.t(_mod_warn_text(sender, sp)), session)
                    self.stats["moderated"] += 1
                    _modlog("warn", "auto-mod-kick", content,
                            {"user": sender, "reason": sp, "cat": "spam"})
                    return
                if await self.timeout_user(user_id, mins, f"Auto-Mod: {sp}", session):
                    self.stats["moderated"] += 1
                    _modlog("timeout", "spam", content, {"user": sender, "reason": sp, "min": mins})
                return
        # F86 / v4.0-W35: ORACLE-Commands IMMER zuerst — VOR dem auto_reply/
        # auto_moderate-Gate. Sonst funktionieren !recap/!ask nicht, wenn beide
        # Schalter aus sind ("Bot still"). Befehle sind bewusste Interaktion.
        try:
            if ORACLE_ENABLED and content.lstrip().lower().startswith((
                    "!recap", "!ask", "!lore", "!oracle", "!chapters",
                    "!momente", "!mem", "!erinnerung", "!damals")):
                ans = await oracle_handle(sender, content)
                if ans:
                    await self.send_message(_nc_i18n.t(ans), session=session)
                return
        except Exception as e:
            log.debug("oracle hook: %s", e)
        # BUGHUNT: nur klassifizieren wenn überhaupt eine KI-Aktion aktiv ist —
        # sonst unnötige Ollama-Last bei jedem Chat-Event.
        if not (self.cfg.get("auto_reply") or self.cfg.get("auto_moderate")):
            return
        # F87: Kick-Chat-Velocity als zweites Hype-Signal (neben TikTok-Chat) —
        # eskaliert der Restream-Chat, wird die Quelle automatisch geclippt.
        try:
            global _KICK_VELO_LAST
            if DIRECTOR_ENABLED:
                _KICK_MSG_TIMES.append(_time_mod.monotonic())
                if len(_KICK_MSG_TIMES) > 200:
                    del _KICK_MSG_TIMES[:100]
                _src = (_RESTREAM_ACTIVE or {}).get("user")
                if (_src and _clip_should_velocity(_KICK_MSG_TIMES)
                        and _time_mod.monotonic() - _KICK_VELO_LAST > 60):
                    _KICK_VELO_LAST = _time_mod.monotonic()
                    _spawn(clip_moment(_src, "Kick-Hype", "KICK CHAT ESKALIERT"), name="clip-kick-velocity")
        except Exception as e:
            log.debug("kick velocity: %s", e)
        # BUGHUNT: Semaphore begrenzt parallele Ollama-Calls (Task-Flut vermeiden).
        if self._sema.locked():
            return   # keine freien Slots → Nachricht überspringen statt aufstauen
        async with self._sema:
            cls = await self._classify(content)
            if cls is None:
                return
            if self.cfg["auto_moderate"] and cls["toxic"] >= self.cfg["sensitivity"] and user_id:
                ok = await self.timeout_user(user_id, int(self.cfg.get("auto_timeout_max_min") or MOD_AUTO_TIMEOUT_MAX_MIN), "Auto-Mod: Spam/Toxizität", session)
                if ok:
                    self.stats["moderated"] += 1
                    _modlog("timeout", "ai", content, {"user": sender, "toxic": cls["toxic"]})
                try:
                    await self._learn_from(content)   # neue Schimpfwörter lernen (→ Review-Queue)
                except Exception:
                    pass
                return
            if self.cfg["auto_reply"] and cls["question"]:
                now = _time_mod.monotonic()
                if now - self._last_reply >= 12:    # Cooldown gegen Spam-Replies
                    self._last_reply = now
                    await self._reply(sender, content, session)
            # V37-SENTINEL-REACH: AZRAEL antwortet auf direkte Ansprache (@azrael)
            # auch im Kick-Chat — dieselbe Logik wie Twitch/YouTube. Vorher
            # antwortete AZRAEL auf Kick NUR auf erkannte Fragen (auto_reply),
            # nicht auf namentliche Ansprache. Shield screent in _azrael_chat_reply.
            elif _azrael_chat_should_reply(content, "azrael"):
                _r = await _azrael_chat_reply("kick", sender, content)
                if _r:
                    await _azrael_broadcast_reply("kick", sender, _r, session)

    async def _ws_loop(self):
        """Liest den Kick-Chat über den öffentlichen Pusher-Websocket."""
        if not KICK_CHATROOM_ID:
            log.warning("Kick-Moderator: KICK_CHATROOM_ID fehlt — Chat-Lesen deaktiviert")
            return
        url = (f"wss://ws-us2.pusher.com/app/{KICK_PUSHER_KEY}"
               f"?protocol=7&client=js&version=8.4.0&flash=false")
        session = aiohttp.ClientSession()
        try:
            while self.running:
                try:
                    async with session.ws_connect(url, heartbeat=30,
                                                  timeout=aiohttp.ClientTimeout(total=20)) as ws:
                        await ws.send_json({"event": "pusher:subscribe",
                                            "data": {"channel": f"chatrooms.{KICK_CHATROOM_ID}.v2"}})
                        self.stats["connected"] = True
                        # v4.0-W116: wann diese Verbindung stand. Ohne die
                        # Marke kann der Flatter-Waechter nicht unterscheiden,
                        # ob sie zehn Sekunden oder zehn Stunden gehalten hat —
                        # und genau daran haengt, ob eine Trennung Alltag ist.
                        self.stats["since"] = _time_mod.time()
                        log.info("Kick-Moderator: Chat-Websocket verbunden")
                        async for msg in ws:
                            if not self.running:
                                break
                            if msg.type != aiohttp.WSMsgType.TEXT:
                                continue
                            try:
                                frame = json.loads(msg.data)
                                ev = frame.get("event") or ""
                                if "ChatMessage" in ev:
                                    data = json.loads(frame.get("data") or "{}")
                                    content = data.get("content") or ""
                                    sender_obj = data.get("sender") or {}
                                    sender = sender_obj.get("username") or "?"
                                    uid = sender_obj.get("id")
                                    if content:
                                        _restream_chat_push("kick", sender, content)   # F92: Sendebild-Panel
                                        _roles = _nc_mod.kick_roles(sender_obj)
                                        _spawn(self._handle(sender, content, uid, session,
                                                            roles=_roles), name="mod-handle")
                                elif "Follow" in ev:
                                    if _overlay_src_ok("kick"):
                                        try:
                                            data = json.loads(frame.get("data") or "{}")
                                            u = (data.get("user") or {}).get("username") or data.get("username")
                                            if u: _overlay_push("follow", u, platform="kick")
                                        except Exception as e:
                                            _loop_fehler("_ws_loop", e)
                                elif "Subscription" in ev or "Gift" in ev:
                                    # V37-P4b: Eigene Kanal-Events wurden bisher NUR aufs
                                    # Overlay gelegt — für Subs/Gifts im EIGENEN Kick-Chat
                                    # gab es nie ein Dankeschön (während AZRAEL sich für
                                    # fremde TikTok-Gifts bedankte — genau verkehrt herum).
                                    try:
                                        data = json.loads(frame.get("data") or "{}")
                                        u = (data.get("gifter_username") or data.get("username")
                                             or (data.get("user") or {}).get("username") or "jemand")
                                        cnt = len(data.get("gifted_usernames") or []) or data.get("months") or 1
                                        if _overlay_src_ok("kick"):
                                            _overlay_push("donation", u, platform="kick",
                                                          message=("Sub/Gift x%d" % cnt if cnt and cnt > 1 else "Sub/Gift"))
                                        if os.getenv("AZRAEL_THANK_OWN_GIFTS", "1") in ("1", "true"):
                                            _spawn(self._thank_own_gift(u, cnt, session),
                                                   name="kick-thank")
                                    except Exception as e:
                                        _loop_fehler("_ws_loop", e)
                            except Exception:
                                continue
                except Exception as e:
                    self.stats["connected"] = False
                    if self.running:
                        # v4.0-W116: war log.warning — im ERROR-Log stand nie
                        # etwas, auch wenn die Verbindung die ganze Nacht
                        # flatterte. Jetzt entscheidet der Verlauf.
                        _verbindung_verloren("Kick-WebSocket", e, 10,
                                             seit=self.stats.get("since", 0.0))
                        await asyncio.sleep(10)
        finally:
            self.stats["connected"] = False
            await session.close()

    async def _engage_loop(self):
        while self.running and self.cfg["engage_min"] > 0:
            await asyncio.sleep(self.cfg["engage_min"] * 60)
            if not (self.running and self.cfg["engage_min"] > 0):
                break
            _te0 = _time_mod.monotonic()
            text, err = await ai_chat(
                [{"role": "system", "content": "Schreibe EINE kurze, lockere Hype-/Info-Nachricht "
                  "für einen Kick-Livestream-Chat auf Deutsch. Max 1 Satz, kein Hashtag-Spam."},
                 {"role": "user", "content": "Engagement-Nachricht"}], timeout=30)
            _ai_telemetry("Kick-Engage", 24, len(text or ""),
                          int((_time_mod.monotonic() - _te0) * 1000), bool(text), err)
            if text and not err:
                await self.send_message(_nc_i18n.t(text.strip()))

    async def start(self):
        if self.running:
            return {"ok": True, "already": True}
        if not (KICK_CLIENT_ID and KICK_CLIENT_SECRET):
            return {"ok": False, "error": "KICK_CLIENT_ID/SECRET fehlen (Developer-App)"}
        self.running = True
        self._task = asyncio.create_task(self._ws_loop())
        self._engage_task = asyncio.create_task(self._engage_loop())
        log_event("kickmod.start", "info", "KI-Moderator gestartet", {})
        # Begrüßung in den Chat (optional)
        greet = (self.cfg.get("greeting") or "").strip()
        if greet:
            _spawn(self.send_message(_nc_i18n.t(greet)), name="mod-greet")
        return {"ok": True}

    async def stop(self):
        self.running = False
        for t in (self._task, self._engage_task):
            if t:
                t.cancel()
        self._task = self._engage_task = None
        self.stats["connected"] = False
        log_event("kickmod.stop", "info", "KI-Moderator gestoppt", {})
        return {"ok": True}


