def _loyalty_get(key):
    try:
        with db_conn() as conn:
            r = conn.execute("SELECT points FROM loyalty_points WHERE k=?", (key,)).fetchone()
        return int(r["points"]) if r else 0
    except Exception:
        return 0


def _loyalty_add(key, delta, name):
    """Punkte addieren (upsert), gibt die neue Summe zurueck."""
    try:
        now = datetime.now(timezone.utc).isoformat()
        with db_conn() as conn:
            conn.execute(
                "INSERT INTO loyalty_points (k, name, points, updated) VALUES (?,?,?,?) "
                "ON CONFLICT(k) DO UPDATE SET points=points+?, name=?, updated=?",
                (key, name, delta, now, delta, name, now))
            conn.commit()
            r = conn.execute("SELECT points FROM loyalty_points WHERE k=?", (key,)).fetchone()
        return int(r["points"]) if r else delta
    except Exception as e:
        log.debug("loyalty add: %s", e)
        return delta


def _loyalty_top(n):
    try:
        with db_conn() as conn:
            rows = conn.execute(
                "SELECT k, name, points FROM loyalty_points ORDER BY points DESC LIMIT ?",
                (n,)).fetchall()
        return [(r["k"], r["name"], int(r["points"])) for r in rows]
    except Exception:
        return []


