# v4.0-W90: STREAM-ARCHIV (Feature A) — dünne Anbindung an nc.intel.
# Schwerlogik liegt in nc/intel/{transcripts,library}.py; hier nur Adapter,
# Hintergrund-Indexer und Routen. Paramstyle folgt dem DB-Backend.
# ─────────────────────────────────────────────────────────────────────────────
_INTEL_PS = "format" if DB_BACKEND == "mariadb" else "qmark"
_INTEL_SCHEMA_READY = False


def _intel_ensure_schema():
    global _INTEL_SCHEMA_READY
    if _INTEL_SCHEMA_READY:
        return
    try:
        with db_conn() as c:
            _intel_tx.ensure_schema(c, _INTEL_PS)
        _INTEL_SCHEMA_READY = True
    except Exception as e:
        log.warning("Archiv-Schema konnte nicht angelegt werden: %s", e)


def _intel_semantic():
    """SemanticMemory-Instanz aus dem Brain (oder None, wenn Brain aus)."""
    try:
        from brain import get_brain
        return get_brain().semantic
    except Exception:
        return None


async def _intel_index_one(rid, path, username="", created_at=None):
    """Eine Aufnahme transkribieren + (falls Backend da) semantisch indizieren."""
    _intel_ensure_schema()
    segs = await _whisper_segments(path)
    with db_conn() as c:
        _intel_tx.save_segments(c, rid, segs, lang=WHISPER_LANG, paramstyle=_INTEL_PS)
        be = _intel_semantic()
        if be is not None:
            _intel_lib.index_recording(c, be, rid, username=username,
                                       created_at=created_at, paramstyle=_INTEL_PS)
    return len(segs)

# ═══ v4.0-W106/W107: Zerlegung — Routen als Blueprints registrieren ═══
#
# Die 34 /api/recordings- und /api/rec/-Routen liegen jetzt in
# nc/routes/recordings.py (siehe docs/MODULARISIERUNG.md). Hier bleibt nur die
# Registrierung — und die Verdrahtung dessen, was der Monolith weiterhin
# bereitstellen muss.
#
# Diese Stelle ist bewusst gewaehlt: sie liegt hinter der LETZTEN der
# injizierten Definitionen (_intel_index_one). Weiter oben — wo der Block in
# W106 noch stand — waeren die Intel-Helfer beim Aufruf noch nicht definiert;
# pyflakes meldete prompt 'undefined name'. Wer hier etwas ergaenzt, muss den
# Block gegebenenfalls WEITER nach unten schieben.


async def _intel_index_loop():
    """v4.0-W90: opt-in Hintergrund-Transkribierer. Nimmt pro Runde EINE noch
       nicht transkribierte Aufnahme (jüngste zuerst) und indiziert sie. Bewusst
       langsam/schonend — Whisper auf ganzen Aufnahmen ist teuer. Aus per
       ARCHIVE_INDEX_ENABLED=0."""
    if _nc_envnum.env_int("ARCHIVE_INDEX_ENABLED", 0) == 0:
        log.info("Stream-Archiv-Indexer aus (ARCHIVE_INDEX_ENABLED=1 zum Aktivieren)")
        return
    _intel_ensure_schema()
    interval = _nc_envnum.env_float("ARCHIVE_INDEX_INTERVAL_S", 120.0)
    log.info("Stream-Archiv-Indexer aktiv (alle %.0fs eine Aufnahme)", interval)
    while True:
        try:
            rows = get_all_recordings(limit=200)
            cand = [r["id"] for r in rows if r.get("id") and r.get("filepath")]
            with db_conn() as c:
                todo = _intel_tx.pending_ids(c, cand, _INTEL_PS)
            if todo:
                rid = todo[0]
                rec = next((r for r in rows if r["id"] == rid), None)
                if rec and rec.get("filepath") and os.path.exists(rec["filepath"]):
                    n = await _intel_index_one(rid, rec["filepath"],
                                               username=rec.get("username", ""),
                                               created_at=None)
                    log.info("Archiv: Aufnahme #%s transkribiert (%d Segmente)", rid, n)
                else:
                    with db_conn() as c:
                        _intel_tx.set_status(c, rid, _intel_tx.FAILED,
                                             error="Datei fehlt", paramstyle=_INTEL_PS)
        except Exception as e:
            # Vorher log.debug: faellt der Indexer aus (Whisper fehlt, DB-Lock,
            # Platte voll), transkribiert er nie wieder — und in einem ERROR-Log
            # steht dazu keine Zeile. Genau das Muster, das _loop_fehler abloest:
            # erste Meldung sofort mit Traceback, danach gedrosselt.
            _loop_fehler("_intel_index_loop", e)
        await asyncio.sleep(interval)








@dashboard_app.route("/healthz")
def healthz():
    """V37: Monitoring-Endpoint. 200 = Kern gesund, 503 = degradiert.
    Bewusst ohne Auth (keine sensiblen Daten, nur ok/degraded) — für
    UptimeRobot/Gatus/Kuma. Kriterien: Eventloop lebt (Heartbeats frisch),
    DB antwortet. Brain/LLM sind optional → nur informativ."""
    now = _time_mod.monotonic()
    hb_fresh = any(now - v < 600 for v in _HEARTBEATS.values()) or not _HEARTBEATS
    db_ok = True
    try:
        with db_conn() as conn:
            conn.execute("SELECT 1").fetchone()
    except Exception:
        db_ok = False
    brain_ok = None
    try:
        from brain import get_brain
        brain_ok = bool(get_brain().overview().get("tick_alive"))
    except Exception:
        pass
    ok = hb_fresh and db_ok
    _zomb = _zombie_child_count()                       # v4.0-W88
    return jsonify(ok=ok, db=db_ok, loops=hb_fresh, brain=brain_ok,
                   version=BUILD_STAMP,                  # v4.0-W88
                   uptime_s=_uptime_s(),                 # v4.0-W88
                   procs=len(active_processes),          # v4.0-W88: aktive Kindprozesse
                   zombies=_zomb,                        # v4.0-W88: defunkte Kinder (W75-Klasse)
                   loop_stalls=_LOOP_STALL_COUNT,        # v4.0-W88
                   ts=datetime.now(timezone.utc).isoformat()), (200 if ok else 503)


@dashboard_app.route("/api/debug/threads")
def api_debug_threads():
    """v4.0-W88: Thread-Übersicht für schnelle Ferndiagnose (authpflichtig).
       Zeigt lebende Threads nach Namens-Präfix gruppiert + Loop-Stall-Zähler +
       Zombie-Kinder — ohne sich per SSH einloggen zu müssen. Für einen echten
       Stack-Dump: SIGUSR1 (kill -USR1 <pid>) oder der Loop-Watchdog."""
    import threading as _th
    groups = {}
    for t in _th.enumerate():
        key = re.split(r"[-_0-9]", t.name or "?", maxsplit=1)[0] or "?"
        groups[key] = groups.get(key, 0) + 1
    return jsonify(ok=True,
                   total=_th.active_count(),
                   groups=dict(sorted(groups.items(), key=lambda kv: -kv[1])),
                   names=sorted(t.name for t in _th.enumerate()),
                   loop_stalls=_LOOP_STALL_COUNT,
                   procs=len(active_processes),
                   zombies=_zombie_child_count(),
                   uptime_s=_uptime_s())


