@dashboard_app.route("/api/azrael/persona", methods=["POST"])
def api_azrael_persona_set():
    """UPGRADE: setzt/loescht die AZRAEL-Persona fuer einen Streamer.
       Body {username, persona}; leere persona entfernt den Override."""
    d = request.get_json(silent=True) or {}
    user = (d.get("username") or "").strip().lstrip("@").lower()
    persona = (d.get("persona") or "").strip()
    if not user:
        return jsonify(ok=False, error="username fehlt"), 400
    try:
        m = _streamer_personas_load()
        if persona:
            m[user] = persona
        else:
            m.pop(user, None)
        _streamer_personas_save(m)
        return jsonify(ok=True, personas=m)
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 500


@dashboard_app.route("/api/azrael/transcript")
def api_azrael_transcript():
    """DASHBOARD: aktuelles Live-Transkript (was Whisper hoert), je User."""
    out = {u: buf[-20:] for u, buf in _LIVE_TRANSCRIPT.items()}
    return jsonify(ok=True, transcript=out)


@dashboard_app.route("/api/azrael/piper_status")
def api_azrael_piper_status():
    """DASHBOARD: Piper-TTS-Status (Binary, Engine, Stimm-Modell)."""
    model = (_OVERLAY.get("piper_model") or "").strip()
    mp = _resolve_piper_model(model)
    exists = bool(mp)
    return jsonify(ok=True, available=_piper_available(), bin=PIPER_BIN,
                   engine=(_OVERLAY.get("voice_engine") or "browser"),
                   voice_enabled=bool(_OVERLAY.get("voice_enabled")),
                   model=model, model_exists=exists, resolved=mp,
                   data_dir=PIPER_DATA_DIR, voice_dirs=PIPER_VOICE_DIRS)


WHISPER_PRESETS = ["tiny", "base", "small", "medium", "large-v3",
                   "tiny.en", "base.en", "small.en", "medium.en"]


@dashboard_app.route("/api/azrael/whisper_model", methods=["GET", "POST"])
def api_azrael_whisper_model():
    """DASHBOARD: Whisper-Modell lesen / zur Laufzeit umschalten.
       POST {model} -> setzt Namen + leert Cache (Reload beim naechsten Transkript)."""
    global _whisper_model, WHISPER_MODEL_NAME
    if request.method == "POST":
        d = request.get_json(silent=True) or {}
        m = (d.get("model") or "").strip()
        if not m:
            return jsonify(ok=False, error="model fehlt"), 400
        WHISPER_MODEL_NAME = m
        _whisper_model = None
        log.info("Whisper-Modell zur Laufzeit umgeschaltet -> %s", m)
        return jsonify(ok=True, model=WHISPER_MODEL_NAME, presets=WHISPER_PRESETS)
    return jsonify(ok=True, model=WHISPER_MODEL_NAME, presets=WHISPER_PRESETS,
                   loaded=bool(_whisper_model is not None),
                   available=_faster_whisper_available())


@dashboard_app.route("/api/kickmod/start", methods=["POST"])
def api_kickmod_start():
    try:
        res = _run_async_from_flask(_KICK_MOD.start(), timeout=15)
        return jsonify(res), (200 if res.get("ok") else 502)
    except RuntimeError:
        return jsonify(ok=False, error="Event-Loop nicht bereit"), 503
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 500


@dashboard_app.route("/api/kickmod/stop", methods=["POST"])
def api_kickmod_stop():
    try:
        res = _run_async_from_flask(_KICK_MOD.stop(), timeout=15)
        return jsonify(res)
    except RuntimeError as e:
        if _loop_not_ready(e):
            return jsonify(ok=False, error="Bot-Loop startet noch", transient=True), 503
        return jsonify(ok=False, error=str(e)), 500
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 500


@dashboard_app.route("/api/kickmod/say", methods=["POST"])
def api_kickmod_say():
    """Manuelle Nachricht über den Bot senden (Operator-Test)."""
    d = request.get_json(silent=True) or {}
    msg = (d.get("message") or "").strip()
    if not msg:
        return jsonify(ok=False, error="leere Nachricht"), 400
    try:
        ok, err = _run_async_from_flask(_KICK_MOD.send_message(_nc_i18n.t(msg)), timeout=20)
        return jsonify(ok=ok, error=err), (200 if ok else 502)
    except RuntimeError as e:
        if _loop_not_ready(e):
            return jsonify(ok=False, error="Bot-Loop startet noch", transient=True), 503
        return jsonify(ok=False, error=str(e)), 500
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 500


# ---- V37-MP: Kanal-Status ALLER eigenen Plattformen -------------------------
_CHST_CACHE = {"ts": 0.0, "data": None}


async def _twitch_channel_status():
    """Helix: live/Zuschauer/Kategorie/Titel + Follower.

    V37-TWFIX: Token-Quelle wie der EventSub-Loop — erst der OAuth-Flow
    (selbst-erneuernd), dann der manuelle TWITCH_EVENTSUB_TOKEN als Fallback.
    Diese Route hing vorher NUR am alten .env-Token und meldete deshalb
    fälschlich »Token nötig«, obwohl der OAuth-Flow längst verbunden war.
    """
    import aiohttp
    chan = (os.getenv("TWITCH_CHANNEL", "") or "").strip().lstrip("#").lower()
    cid = (os.getenv("TWITCH_CLIENT_ID", "") or "").strip()
    tok = None
    if _twoauth.status().get("ready"):
        tok = await _twoauth.access_token(aiohttp)
    if not tok:
        tok = (os.getenv("TWITCH_EVENTSUB_TOKEN", "") or "").strip()
        tok = tok[6:] if tok.lower().startswith("oauth:") else tok
    if not chan:
        return {"configured": False}
    out = {"configured": True, "url": f"https://twitch.tv/{chan}"}
    if not (cid and tok):
        out["error"] = ("Twitch nicht verbunden — im Dashboard „Twitch verbinden“ "
                        "klicken (oder TWITCH_CLIENT_ID + TWITCH_EVENTSUB_TOKEN setzen)")
        return out
    hdrs = {"Client-Id": cid, "Authorization": "Bearer " + tok}
    try:
        sess = await _get_ai_session()
        _to = aiohttp.ClientTimeout(total=10)
        async with sess.get("https://api.twitch.tv/helix/streams",
                            params={"user_login": chan}, headers=hdrs, timeout=_to) as r:
            if r.status in (401, 403):
                out["error"] = f"Token abgelehnt ({r.status})"
                return out
            j = await r.json(content_type=None)
        d = ((j or {}).get("data") or [])
        if d:
            out.update(is_live=True, viewers=d[0].get("viewer_count"),
                       category=d[0].get("game_name") or "", title=d[0].get("title") or "")
        else:
            out.update(is_live=False, viewers=0)
        async with sess.get("https://api.twitch.tv/helix/users",
                            params={"login": chan}, headers=hdrs, timeout=_to) as r:
            ju = await r.json(content_type=None)
        ud = ((ju or {}).get("data") or [])
        if ud:
            async with sess.get("https://api.twitch.tv/helix/channels/followers",
                                params={"broadcaster_id": ud[0]["id"], "first": "1"},
                                headers=hdrs, timeout=_to) as r:
                if r.status == 200:
                    jf = await r.json(content_type=None)
                    out["followers"] = (jf or {}).get("total")
    except Exception as e:
        out["error"] = str(e)[:120]
    return out


async def _youtube_api_status():
    """B120: YouTube-Kanalstatus ueber die Data API v3 — die Twitch-Parität.

    WARUM ueberhaupt: der bisherige Scrape der /live-Seite liefert die
    Abonnentenzahl nur als GERUNDETEN TEXT ("12,3 Tsd. Abonnenten") und
    die Zuschauerzahl nur, wenn YouTube sie gerade ins HTML rendert.
    Damit war das YouTube-Panel nicht mit dem Twitch-Panel (Helix:
    exakte viewer_count + followers total) vergleichbar.

    Der OAuth-Token existiert bereits — _yt_access_token() wird fuer den
    Chat-Versand ohnehin gehalten. Wir nutzen ihn hier mit:
      liveBroadcasts   -> laufender Stream, Titel, liveChatId
      videos           -> concurrentViewers (exakt, nicht gerundet)
      channels         -> subscriberCount + viewCount + videoCount

    QUOTA: liveBroadcasts kostet 1, videos 1, channels 1 Einheit — also
    3 pro Aufruf. Bei 10.000 Einheiten/Tag und dem 60s-Cache unten sind
    das ~4.300 Einheiten/Tag. Passt, aber deshalb der eigene Cache:
    ohne ihn wuerde der 20s-Poll des Control-Tabs das Kontingent bis
    Mittag verbrennen und die API sperrt dann bis Mitternacht.

    Rueckgabe None = keine OAuth-Konfiguration -> Aufrufer scrapet.
    """
    import aiohttp
    tok = await _yt_access_token()
    if not tok:
        return None
    now = _time_mod.monotonic()
    if _YT_API_CACHE["data"] and now - _YT_API_CACHE["ts"] < 60:
        return dict(_YT_API_CACHE["data"])
    out = {"configured": True, "source": "api"}
    hdrs = {"Authorization": f"Bearer {tok}"}
    _to = aiohttp.ClientTimeout(total=12)
    try:
        sess = await _get_ai_session()
        # 1) Laeuft gerade ein Broadcast?
        async with sess.get("https://www.googleapis.com/youtube/v3/liveBroadcasts",
                            params={"part": "snippet,status",
                                    "broadcastStatus": "active",
                                    "broadcastType": "all"},
                            headers=hdrs, timeout=_to) as r:
            if r.status in (401, 403):
                _YT_SEND["token_exp"] = 0        # Token erneuern lassen
                return {"configured": True, "source": "api",
                        "error": f"YouTube-Token abgelehnt ({r.status})"}
            jb = await r.json(content_type=None)
        items = (jb or {}).get("items") or []
        out["is_live"] = bool(items)
        vid = ""
        if items:
            sn = items[0].get("snippet") or {}
            out["title"] = sn.get("title") or ""
            vid = items[0].get("id") or ""
            _lcid = sn.get("liveChatId")
            if _lcid:                            # Chat-ID gleich mitnehmen
                _YT_SEND["live_chat_id"] = _lcid
                _YT_SEND["lcid_exp"] = _time_mod.time() + 300
        # 2) Exakte Zuschauerzahl (nur waehrend eines Livestreams vorhanden)
        if vid:
            async with sess.get("https://www.googleapis.com/youtube/v3/videos",
                                params={"part": "liveStreamingDetails",
                                        "id": vid},
                                headers=hdrs, timeout=_to) as r:
                jv = await r.json(content_type=None)
            vi = ((jv or {}).get("items") or [{}])[0]
            det = vi.get("liveStreamingDetails") or {}
            if det.get("concurrentViewers") is not None:
                try:
                    out["viewers"] = int(det["concurrentViewers"])
                except (TypeError, ValueError):
                    pass
            out["started_at"] = det.get("actualStartTime") or ""
        else:
            out["viewers"] = 0
        # 3) Abonnenten. hiddenSubscriberCount respektieren — sonst zeigt
        #    das Panel 0 statt "verborgen" und der Operator sucht den Fehler.
        async with sess.get("https://www.googleapis.com/youtube/v3/channels",
                            params={"part": "statistics,snippet", "mine": "true"},
                            headers=hdrs, timeout=_to) as r:
            jc = await r.json(content_type=None)
        ci = ((jc or {}).get("items") or [{}])[0]
        st = ci.get("statistics") or {}
        if st.get("hiddenSubscriberCount"):
            out["followers"] = None
            out["followers_hidden"] = True
        elif st.get("subscriberCount") is not None:
            try:
                out["followers"] = int(st["subscriberCount"])
            except (TypeError, ValueError):
                pass
        for k_api, k_out in (("viewCount", "total_views"),
                             ("videoCount", "video_count")):
            if st.get(k_api) is not None:
                try:
                    out[k_out] = int(st[k_api])
                except (TypeError, ValueError):
                    pass
        _cs = ci.get("snippet") or {}
        if _cs.get("customUrl"):
            out["url"] = "https://www.youtube.com/" + str(_cs["customUrl"]).lstrip("/")
        _YT_API_CACHE.update(ts=now, data=dict(out))
    except Exception as e:
        out["error"] = str(e)[:120]
    return out


async def _youtube_channel_status():
    """Kanalstatus: Data API wenn OAuth da ist, sonst Scrape der /live-Seite.

    B120: Die API ist der genaue Pfad (exakte Zuschauer + Abonnenten,
    Twitch-Parität). Der Scrape bleibt als keyloser Fallback erhalten —
    ohne OAuth soll die Kachel weiter etwas anzeigen statt leer zu sein.
    """
    import aiohttp
    yt = (os.getenv("YOUTUBE_CHANNEL", "") or "").strip()
    oauth = _yt_oauth_configured()
    # v4.0-W24b: YouTube taucht im Kanal-Status auf, sobald es IRGENDWIE in
    # Betrieb ist (Handle ODER Restream-Key ODER OAuth ODER aktiver Chat) —
    # vorher blieb die Karte ohne YOUTUBE_CHANNEL komplett unsichtbar, obwohl
    # der Kanal per Key/OAuth lief. Verhalten jetzt wie Twitch: zeigen + Status.
    if not (yt or YOUTUBE_ENABLED or YOUTUBE_STREAM_KEY or oauth or _YT_SEND.get("fn")):
        return {"configured": False}
    # 1) Data-API (braucht KEIN Handle) — exakte Zahlen, Twitch-Paritaet.
    try:
        api = await _youtube_api_status()
        if api and not api.get("error"):
            if yt:
                api.setdefault("url", f"https://www.youtube.com/"
                                      f"{yt if yt.startswith('@') else '@' + yt}")
            return api
        if api and api.get("error"):
            log.debug("YouTube-API-Status: %s — Fallback", api["error"])
    except Exception as e:
        log.debug("YouTube-API-Status: %s — Fallback", e)
    # 2) Ohne Handle koennen wir nicht scrapen/verlinken — Karte trotzdem ZEIGEN
    #    mit klarem, handlungsleitendem Status statt sie zu verstecken.
    if not yt:
        hint = ("OAuth verbunden, aber gerade kein aktiver Live-Broadcast — "
                "Zahlen erscheinen, sobald du live bist." if oauth
                else "YouTube läuft (Restream/Key), aber Titel/Kategorie/Chat/"
                     "Live-Zahlen brauchen OAuth — im Dashboard verbinden "
                     "(docs/SETUP_YT_OAUTH.md).")
        return {"configured": True, "source": "config", "url": None,
                "is_live": False, "error": hint}
    # 3) Handle vorhanden → Scrape der /live-Seite (keyloser Fallback).
    url = (yt if yt.startswith("http")
           else f"https://www.youtube.com/{yt if yt.startswith('@') else '@' + yt}/live")
    out = {"configured": True, "url": url, "source": "scrape"}
    try:
        sess = await _get_ai_session()
        async with sess.get(url, headers={"User-Agent": "Mozilla/5.0",
                                          "Accept-Language": "de,en;q=0.8"},
                            timeout=aiohttp.ClientTimeout(total=12)) as r:
            htmltxt = await r.text()
        live = ('"isLive":true' in htmltxt) or ('"isLiveNow":true' in htmltxt)
        out["is_live"] = bool(live)
        m = re.search(r'"viewCount":"(\d+)"[^}]*"isLive"', htmltxt) or \
            re.search(r'"originalViewCount":"(\d+)"', htmltxt) or \
            re.search(r'"viewCount":\{"videoViewCountRenderer":\{"viewCount":'
                      r'\{"runs":\[\{"text":"([\d.,\s]+)"', htmltxt)
        if m:
            try:
                out["viewers"] = int(re.sub(r"[^\d]", "", m.group(1)) or 0)
            except ValueError:
                pass
        t = re.search(r'"title":\{"simpleText":"([^"]{3,120})"', htmltxt)
        if t:
            out["title"] = t.group(1)
        s = re.search(r'"subscriberCountText":\{[^}]*"simpleText":"([^"]+)"', htmltxt)
        if s:
            out["followers_text"] = s.group(1)
    except Exception as e:
        out["error"] = str(e)[:120]
    return out


@dashboard_app.route("/api/channels/status")
def api_channels_status():
    """V37-MP: Kanal-Status aller eigenen Plattformen in EINEM Call —
       Kick (keyless API), Twitch (Helix), YouTube (Scrape). 20s-Cache, weil
       der Control-Tab regelmäßig pollt und Twitch/YouTube Rate-Limits haben."""
    now = _time_mod.monotonic()
    if _CHST_CACHE["data"] and now - _CHST_CACHE["ts"] < 20 and request.args.get("refresh") != "1":
        return jsonify(_CHST_CACHE["data"])

    async def _all():
        res = await asyncio.gather(
            _KICK_MOD.channel_info() if _KICK_MOD else asyncio.sleep(0, result=(None, "aus")),
            _twitch_channel_status(), _youtube_channel_status(),
            return_exceptions=True)
        k = res[0]
        if isinstance(k, tuple):
            info, err = k
            kick = ({"configured": True, "url": KICK_CHANNEL_URL or None, **(info or {})}
                    if not err else {"configured": bool(KICK_CHANNEL_URL), "error": str(err)[:120]})
        else:
            kick = {"configured": bool(KICK_CHANNEL_URL),
                    "error": str(k)[:120] if isinstance(k, Exception) else "aus"}
        return {"kick": kick,
                "twitch": res[1] if not isinstance(res[1], Exception) else {"configured": True, "error": str(res[1])[:120]},
                "youtube": res[2] if not isinstance(res[2], Exception) else {"configured": True, "error": str(res[2])[:120]}}

    try:
        # _run_async_from_flask liefert das Coroutine-Ergebnis DIREKT zurück —
        # NICHT (wert, fehler). api_kick_channel entpackt nur deshalb in zwei
        # Namen, weil channel_info() selbst ein 2-Tupel zurückgibt.
        data = _run_async_from_flask(_all(), timeout=25)
        out = {"ok": True, "platforms": data}
        _CHST_CACHE.update(ts=now, data=out)
        return jsonify(out)
    except RuntimeError as e:
        return jsonify(ok=False, error=str(e), transient=True), 503
    except Exception as e:
        log.warning("api_channels_status: %s", e)
        return jsonify(ok=False, error=str(e)), 500






# ===================== TITEL/KATEGORIE (Kick + Twitch + YouTube) =============
# B142: kuratierte Breit-Kategorien, die auf allen drei Plattformen einen
# sinnvollen Gegenwert haben. Kick/Twitch werden zur Laufzeit per Namenssuche
# aufgeloest (deren IDs aendern sich / sind nicht stabil hartcodierbar);
# YouTube nutzt die festen videoCategory-IDs. YouTube-Setzung greift erst,
# wenn OAuth verbunden ist (nur dann laesst sich der Broadcast anfassen).
# Erweitern: einfach eine Zeile ergaenzen. 'kick'/'twitch' sind Suchbegriffe,
# 'yt' ist die YouTube-Kategorie-ID.
_STREAM_CATEGORIES = [
    {"label": "Just Chatting",            "kick": "Just Chatting",            "twitch": "Just Chatting",            "yt": "22"},
    {"label": "IRL / Draußen",            "kick": "IRL",                      "twitch": "Travel & Outdoors",        "yt": "19"},
    {"label": "Music",                    "kick": "Music",                    "twitch": "Music",                    "yt": "10"},
    {"label": "Sports",                   "kick": "Sports",                   "twitch": "Sports",                   "yt": "17"},
    {"label": "ASMR",                     "kick": "ASMR",                     "twitch": "ASMR",                     "yt": "22"},
    {"label": "Pools, Hot Tubs & Beaches","kick": "Pools, Hot Tubs & Beaches","twitch": "Pools, Hot Tubs & Beaches","yt": "22"},
    {"label": "Food & Drink",             "kick": "Food & Drink",             "twitch": "Food & Drink",             "yt": "26"},
    {"label": "Special Events",           "kick": "Special Events",           "twitch": "Special Events",           "yt": "24"},
]


async def _youtube_set_channel(title, cat, yt_tok):
    """v4.0-W5: YouTube-Titel/Kategorie am aktiven Broadcast via Data API setzen —
       damit ist die Kanal-Steuerung auf ALLEN drei Plattformen komplett.
       Ablauf: liveBroadcasts.list → Video-ID; videos.list → aktuelles snippet;
       Titel + categoryId (cat['yt']) mergen; videos.update. (title & categoryId
       sind bei videos.update Pflicht → nicht geaenderte Werte bleiben erhalten.)"""
    import aiohttp
    hdr = {"Authorization": f"Bearer {yt_tok}"}
    try:
        sess = await _get_ai_session()
        # 1) aktiven Broadcast (== Video-ID) finden
        async with sess.get(_nc_ytapi.BROADCASTS_URL,
                            params=_nc_ytapi.active_broadcast_params(),
                            headers=hdr, timeout=aiohttp.ClientTimeout(total=15)) as r:
            bdata = await r.json(content_type=None)
        if r.status != 200:
            return (False, _nc_ytapi.parse_error(bdata) or f"HTTP {r.status}")
        vid = _nc_ytapi.parse_broadcast_id(bdata)
        if not vid:
            return (False, "kein aktiver YouTube-Broadcast (Stream offline?)")
        # 2) aktuelles Video-snippet holen (Pflichtfelder erhalten)
        async with sess.get(_nc_ytapi.VIDEOS_URL,
                            params=_nc_ytapi.video_list_params(vid),
                            headers=hdr, timeout=aiohttp.ClientTimeout(total=15)) as r:
            vdata = await r.json(content_type=None)
        if r.status != 200:
            return (False, _nc_ytapi.parse_error(vdata) or f"HTTP {r.status}")
        cur = _nc_ytapi.parse_video_snippet(vdata)
        if not cur:
            return (False, "YouTube-Video-Snippet nicht gefunden")
        # 3) Titel + Kategorie mergen und schreiben
        catid = cat.get("yt") if cat else None
        snip = _nc_ytapi.merge_video_snippet(cur, title=title, category_id=catid)
        async with sess.put(_nc_ytapi.VIDEOS_URL, params={"part": "snippet"},
                            json=_nc_ytapi.video_update_body(vid, snip),
                            headers=hdr, timeout=aiohttp.ClientTimeout(total=20)) as r:
            udata = await r.json(content_type=None)
        if r.status in (200, 201):
            return (True, "")
        return (False, _nc_ytapi.parse_error(udata) or f"HTTP {r.status}")
    except Exception as e:
        return (False, str(e)[:120])


async def _channel_set_all(title, cat):
    """B142: Titel und/oder Kategorie auf Kick + Twitch (+ YouTube nach OAuth)
       setzen. Jede Plattform unabhaengig — faellt eine aus, laufen die anderen
       trotzdem. Rueckgabe: {plattform: (ok, err)}."""
    out = {}
    # ---- KICK ----
    if _KICK_MOD:
        _kcat = None
        if cat:
            _kcat, _ = await _KICK_MOD.search_category(cat["kick"])
        out["kick"] = await _KICK_MOD.update_channel(title=title, category_id=_kcat)
    else:
        out["kick"] = (False, "Kick nicht konfiguriert")
    # ---- TWITCH ----
    try:
        _tw_connected = bool((_twoauth.status() or {}).get("connected"))
    except Exception:
        _tw_connected = False
    if _tw_connected:
        _gid = None
        if cat:
            _gid, _ = await _twoauth.search_category(aiohttp, cat["twitch"])
        out["twitch"] = await _twoauth.update_channel(aiohttp, title=title, game_id=_gid)
    else:
        out["twitch"] = (False, "Twitch nicht verbunden")
    # ---- YOUTUBE (nur nach OAuth) ----
    try:
        _yt_tok = await _ytoauth.access_token(aiohttp)
    except Exception:
        _yt_tok = None
    if _yt_tok:
        # OAuth da → Titel/Kategorie am aktiven/geplanten Broadcast setzen.
        out["youtube"] = await _youtube_set_channel(title, cat, _yt_tok)
    else:
        out["youtube"] = (False, "OAuth nicht verbunden")
    return out


@dashboard_app.route("/api/channel/categories")
def api_channel_categories():
    """B142: kuratierte Kategorie-Labels fuer das Dropdown."""
    return jsonify(ok=True, categories=[c["label"] for c in _STREAM_CATEGORIES])


@dashboard_app.route("/api/channel/set", methods=["POST"])
def api_channel_set():
    """B142: Titel + Kategorie plattformuebergreifend setzen (Kick + Twitch,
       YouTube nach OAuth). Body: {title?, category?} — category ist ein Label
       aus /api/channel/categories."""
    d = request.get_json(silent=True) or {}
    title = d.get("title")
    if title is not None:
        title = str(title).strip() or None
    label = (d.get("category") or "").strip()
    if title is None and not label:
        return jsonify(ok=False, error="Titel oder Kategorie nötig"), 400
    cat = None
    if label:
        cat = next((c for c in _STREAM_CATEGORIES if c["label"] == label), None)
        if not cat:
            return jsonify(ok=False, error=f"Unbekannte Kategorie: {label}"), 400
    try:
        res = _run_async_from_flask(_channel_set_all(title, cat), timeout=45)
        any_ok = any(v[0] for v in res.values())
        return jsonify(ok=any_ok,
                       results={k: {"ok": v[0], "error": v[1]} for k, v in res.items()})
    except RuntimeError as e:
        if _loop_not_ready(e):
            return jsonify(ok=False, error="Bot-Loop startet noch", transient=True), 503
        return jsonify(ok=False, error=str(e)), 500
    except Exception as e:
        log.warning("api_channel_set: %s", e)
        return jsonify(ok=False, error=str(e)), 500


# ===================== STREAM-OVERLAY (vor der Kamera) =====================
# Eine eigene Seite unter /overlay als OBS-Browser-Source: Sendername,
# Donations, letzter Follower, virtueller Moderator. Daten via /api/overlay/state.
_OVERLAY = {
    "title": os.getenv("OVERLAY_TITLE", "Azrael Sentinel").strip(),
    "goal_target": _env_int("DONATION_GOAL_TARGET", 0),
    "goal_label": os.getenv("DONATION_GOAL_LABEL", "Spendenziel").strip(),
    "goal_purpose": os.getenv("DONATION_GOAL_PURPOSE", "").strip(),  # Transparenz: wofür?
    "azrael_show": os.getenv("OVERLAY_AZRAEL", "1").strip().lower() in ("1", "true", "yes", "on"),
    # AZRAEL-Stimme (TTS via Web Speech API im Overlay → OBS Browser-Source-Audio).
    # voice_engine: "browser" = Web-Speech im Overlay-Browser (OS-Stimmen);
    #               "piper"   = server-seitige neuronale TTS (eigene deutsche Männer-
    #                           Stimmen, OS-unabhängig; Bot erzeugt & liefert die Audio aus).
    "voice_enabled": os.getenv("OVERLAY_VOICE", "0").strip().lower() in ("1", "true", "yes", "on"),
    "voice_engine": (os.getenv("OVERLAY_VOICE_ENGINE", "browser").strip().lower() or "browser"),
    "voice_lang": (os.getenv("OVERLAY_VOICE_LANG", "de-DE").strip() or "de-DE"),
    "voice_name": os.getenv("OVERLAY_VOICE_NAME", "").strip(),   # nur Browser-Engine
    "voice_rate": 1.0, "voice_pitch": 1.0, "voice_volume": 1.0,
    "piper_model": os.getenv("PIPER_MODEL", "").strip(),         # Pfad ODER Modellname (Piper)
    "piper_length": 1.0,                                          # Tempo (length-scale; >1 = langsamer)
    "voice_reactions": True,   # AZRAEL-Live-Reaktionen vorlesen
    "voice_mod": False,        # Moderations-/Chat-Antworten vorlesen
}

# ---- Piper TTS (server-seitige, OS-unabhängige Stimme) ----------------------
# Erzeugt aus Text eine WAV-Datei via Piper-CLI (neuronale TTS, CPU) und liefert
# sie unter /api/tts/<file> aus. Deutsche Männer-Stimmen z. B. de_DE-thorsten-medium,
# de_DE-karlsson-low, de_DE-pavoque-low (Modelle einmalig laden, s. .env.example).
# Untestbar in dieser Umgebung — Modelle müssen am Server liegen.
PIPER_BIN = os.getenv("PIPER_BIN", "piper").strip() or "piper"
PIPER_DATA_DIR = os.getenv("PIPER_DATA_DIR", os.path.join(RECORDINGS_DIR, "piper")).strip()

# Standard-Suchorte für Piper-Stimmmodelle. Henry legt die .onnx unter /opt/piper/voices
# ab → fest mit drin, plus PIPER_DATA_DIR und ein optionaler PIPER_VOICES_DIR-Override.
PIPER_VOICE_DIRS = [d for d in [
    os.getenv("PIPER_VOICES_DIR", "").strip(),
    PIPER_DATA_DIR,
    "/opt/piper/voices",
    "/opt/piper/voices/de", "/opt/piper/voices/en",
] if d]


_PIPER_VOICE_CACHE = {"ts": 0.0, "voices": []}


def _piper_voice_roots():
    """Alle Wurzeln, in denen nach Piper-Stimmen gesucht wird (B166: nc.piper_voices)."""
    return _nc_piper.voice_roots(
        PIPER_VOICE_DIRS, recordings_dir=RECORDINGS_DIR,
        module_dir=os.path.dirname(os.path.abspath(__file__)))


def _piper_list_voices(force=False):
    """Scannt alle Voice-Wurzeln REKURSIV nach .onnx-Stimmen (auch in Unterordnern).
       Returns [{name, path}], 60s gecacht. Das ist die 'direkt aus dem Verzeichnis'-Quelle."""
    now = _time_mod.time()
    if not force and _PIPER_VOICE_CACHE["voices"] and now - _PIPER_VOICE_CACHE["ts"] < 60:
        return _PIPER_VOICE_CACHE["voices"]
    found, seen = [], set()
    for root in _piper_voice_roots():
        try:
            if not (root and os.path.isdir(root)):
                continue
            for dirpath, _dirs, files in os.walk(root):
                for f in files:
                    if f.endswith(".onnx"):
                        p = os.path.abspath(os.path.join(dirpath, f))
                        if p not in seen:
                            seen.add(p)
                            found.append({"name": f[:-5], "path": p})
        except OSError:
            pass
    found.sort(key=lambda v: v["name"])
    _PIPER_VOICE_CACHE.update(ts=now, voices=found)
    return found


def _resolve_piper_model(model):
    """Löst Modellname/-pfad zur konkreten .onnx auf (absoluter Pfad) oder None.
       Probiert: exakter Pfad, dann REKURSIVE Suche in allen Voice-Wurzeln —
       exakter Name, exakter Dateiname, sonst Teilstring (case-insensitiv).
       So greift z.B. 'thorsten' auf 'de_DE-thorsten-medium.onnx' auch im Unterordner."""
    # B166: reine Auflöse-Logik in nc.piper_voices; das Scannen bleibt hier.
    return _nc_piper.resolve_model_path(model, _piper_list_voices())
_TTS_DIR = os.path.join(RECORDINGS_DIR, "tts")
_piper_warned = {"done": False}

def _piper_available():
    import shutil
    return bool(shutil.which(PIPER_BIN) or os.path.isfile(PIPER_BIN))

_piper_auto = {"model": None, "scanned": False}


def _piper_pick_model():
    """Absoluter .onnx-Pfad der zu nutzenden Stimme. Erst das konfigurierte Modell
       (_OVERLAY['piper_model'] / PIPER_MODEL); ist keins gesetzt/auffindbar, wird
       AUTOMATISCH die erste installierte Stimme in PIPER_VOICE_DIRS genommen.
       None + einmalige Warnung, wenn gar keine Stimme installiert ist."""
    model = (_OVERLAY.get("piper_model") or "").strip()
    if model:
        mp = _resolve_piper_model(model)
        if mp:
            return mp
        if not _piper_warned.get("model"):
            log.warning("Piper-Modell '%s' nicht gefunden (gesucht in: %s) — fällt auf "
                        "Auto-Stimme zurück.", model, ", ".join(PIPER_VOICE_DIRS))
            _piper_warned["model"] = True
    if not _piper_auto["scanned"]:
        _piper_auto["scanned"] = True
        vs = _piper_list_voices()
        if vs:
            _piper_auto["model"] = vs[0]["path"]
            log.info("Piper Auto-Stimme: %s (%d Stimmen gefunden, kein gültiges PIPER_MODEL).",
                     _piper_auto["model"], len(vs))
        elif not _piper_warned.get("nomodel"):
            log.warning("Keine Piper-Stimme (.onnx) gefunden in: %s — TTS bleibt stumm.",
                        ", ".join(_piper_voice_roots()))
            _piper_warned["nomodel"] = True
    return _piper_auto["model"]

def _tts_cleanup(keep=40):
    try:
        fs = sorted((os.path.join(_TTS_DIR, f) for f in os.listdir(_TTS_DIR) if f.endswith(".wav")),
                    key=os.path.getmtime)
        for f in fs[:-keep]:
            try: os.remove(f)
            except OSError: pass
    except OSError:
        pass

async def _piper_say(text, rate=None, source_user=None):
    """text → WAV via Piper; gibt Overlay-URL (/api/tts/..) zurück oder None.
       rate: F100-Regie-Faktor (>1 = schneller/hyped, <1 = ruhiger)."""
    import random as _rnd
    text = (text or "").strip()
    if not text:
        return None
    if not _piper_available():
        if not _piper_warned["done"]:
            log.warning("Piper-TTS nicht gefunden (PIPER_BIN=%s). `pip install piper-tts` "
                        "+ Stimm-Modell laden. Voice-Engine 'piper' bleibt inaktiv.", PIPER_BIN)
            _piper_warned["done"] = True
        return None
    mp = _piper_pick_model()                # konfiguriertes ODER auto-erkanntes .onnx
    if not mp:
        return None
    try:
        length = max(0.5, min(2.0, float(_OVERLAY.get("piper_length", 1.0))))
    except (TypeError, ValueError):
        length = 1.0
    if rate:                                # F100: höhere Energie → kürzere length-scale → schnellere Sprache
        length = max(0.5, min(2.0, length / max(0.6, min(1.4, float(rate)))))
    os.makedirs(_TTS_DIR, exist_ok=True)
    fn = f"az_{int(_time_mod.time()*1000)}_{_rnd.randint(100,999)}.wav"
    out = os.path.join(_TTS_DIR, fn)
    cmd = [PIPER_BIN, "-m", mp, "-f", out, "--length-scale", str(length)]
    # mp ist absoluter .onnx-Pfad → Piper findet die .onnx.json daneben, kein --data-dir nötig
    proc = None
    try:
        proc = await asyncio.create_subprocess_exec(
            *cmd, stdin=asyncio.subprocess.PIPE,
            stdout=asyncio.subprocess.DEVNULL, stderr=asyncio.subprocess.PIPE)
        _, err = await asyncio.wait_for(proc.communicate(text.encode("utf-8")), timeout=30)
        if proc.returncode != 0 or not os.path.exists(out):
            log.warning("Piper-TTS rc=%s: %s", proc.returncode,
                        (err or b"")[:200].decode("utf-8", "replace"))
            return None
        _tts_cleanup()
        await _restream_tts_enqueue_wav(out, source_user=source_user)   # AZRAEL-Stimme in den Restream-Ton (V37-P7b: pro Quelle routbar)
        return f"/api/tts/{fn}"
    except (asyncio.TimeoutError, OSError) as e:
        log.warning("Piper-TTS Fehler: %s", e)
        if proc:
            try:
                proc.kill()
                await proc.wait()        # reap -> kein Zombie-Piper-Prozess
            except Exception: pass
        return None


def _azrael_overlay_state():
    """Zustand des AZRAEL-Avatars fürs Overlay: an/aus, ob gerade eine Reaktion
       live ist (active), und der Reaktionstext. 'active' verfällt nach
       AZRAEL_REACTION_HOLD_S — der Avatar leuchtet nur kurz beim Reagieren auf."""
    if not _OVERLAY.get("azrael_show"):
        return {"show": False, "active": False, "text": "", "statement": ""}
    r = _AZRAEL_REACTION
    active = bool(r.get("text")) and (_time_mod.time() - r.get("ts", 0)) < AZRAEL_REACTION_HOLD_S
    return {"show": True, "active": active,
            # V37-B101: gekappt fürs Sendebild (Textwand vermeiden)
            "text": _ov_clip_text(r.get("text", "")) if active else "",
            "text_full": r.get("text", "") if active else "",
            "statement": _ov_clip_text(r.get("statement", ""), 120) if active else "",
            "audio": r.get("audio", "") if active else "",
            "source": r.get("source", "") if active else ""}

def _overlay_src_ok(src):
    """True wenn Events von 'src' (kick|tiktok) ins Overlay dürfen. Default 'kick' —
       beim Restream sitzt das Publikum auf Kick, TikTok-Gifts sind das fremde Publikum."""
    return OVERLAY_GIFT_SOURCE == "both" or OVERLAY_GIFT_SOURCE == src


_OV_PLATFORMS = ("kick", "twitch", "youtube", "tiktok")


# B120: EIN Gate fuer die Einnahmen-Herkunft.
#
# Fachliche Begruendung, warum TikTok hier NICHT dazugehoert: TikTok-Gifts
# gehen an den GETRACKTEN Streamer, nicht an unsere eigenen Kanaele. Sie
# sind fremdes Geld, das wir nur beim Mitschneiden vorbeifliegen sehen.
# Sie im Spenden-Panel, im Spendenziel oder gar in der Finanzamt-Auswertung
# mitzuzaehlen wuerde Einnahmen erfinden, die es nie gegeben hat.
#
# Vorher war TikTok nur in der ANZEIGE einer einzigen Route (
# /api/donations/summary) ausgeblendet — geschrieben wurde weiter, und
# /api/overlay/state sowie die Spendenziel-Summe zaehlten es mit.
# Deshalb jetzt EIN Konstantenpaar, an dem alle Stellen haengen.
REVENUE_PLATFORMS = ("kick", "twitch", "youtube", "manuell")
_REVENUE_SQL_IN = "('" + "','".join(REVENUE_PLATFORMS) + "')"

# B138-GELD: Die Abfragen lauteten frueher COALESCE(platform,'kick') IN (…).
# Damit wurde jede Zeile OHNE Plattform-Angabe stillschweigend zu Kick erklaert
# und als eigene Einnahme gezaehlt. Betroffen sind Altbestaende aus der Zeit vor
# der B120-Sperre, als TikTok-Gifts noch als 'donation' mit leerer Plattform
# geschrieben wurden — im Panel tauchten dann TikTok-Namen unter KICK auf und
# blaehten die Summe auf.
#
# Jetzt steht dort schlicht "platform IN (…)": NULL IN (…) ergibt NULL, also
# nicht TRUE, und die Zeile faellt heraus. "Herkunft unbekannt" ist eben KEINE
# Einnahme. Neue Eintraege sind nicht betroffen, _overlay_push setzt die
# Plattform immer.
#
# ERWARTETE FOLGE: die angezeigten Zahlen SINKEN. Das ist die Korrektur, kein
# Datenverlust — die Zeilen stehen unveraendert in overlay_events und lassen
# sich ueber /api/donations/unbekannt einsehen.




def is_revenue_platform(platform) -> bool:
    """Zaehlt Geld von dieser Plattform auf UNSERE Kanaele ein?"""
    return (platform or "").strip().lower() in REVENUE_PLATFORMS


def _overlay_push(kind, name, amount=None, message=None, platform="kick"):
    """Follower-/Donation-Event ins Overlay.
       V37-OVMP: platform sagt, WOHER das Event kam (kick|twitch|youtube|tiktok)
       — das Overlay zeigt Badges und rechnet Summen pro Plattform. Default
       'kick' hält alte Aufrufer kompatibel."""
    platform = (platform or "kick").strip().lower()
    if platform not in _OV_PLATFORMS:
        platform = "kick"
    # B120: TikTok-Gifts sind KEINE Spende an uns (siehe oben). Sie werden
    # gar nicht erst als 'donation' gespeichert — sonst taucht das Geld
    # frueher oder spaeter doch wieder in irgendeiner Summe auf.
    # Follows von TikTok bleiben erlaubt: die sind Reichweite, kein Geld.
    if kind == "donation" and not is_revenue_platform(platform):
        log.debug("Donation von %s verworfen — kein eigener Kanal (%s)",
                  platform, name)
        return
    try:
        with db_conn() as conn:
            conn.execute("INSERT INTO overlay_events (ts, kind, name, amount, message, platform) "
                         "VALUES (?,?,?,?,?,?)",
                         (datetime.now(timezone.utc).isoformat(), kind, (name or "?")[:120],
                          (str(amount)[:40] if amount is not None else None),
                          (message or "")[:500], platform))
            conn.commit()
    except Exception:
        pass
    globals()["_RESTREAM_LAST_EVENT"] = {
        "ts": _time_mod.monotonic(), "kind": kind, "name": (name or "?"),
        "amount": (str(amount) if amount is not None else ""),
        "message": (message or ""), "platform": platform}


@dashboard_app.route("/overlay")
def overlay_page():
    """Liefert die Overlay-Seite ROH (kein Jinja, da JS/CSS geschweifte Klammern enthält)."""
    for cand in (os.path.join(os.getcwd(), "templates", "overlay.html"),
                 os.path.join(os.getcwd(), "overlay.html")):
        if os.path.exists(cand):
            try:
                with open(cand, "r", encoding="utf-8") as f:
                    return Response(f.read(), mimetype="text/html")
            except Exception as e:
                return Response(f"overlay.html Lesefehler: {e}", status=500)
    return Response("<h1>overlay.html fehlt</h1><p>Lege <code>overlay.html</code> nach "
                    "<code>templates/</code> (neben dashboard.html).</p>", status=404,
                    mimetype="text/html")


# ═══ F92: Studio-Layout — Chat-Feed + Layout-Umschalter fürs Dashboard ═══
