@dashboard_app.route("/api/data/export")
def api_data_export():
    """Exportiert Daten als CSV oder JSON. ?kind=recordings|streamers|attempts&format=csv|json"""
    kind = (request.args.get("kind") or "recordings").lower()
    fmt = (request.args.get("format") or "json").lower()
    queries = {
        "recordings": ("SELECT id, username, created_at, file_size, duration_secs, rating, label "
                       "FROM recordings ORDER BY created_at DESC LIMIT 5000"),
        "streamers": ("SELECT id, username, created_at, last_live, paused FROM trackings "
                      "ORDER BY username LIMIT 5000"),
        "attempts": ("SELECT id, username, started_at, outcome, duration_secs, file_size "
                     "FROM recording_attempts ORDER BY started_at DESC LIMIT 5000"),
    }
    if kind not in queries:
        return jsonify(ok=False, error="kind: recordings|streamers|attempts"), 400
    try:
        with db_conn() as conn:
            rows = [dict(r) for r in conn.execute(queries[kind]).fetchall()]
        if fmt == "csv":
            import csv as _csv
            import io as _io
            buf = _io.StringIO()
            if rows:
                w = _csv.DictWriter(buf, fieldnames=list(rows[0].keys()))
                w.writeheader()
                w.writerows(rows)
            from flask import Response
            return Response(buf.getvalue(), mimetype="text/csv",
                            headers={"Content-Disposition": f"attachment; filename={kind}.csv"})
        return jsonify(ok=True, kind=kind, count=len(rows), rows=rows)
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 500














# F15: Sync-Helper für Flask-Routen (Dashboard-Backend)
# =============================================================================
# /health & /api/system laufen im Flask-Thread (sync), aber prüfen Redis/Ollama.
# Statt das Async-Setup hochzufahren benutzen wir stdlib socket + urllib —
# klein, schnell, blockiert nicht den asyncio-Loop.
# B4: socket / urllib / time-Imports wurden an den Anfang verschoben.
# -----------------------------------------------------------------------------

# F24: Probe-Cache (5s TTL). Redis/Ollama-Status muss nicht alle 200ms neu
# erfragt werden — bei nicht-laufenden Services kostet jede Socket-Connection
# 1-2 Sekunden Timeout. Cache reduziert das auf vernachlässigbar.
_PROBE_CACHE = {}     # key -> (value, expires_at)
_PROBE_TTL = 5.0

def _cached_probe(key, fn, *args, **kwargs):
    now = _time_mod.monotonic()
    cached = _PROBE_CACHE.get(key)
    if cached and cached[1] > now:
        return cached[0]
    val = fn(*args, **kwargs)
    _PROBE_CACHE[key] = (val, now + _PROBE_TTL)
    return val

def _check_redis_alive_sync(timeout: float = 1.0) -> bool:
    """RAW-TCP-Ping an Redis. Sendet PING und prüft +PONG."""
    def _probe():
        try:
            u = _urlparse(REDIS_URL)
            host = u.hostname or "localhost"
            port = u.port or 6379
            with _socket.create_connection((host, port), timeout=timeout) as sock:
                sock.sendall(b"*1\r\n$4\r\nPING\r\n")
                data = sock.recv(64)
                return b"PONG" in data
        except Exception:
            return False
    return _cached_probe("redis_alive", _probe)

def _check_redis_version_sync(timeout: float = 1.0):
    """INFO server → redis_version. None bei Fehler."""
    def _probe():
        try:
            u = _urlparse(REDIS_URL)
            host = u.hostname or "localhost"
            port = u.port or 6379
            with _socket.create_connection((host, port), timeout=timeout) as sock:
                sock.sendall(b"*2\r\n$4\r\nINFO\r\n$6\r\nserver\r\n")
                data = b""
                while b"\r\n\r\n" not in data and len(data) < 8192:
                    chunk = sock.recv(4096)
                    if not chunk: break
                    data += chunk
            for line in data.decode("utf-8", errors="ignore").splitlines():
                if line.startswith("redis_version:"):
                    return line.split(":", 1)[1].strip()
        except Exception:
            pass
        return None
    return _cached_probe("redis_version", _probe)



def _active_recorder_sync() -> Optional[str]:
    """Wie build_recording_cmd's Auswahl-Logik aber ohne Auflösung.
       F43: streamlink raus."""
    has_ffmpeg = bool(shutil.which("ffmpeg"))
    has_ytdlp  = bool(shutil.which("yt-dlp") or shutil.which("yt_dlp"))
    pref = RECORDER_PREF
    if pref == "native": return "native" if has_ffmpeg else None
    if pref == "ytdlp":  return "ytdlp"  if has_ytdlp  else None
    if has_ffmpeg: return "native"
    if has_ytdlp:  return "ytdlp"
    return None

def _ai_calls_total_sync() -> int:
    """Liest ai_calls_total via raw Redis-RESP. 0 wenn Redis nicht da."""
    try:
        u = _urlparse(REDIS_URL)
        host = u.hostname or "localhost"
        port = u.port or 6379
        with _socket.create_connection((host, port), timeout=1.0) as sock:
            sock.sendall(b"*2\r\n$3\r\nGET\r\n$15\r\nai_calls_total\r\n")
            data = sock.recv(128).decode("utf-8", errors="ignore")
        if data.startswith("$-1"):
            return 0
        if data.startswith("$"):
            parts = data.split("\r\n", 2)
            if len(parts) >= 2:
                try: return int(parts[1])
                except ValueError: pass
    except Exception:
        pass
    return 0

