# ==================== DEFENSE — Server-Angriffe & CrowdSec ====================
# Zeigt Angriffe (fehlgeschlagene SSH-Logins) + die fail2ban-Banliste, geo-lokalisiert
# für eine Weltkarte. Liest Server-Logs/fail2ban; wo dem Bot-User Rechte fehlen, wird
# 'sudo -n' versucht und sonst ein klarer Hinweis zurückgegeben (kein Crash).
DEFENSE_SERVER_LAT = _nc_envnum.env_float("DEFENSE_SERVER_LAT", 50.69)   # OVH Gravelines, FR; v4.0-W82: leere .env robust
DEFENSE_SERVER_LON = _nc_envnum.env_float("DEFENSE_SERVER_LON", 2.13)   # v4.0-W82: leere .env robust
# B132: fail2ban laeuft auf diesem Server nicht mehr — ersetzt durch CrowdSec.
# Der alte Aufruf blieb im Code stehen und lieferte dauerhaft "nicht
# erreichbar": leere Bannliste, leere Weltkarte, ohne dass irgendwo stand warum.
def _cscli_bin():
    """Absoluter cscli-Pfad. Wichtig fuer sudoers: eine Regel wie
       'NOPASSWD: /usr/bin/cscli' matcht nur, wenn sudo GENAU diesen Pfad
       aufruft. Liegt cscli in /usr/local/bin (haeufig bei CrowdSec), scheiterte
       'sudo -n cscli' bisher stumm → Passwortabfrage → Panic vom rechtelosen
       Direktaufruf. Deshalb den echten Pfad ermitteln und ueberall nutzen.

       B138: Rueckgabe None statt des Platzhalters "cscli". Mit dem Platzhalter
       lief 'sudo -n cscli' los, sudo antwortete 'sudo: cscli: command not
       found', und die Fehlerzuordnung sah darin wegen des Praefix 'sudo:' ein
       fehlendes Recht — der Betreiber befolgte eine sudoers-Anleitung fuer ein
       Programm, das es auf dem Server gar nicht gibt."""
    # v4.0-W60: Auflösung nach nc/binresolve.py (which zuerst, dann Kandidaten,
    # sonst None — which/exists injiziert, gegen Mocks bewiesen).
    return _nc_binresolve.resolve(
        "cscli",
        ("/usr/bin/cscli", "/usr/local/bin/cscli", "/usr/sbin/cscli",
         "/usr/local/sbin/cscli"),
        shutil.which, os.path.exists)

_CSCLI_CACHE = [None]      # gefundener Pfad; solange None wird neu gesucht
_DEFENSE_GEO_ERR = ""      # letzter Fehler der Geo-Aufloesung, fuer das Panel


def _cscli_path():
    """Pfad zur Laufzeit ermitteln statt beim Import einzufrieren.

       B138: vorher stand das Ergebnis in der Modul-Konstante _CSCLI. Wer
       CrowdSec nachinstalliert hatte, bekam bis zum naechsten Bot-Neustart
       weiter 'cscli nicht gefunden'. Ein Fund wird gemerkt, ein Fehlschlag
       nicht — nur so wirkt eine Nachinstallation sofort, und shutil.which plus
       vier os.path.exists sind pro Panel-Aufruf billig genug."""
    if _CSCLI_CACHE[0]:
        return _CSCLI_CACHE[0]
    p = _cscli_bin()
    if p:
        _CSCLI_CACHE[0] = p
    return p


def _f2b_sudo_hint():
    """Hinweis mit dem ECHTEN Pfad. sudoers verlangt einen absoluten Pfad — der
       frueher eingebaute Platzhalter 'cscli' haette eine Regel ergeben, die
       sudo stillschweigend nie anwendet."""
    p = _cscli_path() or "/usr/bin/cscli"
    return ("CrowdSec nicht abfragbar: dem Bot-User (ubuntu) passwortlosen Zugriff geben — "
            f"/etc/sudoers.d/nightcrawler: 'ubuntu ALL=(root) NOPASSWD: {p}' "
            "(Pfad muss exakt stimmen), danach prüfen: sudo systemctl status crowdsec")


_AUTHLOG_HINT = ("Auth-Log nicht lesbar: Bot-User in die Gruppen 'adm' und 'systemd-journal' "
                 "aufnehmen und den Dienst neu starten — Gruppenrechte greifen erst im neuen "
                 "Prozess, ein blosses 'usermod' ohne Neustart aendert nichts.")


def _darf_journal_lesen():
    """Darf dieser Prozess Auth-Logs/Journal ueberhaupt lesen?

       Braucht es, weil journalctl ohne Gruppenrecht mit rc=0 und
       '-- No entries --' antwortet: Erfolg im Rueckgabecode, Leere im Inhalt.
       Ohne diese Pruefung ist 'niemand greift an' nicht von 'ich darf nicht
       hinsehen' zu unterscheiden — genau das leere Panel."""
    try:
        import grp
        def _gid_of(name):
            try:
                return grp.getgrnam(name).gr_gid
            except KeyError:
                return None
        # v4.0-W62b: Entscheidung nach nc/journalperm.py (Werte injiziert, bewiesen).
        return _nc_journalperm.may_read(set(os.getgroups()), _gid_of, os.geteuid())
    except Exception:
        return True   # Nicht-Linux/unklar: lieber nicht faelschlich Alarm schlagen


def _is_private_ip(ip):
    try:
        import ipaddress
        a = ipaddress.ip_address(ip)
        return a.is_private or a.is_loopback or a.is_link_local or a.is_reserved
    except Exception:
        return ip.startswith(("10.", "192.168.", "127.", "169.254.", "172.1", "172.2", "172.3"))


def _run_priv(args, timeout=6, sudo_first=False):
    # v4.0-W26: verbatim nach nc/sysrun.py extrahiert (bitgenau geprüft, inkl.
    # Aufrufreihenfolge und Fehlercodes 124/127).
    return _nc_sysrun.run_priv(args, timeout=timeout, sudo_first=sudo_first)


def _geo_lookup_ips(ips):
    """Geolokalisiert IPs für die Defense-Karte (gleicher Cache + ip-api-Batch wie die
       Proxy-Globe). Private/lokale IPs werden übersprungen. Returns {ip:{lat,lon,country,cc,city}}."""
    import urllib.request, json as _json
    global _DEFENSE_GEO_ERR
    _DEFENSE_GEO_ERR = ""
    out, unknown = {}, []
    for ip in {i for i in ips if i}:
        if _is_private_ip(ip):
            continue
        with _PROXY_GEO_LOCK:
            c = _PROXY_GEO_CACHE.get(ip)
        if c and c.get("lat") is not None:
            out[ip] = c
        else:
            unknown.append(ip)
    if unknown:
        pub = unknown[:100]
        try:
            body = _json.dumps([{"query": ip,
                                 "fields": "status,lat,lon,country,countryCode,city,query"}
                                for ip in pub]).encode()
            req = urllib.request.Request("http://ip-api.com/batch", data=body,
                                         headers={"Content-Type": "application/json",
                                                  "User-Agent": "nc-defense/1"})
            with urllib.request.urlopen(req, timeout=8) as r:
                arr = _json.loads(r.read().decode())
            for item in arr or []:
                if item.get("status") == "success":
                    ip = item.get("query")
                    g = {"lat": item.get("lat"), "lon": item.get("lon"),
                         "country": item.get("country"), "cc": item.get("countryCode"),
                         "city": item.get("city")}
                    with _PROXY_GEO_LOCK:
                        _PROXY_GEO_CACHE[ip] = g
                    out[ip] = g
        except Exception as e:
            # B138: war log.debug — in einem ERROR-Log unsichtbar. Fiel ip-api
            # aus (Rate-Limit 45/min oder ausgehender Port 80 zu), blieben
            # TOP-LÄNDER und Weltkarte leer und niemand erfuhr warum.
            _DEFENSE_GEO_ERR = str(e)[:160]
            log.warning("Abwehr: Geo-Auflösung (ip-api) fehlgeschlagen: %s", e)
    return out


def _crowdsec_via_lapi():
    """v4.0-W18: Sperrliste ueber die CrowdSec-LAPI mit einem Bouncer-Schluessel.
       Braucht KEIN Root (der cscli-Weg schon — daher die sudoers-Regel). Gibt
       None zurueck, wenn kein Schluessel gesetzt ist -> Aufrufer nimmt cscli."""
    if not CROWDSEC_BOUNCER_KEY:
        return None
    import json as _json
    import urllib.error
    import urllib.request
    url = _nc_crowdsec.decisions_url(CROWDSEC_LAPI_URL, CROWDSEC_LAPI_HOST,
                                     CROWDSEC_LAPI_PORT)
    req = urllib.request.Request(url, headers=_nc_crowdsec.headers(CROWDSEC_BOUNCER_KEY))
    try:
        with urllib.request.urlopen(req, timeout=6) as r:      # noqa: S310 (feste URL)
            raw = r.read().decode("utf-8", "replace")
        data = _json.loads(raw) if raw.strip() else []
    except urllib.error.HTTPError as e:
        status, hint, fix = _nc_crowdsec.explain_status(e.code)
        # v4.1-W12: gedrosselt UND mit Abhilfe. Vorher stand hier 109 Mal in
        # dreieinhalb Stunden dieselbe Zeile "CrowdSec-LAPI HTTP 403" — der
        # Dashboard-Takt ruft diesen Weg alle zwei Minuten auf, und ein 403
        # ist ein DAUERZUSTAND (Schluessel nicht registriert), kein Ereignis.
        # Was dabei fehlte, war ausgerechnet das Wichtige: hint und fix gingen
        # nur an die API zurueck, nie ins Log. Wer den Log las, sah 109 Mal
        # eine Zahl und nie, was zu tun ist. Jetzt: beim ersten Mal und danach
        # hoechstens alle 15 Minuten, dafuer mit Grund und Abhilfe.
        _st = globals().setdefault("_CROWDSEC_LOG_STATE", {})
        _now = _time_mod.time()
        _prev = _st.get(e.code) or {"ts": 0.0, "n": 0}
        _prev["n"] += 1
        if _now - _prev["ts"] >= 900:
            _sup = _prev["n"] - 1
            log.warning("Abwehr: CrowdSec-LAPI HTTP %s — %s Abhilfe: %s%s",
                        e.code, hint, fix,
                        (f" (×{_sup} unterdrueckt seit der letzten Meldung)"
                         if _sup > 0 else ""))
            _prev["ts"] = _now
            _prev["n"] = 0
        _st[e.code] = _prev
        return {"ok": False, "status": status, "error": f"HTTP {e.code}",
                "hint": hint, "fix": fix, "jails": [], "total_banned": 0,
                "engine": "crowdsec", "via": "lapi"}
    except Exception as e:
        return {"ok": False, "status": "lapi_tot", "error": str(e)[:160],
                "hint": (f"CrowdSec-LAPI ({CROWDSEC_LAPI_HOST}:{CROWDSEC_LAPI_PORT}) "
                         "nicht erreichbar."),
                "fix": "sudo systemctl restart crowdsec && sudo cscli lapi status",
                "jails": [], "total_banned": 0, "engine": "crowdsec", "via": "lapi"}
    jails, total = _nc_crowdsec.parse_decisions(data)
    return {"ok": True, "status": ("ok" if total else "leer"), "via_sudo": False,
            "engine": "crowdsec", "via": "lapi", "jails": jails,
            "total_banned": total}


def _crowdsec_status():
    """B132: Bannliste aus CrowdSec statt fail2ban.

    CrowdSec ist hier nicht nur das Vorhandene, sondern der bessere Partner:
    `cscli -o json` liefert strukturierte Daten. Das alte fail2ban-Modul
    parste Freitext ("Jail list:", "Currently banned:") — bei jeder
    Formataenderung ein stiller Ausfall.

    Die Rueckgabeform bleibt bewusst identisch (jails / total_banned), damit
    Weltkarte und alle Aufrufer unveraendert weiterlaufen. Eine CrowdSec-
    Entscheidung wird auf das Jail-Modell abgebildet: 'jail' ist die Herkunft
    (crowdsec, cscli, CAPI), 'ips' sind die gesperrten Adressen.
    """
    # W18: wenn ein Bouncer-Schluessel hinterlegt ist, ueber die LAPI gehen —
    # kein Root noetig. Nur wenn das fehlschlaegt/fehlt, der alte cscli-Weg.
    _lapi = _crowdsec_via_lapi()
    if _lapi is not None and _lapi.get("ok"):
        return _lapi
    import json as _json
    cscli = _cscli_path()
    if not cscli:
        # B138: zuerst pruefen, OB es das Programm gibt. sudo meldet ein
        # fehlendes Programm mit einer Zeile, die mit 'sudo:' beginnt — die
        # Zuordnung unten hat das bisher als fehlendes Recht gedeutet und den
        # Betreiber in eine sudoers-Datei geschickt, die nichts repariert.
        log.warning("Abwehr: cscli nicht gefunden — weder im PATH noch in /usr/bin, "
                    "/usr/local/bin, /usr/sbin, /usr/local/sbin")
        return {"ok": False, "status": "fehlt",
                "error": "cscli nicht gefunden",
                "hint": "CrowdSec ist auf diesem Server nicht installiert — "
                        "es fehlt also nicht das Recht, sondern das Programm.",
                "fix": "sudo apt install crowdsec && sudo systemctl enable --now crowdsec",
                "jails": [], "total_banned": 0, "engine": "crowdsec"}
    rc, out, err, sudo = _run_priv([cscli, "decisions", "list", "-o", "json"],
                                   sudo_first=True)
    if rc != 0:
        e = ((err or out or "").strip())
        el = e.lower()
        if rc == 124 or "zeitüberschreitung" in el or "timed out" in el:
            status = "timeout"
            hint = "cscli antwortet nicht innerhalb des Zeitlimits — haengt die LAPI?"
            fix = "sudo systemctl restart crowdsec && sudo cscli lapi status"
        elif ("password is required" in el or "a terminal is required" in el
              or el.startswith("sudo:")):
            status = "kein_sudo"
            hint = _f2b_sudo_hint()
            fix = (f"echo 'ubuntu ALL=(root) NOPASSWD: {cscli}' | sudo tee "
                   "/etc/sudoers.d/nightcrawler && sudo systemctl restart tiktok-bot")
        elif ("connection refused" in el or f":{CROWDSEC_LAPI_PORT}" in el
              or ":8080" in el or "panic" in el
              or "nil pointer" in el or "unable to list decisions" in el
              or "dial tcp" in el):
            status = "lapi_tot"
            # W17: Port ist konfigurierbar (Henry faehrt die LAPI auf 8083) —
            # ein fest verdrahtetes 8080 im Hinweis schickt den Betreiber sonst
            # auf die falsche Faehrte.
            hint = (f"CrowdSec-Dienst/LAPI ({CROWDSEC_LAPI_HOST}:{CROWDSEC_LAPI_PORT}) "
                    "antwortet nicht.")
            fix = "sudo systemctl restart crowdsec && sudo cscli lapi status"
        else:
            status = "fehler"
            hint = _f2b_sudo_hint()
            fix = f"sudo -n {cscli} decisions list -o json"
        # log.warning statt stillem Verschlucken: ein leeres Abwehr-Panel war
        # bisher im journalctl nicht wiederzufinden.
        log.warning("Abwehr: cscli rc=%s status=%s: %s", rc, status, e[:200])
        return {"ok": False, "status": status,
                "error": (e or "cscli nicht erreichbar")[:300],
                "hint": hint, "fix": fix, "jails": [], "total_banned": 0,
                "engine": "crowdsec"}
    try:
        data = _json.loads(out or "null")
    except ValueError:
        log.warning("Abwehr: cscli lieferte kein JSON (%d Zeichen Ausgabe)", len(out or ""))
        return {"ok": False, "status": "json_kaputt",
                "error": "cscli lieferte kein gueltiges JSON",
                "hint": "Das Ausgabeformat hat sich geaendert oder eine Warnung stand vor dem JSON.",
                "fix": f"{cscli} decisions list -o json | head -c 400",
                "jails": [], "total_banned": 0, "engine": "crowdsec"}
    # Ohne Entscheidungen gibt cscli 'null' aus, nicht '[]'. Das ist ein
    # Erfolg, kein Fehler — dann ist schlicht niemand gesperrt.
    rows = data or []
    by_origin, total = {}, 0
    for d in rows:
        # Je nach cscli-Version flach oder unter 'decisions' geschachtelt.
        # Beides akzeptieren, statt sich auf eine Variante zu verlassen.
        for dec in (d.get("decisions") or [d]):
            ip = (dec.get("value") or "").strip()
            if not ip:
                continue
            origin = (dec.get("origin") or "crowdsec").strip()
            e = by_origin.setdefault(origin, {"jail": origin, "ips": [],
                                              "banned_now": 0,
                                              "banned_total": None,
                                              "scenarios": {}})
            if ip not in e["ips"]:
                e["ips"].append(ip)
                e["banned_now"] += 1
                total += 1
            sc = (dec.get("scenario") or "").split("/")[-1]
            if sc:
                e["scenarios"][sc] = e["scenarios"].get(sc, 0) + 1
    # B138: 'leer' ist ein Erfolgszustand — cscli hat geantwortet, es ist nur
    # niemand gesperrt. Das Frontend muss das vom Rechteproblem trennen koennen.
    return {"ok": True, "status": ("ok" if total else "leer"), "via_sudo": sudo,
            "engine": "crowdsec", "cscli": cscli,
            "jails": list(by_origin.values()), "total_banned": total}


# Alter Name bleibt als Verweis: zwei Aufrufer haengen daran, und ein stiller
# Namenswechsel waere genau die Art Bruch, die wir gerade beheben.
_fail2ban_status = _crowdsec_status


def _parse_ssh_attacks(limit=300):
    """Aggregiert fehlgeschlagene SSH-Logins (Angriffe) pro IP aus auth.log/secure,
       Fallback journalctl bzw. sudo. Returns {ok, attacks:[{ip,count,last,users}], ...}."""
    # B138: die Ursache wird festgehalten statt weggeworfen. Vorher verschluckte
    # 'except (PermissionError, FileNotFoundError, OSError): continue' beide
    # Faelle gleich, und journalctl antwortet ohne Gruppenrecht mit rc=0 und
    # '-- No entries --' — das Panel meldete dann 'Keine Angriffe protokolliert',
    # obwohl es nichts lesen durfte. Auf Ubuntu 24.04 gibt es /var/log/auth.log
    # gar nicht mehr, damit war das der Normalfall, nicht der Ausnahmefall.
    text, source, denied = "", None, False
    for p in ("/var/log/auth.log", "/var/log/auth.log.1", "/var/log/secure"):
        if not os.path.exists(p):
            continue
        try:
            with open(p, "r", errors="ignore") as f:
                text += f.read()
                source = p
        except PermissionError:
            denied = True
        except OSError as ex:
            log.warning("Abwehr: %s existiert, ist aber nicht lesbar: %s", p, ex)
    if not text:
        rc, out, _e, sudo = _run_priv(["journalctl", "-u", "ssh", "-u", "sshd",
                                       "--no-pager", "-n", "8000"], timeout=8)
        leer = (rc == 0 and "no entries" in (out or "").strip().lower())
        if rc == 0 and out and not leer:
            text, source = out, "journalctl" + ("+sudo" if sudo else "")
        elif leer and _darf_journal_lesen():
            # Wir duerfen lesen und es steht wirklich nichts drin: der gute Fall.
            return {"ok": True, "status": "leer", "source": "journalctl",
                    "attacks": [], "total": 0, "unique_ips": 0}
        else:
            denied = True
    if not text:
        rc, out, _e, sudo = _run_priv(["cat", "/var/log/auth.log"], timeout=8)
        if rc == 0 and out:
            text, source = out, "auth.log+sudo"
        else:
            denied = True
    if not text:
        status = "keine_rechte" if denied else "keine_logs"
        log.warning("Abwehr: kein Auth-Log lesbar (status=%s)", status)
        return {"ok": False, "status": status,
                "error": ("Auth-Log vorhanden, aber nicht lesbar" if status == "keine_rechte"
                          else "kein Auth-Log und kein Journal-Eintrag gefunden"),
                "hint": (_AUTHLOG_HINT if status == "keine_rechte" else
                         "Weder /var/log/auth.log noch das Journal liefern SSH-Zeilen — "
                         "laeuft auf diesem Server ueberhaupt ein sshd?"),
                "fix": ("sudo usermod -aG adm,systemd-journal ubuntu && "
                        "sudo systemctl restart tiktok-bot"
                        if status == "keine_rechte" else "systemctl status ssh"),
                "attacks": [], "total": 0, "unique_ips": 0}
    agg = {}
    pat_fail = re.compile(r"Failed password for (?:invalid user )?(\S+) from (\d{1,3}(?:\.\d{1,3}){3})")
    pat_inv = re.compile(r"Invalid user (\S+) from (\d{1,3}(?:\.\d{1,3}){3})")
    pat_ip = re.compile(r"from (\d{1,3}(?:\.\d{1,3}){3})")
    for line in text.splitlines():
        if not ("Failed password" in line or "Invalid user" in line
                or "authentication failure" in line or "Connection closed by authenticating" in line):
            continue
        mm = pat_fail.search(line) or pat_inv.search(line)
        if mm:
            user, ip = mm.group(1), mm.group(2)
        else:
            ipm = pat_ip.search(line)
            if not ipm:
                continue
            user, ip = "?", ipm.group(1)
        if _is_private_ip(ip):
            continue
        d = agg.setdefault(ip, {"ip": ip, "count": 0, "last": line[:15], "users": set()})
        d["count"] += 1
        d["last"] = line[:15]
        if user and user != "?":
            d["users"].add(user)
    attacks = sorted(agg.values(), key=lambda x: x["count"], reverse=True)[:limit]
    for a in attacks:
        a["users"] = sorted(a["users"])[:6]
    return {"ok": True, "status": ("ok" if agg else "leer"), "source": source,
            "attacks": attacks, "total": sum(a["count"] for a in agg.values()),
            "unique_ips": len(agg)}


@dashboard_app.route("/api/defense/overview")
def api_defense_overview():
    try:
        f2b = _fail2ban_status()
        atk = _parse_ssh_attacks(limit=250)
        top_ips = [a["ip"] for a in atk.get("attacks", [])[:60]]
        geo = _geo_lookup_ips(top_ips) if top_ips else {}
        by_country = {}
        for a in atk.get("attacks", []):
            g = geo.get(a["ip"])
            if g and g.get("country"):
                by_country[g["country"]] = by_country.get(g["country"], 0) + a["count"]
        top_countries = sorted(by_country.items(), key=lambda x: x[1], reverse=True)[:8]
        # B138: status + fix mitliefern. Ohne sie kann das Panel "nichts
        # gefunden" nicht von "darf nicht nachsehen" unterscheiden.
        return jsonify(ok=True, banned=f2b.get("total_banned", 0), f2b_ok=f2b.get("ok"),
                       f2b_status=f2b.get("status"),
                       f2b_hint=(None if f2b.get("ok") else f2b.get("hint")),
                       f2b_fix=(None if f2b.get("ok") else f2b.get("fix")),
                       attacks_total=atk.get("total", 0), unique_ips=atk.get("unique_ips", 0),
                       attacks_ok=atk.get("ok"), attacks_status=atk.get("status"),
                       attacks_source=atk.get("source"),
                       attacks_hint=(None if atk.get("ok") else atk.get("hint")),
                       attacks_fix=(None if atk.get("ok") else atk.get("fix")),
                       geo_error=(_DEFENSE_GEO_ERR or None),
                       top_countries=[{"country": c, "hits": n} for c, n in top_countries],
                       server={"lat": DEFENSE_SERVER_LAT, "lon": DEFENSE_SERVER_LON})
    except Exception as e:
        return jsonify(ok=False, error=str(e)), 500


# ═══════════════════════════════════════════════════════════════════════════
# B138: SELBSTTEST — eine Antwort auf "was ist kaputt und was tut man dagegen"
# ═══════════════════════════════════════════════════════════════════════════
# Die Diagnosedaten existierten schon, lagen aber in fuenf Log-Greps und drei
# Panels verstreut: Kick-Key-Herkunft im Startlog, YouTube-Grund im
# Restream-Deck, CrowdSec-Status im Abwehr-Panel, gestoerte Schleifen nur im
# journalctl. Wer wissen wollte, warum nichts sendet, musste alle fuenf
# kennen. Hier laufen sie zusammen — jeder Befund mit dem Befehl, der ihn
# behebt. Bewusst KEINE neue Datenerhebung: nur Zusammenfuehrung.

def _st_befund(liste, schwere, bereich, befund, fix=None):
    """schwere: 'rot' (sendet nicht / Datenverlust) | 'gelb' (eingeschraenkt)."""
    liste.append({"schwere": schwere, "bereich": bereich,
                  "befund": befund, "fix": fix})


@dashboard_app.route("/api/selftest")
def api_selftest():
    """Aggregierte Selbstdiagnose. Ueber den SSH-Tunnel:
       curl -s localhost:8050/api/selftest | python3 -m json.tool"""
    b = []
    try:
        # ── gestoerte Dauerschleifen ────────────────────────────────────
        # Das Wertvollste hier: _LOOP_FEHLER weiss, WELCHE Schleife klemmt.
        # Faellt _backup_loop aus, laufen Backups nicht — das sah man bisher
        # nirgends, weil die Schleifen auf log.debug abfingen.
        for name, st in sorted(_LOOP_FEHLER.items()):
            alter = _time_mod.monotonic() - st[0]
            _st_befund(b, "rot", "Schleife",
                       f"{name} ist gestoert (letzte Meldung vor {int(alter)}s, "
                       f"{st[1]} weitere unterdrueckt)",
                       f"journalctl -u tiktok-bot | grep 'Schleife {name}'")

        # ── Restream: sendet ueberhaupt etwas? ──────────────────────────
        laeuft = sorted((_RESTREAM_MGR._procs or {}).keys())
        ziele = [n for n, _u in _nc_rst.active_targets()]   # v4.0-W77
        if not laeuft:
            _st_befund(b, "gelb", "Restream", "kein Restream aktiv",
                       "Normal, wenn gerade keine Quelle live ist.")

        # ── Encoder-Rueckstand: CPU-gebunden oder nicht? ────────────────
        # Die entscheidende Zahl bei "der Restream laggt". ffmpeg meldet
        # speed=1.0x, wenn es Echtzeit schafft. Faellt der Wert darunter,
        # kommt der Encoder NICHT hinterher — dann ist es wirklich CPU.
        # Bleibt er bei ~1.0x und es ruckelt trotzdem, ist es Puffer oder
        # Netz, und mehr CPU aendert nichts. Ohne diese Unterscheidung dreht
        # man an den falschen Schrauben.
        for rid, info in sorted((_RESTREAM_MGR._procs or {}).items()):
            h = info.get("health") or {}
            sp = h.get("speed")
            langsam = h.get("slow_ticks", 0)
            try:
                spf = float(str(sp).rstrip("x")) if sp else None
            except (TypeError, ValueError):
                spf = None
            if spf is not None and spf < 0.95:
                _st_befund(b, "rot", "Encoder",
                           f"Restream #{rid}: ffmpeg schafft nur {sp} Echtzeit "
                           f"({langsam} langsame Takte) — CPU-gebunden, das Bild "
                           f"laeuft dem Encoder davon",
                           "FFMPEG_THREADS_LIVE erhoehen (Default 3, bei tee laeuft "
                           "nur EIN Encoder) oder RESTREAM_BITRATE_K senken")
            elif langsam >= 3:
                _st_befund(b, "gelb", "Encoder",
                           f"Restream #{rid}: {langsam} langsame Takte, aktuell {sp}",
                           "Grenzwertig — bei Lastspitzen reisst es ab.")
            if info.get("transcode"):
                _st_befund(b, "gelb", "Encoder",
                           f"Restream #{rid} laeuft im Transcode (kostet CPU). "
                           f"Ziele: {', '.join(ziele) or '?'}",
                           "Nur EIN Ziel? Dann ist Transcode vermeidbar. Mehrere "
                           "Ziele erzwingen ihn (RESTREAM_MULTI_ALLOW_COPY=0).")

        # ── Kick: welcher Ausgang ist tot? ──────────────────────────────
        for zielname, tf in _RESTREAM_MGR.tee_fehler().items():   # v4.0-W116
            alter = _time_mod.time() - (tf.get("ts") or 0)
            if alter < 3600:
                _st_befund(b, "rot", "Restream",
                           f"ffmpeg meldet Ziel '{zielname}' abgelehnt "
                           f"(vor {int(alter)}s): {(tf.get('msg') or '')[:160]}",
                           "journalctl -u tiktok-bot | grep 'Kick-Ziel:' "
                           "— zeigt Ingest und Key-Herkunft (db schlaegt .env)")

        # ── YouTube ─────────────────────────────────────────────────────
        yt_grund = _YT_INGEST_CACHE.get("reason") or ""
        # Bodenwahrheit zuerst: steht YouTube wirklich in der Zielliste? Alles
        # andere ist Absicht, das hier ist Wirkung. multistream_targets()
        # verlangt enabled UND ingest UND key — faellt eines aus, fehlt das
        # Ziel im tee, ohne dass irgendwo "YouTube" auftaucht.
        if YOUTUBE_ENABLED and YOUTUBE_STREAM_KEY and "youtube" not in ziele:
            fehlt = []
            if not YOUTUBE_INGEST_URL:
                fehlt.append("YOUTUBE_INGEST_URL ist leer")
            if not _nc_rst._CFG.get("youtube_enabled"):
                fehlt.append("youtube_enabled im Restream-Modul steht auf False")
            if not _nc_rst._CFG.get("youtube_key"):
                fehlt.append("youtube_key im Restream-Modul ist leer "
                             "(wurde von _youtube_restream_autoconfig geleert?)")
            _st_befund(b, "rot", "YouTube",
                       "YOUTUBE_ENABLED=1 und YOUTUBE_STREAM_KEY gesetzt, aber "
                       "YouTube ist KEIN Sendeziel. " + ("; ".join(fehlt) or
                       "Grund unklar — .env nach dem Setzen neu geladen? "
                       "Modul-Konstanten werden nur beim Start gelesen."),
                       "sudo systemctl restart tiktok-bot   # .env wirkt erst "
                       "nach Neustart")
        if YOUTUBE_ENABLED and not YOUTUBE_STREAM_KEY:
            if not _YT_INGEST_CACHE.get("key"):
                _st_befund(b, "rot", "YouTube",
                           f"kein Stream-Key aufgeloest: {yt_grund or 'noch nicht versucht'}",
                           "In YouTube Studio einen Live-Stream anlegen, dann: "
                           "curl -s localhost:8050/api/restream/deck")
            elif not _YT_INGEST_CACHE.get("bound"):
                _st_befund(b, "gelb", "YouTube",
                           "sendet auf den persistenten Key — kein aktiver oder "
                           "geplanter Broadcast gefunden. Bild erscheint erst, "
                           "wenn YouTube den Broadcast selbst startet.",
                           "In YouTube Studio den Stream starten.")
        elif not YOUTUBE_ENABLED:
            _st_befund(b, "gelb", "YouTube", "YOUTUBE_ENABLED=0",
                       "In der .env auf 1 setzen und Dienst neu starten.")

        # ── Ingest-Adressen auf offensichtlich Falsches pruefen ─────────
        # Aus dem echten error.log: rtmp://live.twitch.tv/app/<key> — das ist
        # Twitchs WEBserver, kein RTMP-Ingest. ffmpeg meldet darauf nur
        # "Input/output error"; dass die Adresse selbst falsch ist, sieht man
        # der Meldung nicht an. Solche Adressen sind statisch pruefbar.
        if TWITCH_ENABLED and TWITCH_INGEST_URL:
            _t = TWITCH_INGEST_URL.lower()
            if "contribute.live-video.net" not in _t:
                _st_befund(b, "rot", "Twitch",
                           f"TWITCH_INGEST_URL zeigt auf '{TWITCH_INGEST_URL}' — "
                           "Twitch nimmt RTMP nur auf *.contribute.live-video.net "
                           "an. Jede andere Adresse endet in 'Input/output error'.",
                           "TWITCH_INGEST_URL=rtmp://ingest.global-contribute."
                           "live-video.net/app  (dann Dienst neu starten)")
        if KICK_INGEST_URL and not KICK_INGEST_URL.lower().startswith(("rtmp://", "rtmps://")):
            _st_befund(b, "rot", "Kick",
                       f"KICK_INGEST_URL ist keine RTMP-Adresse: {KICK_INGEST_URL}",
                       "Im Kick-Dashboard die Ingest-URL kopieren (rtmps://…).")

        # ── Quell-URL-Ablauf: Telemetrie, kein Fehler ───────────────────
        for rid, n in sorted((_RESTREAM_MGR._srcexpired or {}).items()):
            if n >= 3:
                _st_befund(b, "gelb", "Quelle",
                           f"Restream #{rid}: TikTok-Quell-URL lief {n}x ab und "
                           "wurde jedesmal erneuert — der Stream laeuft, es "
                           "kostet nur je ~2s Unterbrechung",
                           "Normal. Nur wenn es im Minutentakt passiert, lohnt "
                           "ein Blick auf RECORD_PROXY.")

        # ── AZRAEL: antwortet er auf Ansprache? ─────────────────────────
        # AZRAEL_CHAT_REPLY steht per Default auf 0 — dann gibt der Gate
        # _azrael_chat_should_reply() sofort False zurueck und AZRAEL
        # schweigt auf Kick, Twitch UND YouTube. Von aussen sieht das aus
        # wie ein kaputter Bot, ist aber eine nie gesetzte Variable.
        if not AZRAEL_CHAT_REPLY:
            _st_befund(b, "gelb", "AZRAEL",
                       "antwortet NICHT auf Ansprache im Stream-Chat "
                       "(AZRAEL_CHAT_REPLY=0) — betrifft Kick, Twitch und "
                       "YouTube gleichzeitig",
                       "AZRAEL_CHAT_REPLY=1 in die .env, dann Dienst neu starten")

        # ── AZRAEL: kommt er ueberhaupt ins Publikum? ───────────────────
        # Lange unbemerkt: die Reaktionen liefen in Stimme, Overlay, Dashboard
        # und Discord, aber in keinen Stream-Chat. Wenn kein Kanal sendefaehig
        # ist, soll das hier stehen und nicht erst auffallen, wenn jemand die
        # Chats vergleicht.
        if AZRAEL_REACT_TO_CHAT:
            _kanaele = []
            if _KICK_MOD:
                _kanaele.append("kick")
            if _TWITCH_SEND.get("fn"):
                _kanaele.append("twitch")
            if _YT_SEND.get("fn"):
                _kanaele.append("youtube")
            if not _kanaele:
                _st_befund(b, "rot", "AZRAEL",
                           "kein Stream-Chat sendefaehig — Reaktionen erscheinen "
                           "nur in Overlay/Stimme/Discord, nicht im Chat",
                           "Kick: KICK_CLIENT_ID/SECRET · Twitch: OAuth im "
                           "Dashboard verbinden · YouTube: aktiver Live-Chat")
            elif len(_kanaele) < 3:
                _st_befund(b, "gelb", "AZRAEL",
                           f"sendet nur nach: {', '.join(_kanaele)}",
                           "Die fehlenden Kanaele sind nicht verbunden.")

        # ── Abwehr ──────────────────────────────────────────────────────
        try:
            f2b = _crowdsec_status()
            if not f2b.get("ok"):
                _st_befund(b, "gelb", "Abwehr",
                           f"CrowdSec: {f2b.get('hint') or f2b.get('error')}",
                           f2b.get("fix"))
            atk = _parse_ssh_attacks()
            if not atk.get("ok"):
                _st_befund(b, "gelb", "Abwehr",
                           f"Auth-Log: {atk.get('hint') or atk.get('error')}",
                           atk.get("fix"))
        except Exception as e:
            _st_befund(b, "gelb", "Abwehr", f"Abwehr-Pruefung selbst gescheitert: {e}")

        # ── Herzschlaege: schweigt ein Kern-Loop? ───────────────────────
        now = _time_mod.monotonic()
        for name, last in sorted((_HEARTBEATS or {}).items()):
            still = now - last
            if still > 900:
                _st_befund(b, "rot", "Herzschlag",
                           f"{name} meldet sich seit {int(still)}s nicht mehr",
                           "journalctl -u tiktok-bot -n 200 --no-pager")

        # ── Platte ──────────────────────────────────────────────────────
        try:
            # shutil, nicht _sh: '_sh' ist nur ein lokaler Alias innerhalb von
            # _alert_monitor_loop und hier nicht sichtbar.
            du = shutil.disk_usage(RECORDINGS_DIR if os.path.isdir(RECORDINGS_DIR) else "/")
            pct = 100 * (du.total - du.free) / du.total if du.total else 0
            if pct >= 90:
                _st_befund(b, "rot", "Platte", f"zu {pct:.0f}% voll",
                           "curl -X POST localhost:8050/api/system/cleanup")
            elif pct >= 80:
                _st_befund(b, "gelb", "Platte", f"zu {pct:.0f}% voll")
        except Exception:
            pass

        rot = sum(1 for x in b if x["schwere"] == "rot")
        return jsonify(
            ok=True,
            urteil=("kaputt" if rot else ("eingeschraenkt" if b else "gesund")),
            befunde=b, anzahl_rot=rot, anzahl_gelb=len(b) - rot,
            kontext={
                "restreams_aktiv": laeuft,
                "restream_ziele": ziele,
                "youtube": {"aktiviert": bool(YOUTUBE_ENABLED),
                            "key_quelle": ("env" if YOUTUBE_STREAM_KEY
                                           else (_YT_INGEST_CACHE.get("source") or "")),
                            "broadcast": _YT_INGEST_CACHE.get("broadcast", ""),
                            "grund": yt_grund},
                "db_backend": DB_BACKEND,
                "schleifen_gestoert": sorted(_LOOP_FEHLER.keys()),
            })
    except Exception as e:
        log.error("api_selftest: %s", e, exc_info=True)
        return jsonify(ok=False, error=str(e)), 500


